window.POEM_DB=window.POEM_DB||{};POEM_DB["song_029"]={"n":"吕本中","dyn":"宋","poems":[{"t":"再和兼寄奉符大有叔","f":"七言律诗","c":["血气侵凌不复豪，往来攲倒似乘涛。","宁知懒过嵇中散，亦有诗如谢法曹。","旧稿只堪供酱瓿，故人相赠有绨袍。","兖州宾主同风味，恶句烦公更一薅。"]},{"t":"连州阳山归路三绝 其二","f":"七言绝句","c":["稍离烟瘴近湘潭，疾病衰颓已不堪。","儿女不知来避地，强言风物胜江南。"]},{"t":"海陵病中 其一","f":"七言绝句","c":["病知前路资粮少，老觉平生事业非。","无数青山隔沧海，与谁同往却同归。"]},{"t":"兵乱后自嬄杂诗 其一","f":"五言律诗","c":["晚逢戎马际，处处聚兵时。","后死翻为累，偷生未有期。","积忧全少睡，经劫抱长饥。","欲逐范仔辈，同盟起义师。"]},{"t":"兵乱后自嬄杂诗 其九","f":"五言律诗","c":["黄事多反覆，萧兰不辨真。","汝为误国贼，我作破家人。","求饱羹无糁，浇愁爵有尘。","往来梁上燕，相顾却情亲。"]},{"t":"兵乱后自嬄杂诗 其十四","f":"五言律诗","c":["蜗舍嗟芜没，孤城乱定初。","篱根留敝屦，屋角得残书。","云路惭高鸟，渊潜羡巨鱼。","客来阙佳致，亲为摘山蔬。"]},{"t":"春日即事二首 其二","f":"七言律诗","c":["病起多情白日迟，强来庭下探花期。","雪消池馆初春后，人倚栏干欲暮时。","乱蝶狂蜂俱有意，兔葵燕麦自无知。","池边垂柳腰肢活，折尽长条为寄谁。"]},{"t":"柳州开元寺夏雨","f":"七言律诗","c":["风雨翛翛似晚秋，鸦归门掩伴僧幽。","云深不见千岩秀，水涨初开万壑留。","钟唤梦回空怅望，人传书到竟沈浮。","面如田字非吾相，莫羡班超封列侯。"]},{"t":"读书","f":"五言律诗","c":["老去有馀业，读书空作劳。","时闻夜虫响，每伴午鸡号。","久静能忘病，因行得出遨。","胡为良自苦，膏火自煎熬。"]},{"t":"雪后","f":"七言律诗","c":["谩遣儿童扫雪开，却穿篱落看春回。","溪山冷淡泥三尺，故旧飘零酒一杯。","近买芒鞋供踏雨，更收藜杖与寻梅。","玉川老去生涯在，时有邻僧送米来。"]},{"t":"暮步至江上","f":"七言律诗","c":["客事久输鹦鹉杯，春愁如接凤凰台。","树阴不碍帆影过，雨气却随潮信来。","山似故人堪对饮，花如遗恨不重开。","雪篱风榭年年事，辜负风光取次回。"]},{"t":"梦","f":"五言绝句","c":["梦入长安道，萋萋尽春草。","觉来春已去，一片池塘好。"]},{"t":"长相思","f":"词","c":["要相忘。","不相忘。","玉树郎君月艳娘。","几回曾断肠。","欲下床。","却上床。","上得床来思旧乡。","北风吹梦长。"]},{"t":"生查子","f":"五言律诗","c":["残春雾雨馀，小院黄昏后。","说道觅新词，把酒来相就。","酴醾插髻云，岁岁长如旧。","不是做词迟，却怕添伊瘦。"]},{"t":"生查子 其二 离思","f":"五言律诗","c":["人分南浦春，酒把阳关盏。","衣带自无情，顿为离人缓。","愁随苦海深，恨逐前峰远。","更听断肠猿，一似闻弦雁。"]},{"t":"生查子 其一 离思","f":"五言律诗","c":["双双小凤斜，淡淡鸦儿稳。","一曲渭城歌，柳色饶春恨。","离觞洗别愁，酒尽愁难尽。","宝瑟雁纵横，谁寄天涯信。"]},{"t":"如梦令 忆旧","f":"词","c":["海雁桥边春苦。","几见落花飞絮。","重到柳行西，懒问画楼何处。","凝伫。","凝伫。","十顷荷花风雨。"]},{"t":"西江月 其二","f":"词","c":["酒罢悠扬醉兴。","茶烹唤起醒魂。","却嫌仙剂点甘辛。","冲破龙团气韵。","金鼎清泉乍泻，香沈微惜芳熏。","玉人歌断恨轻分。","欢意厌厌未尽。"]},{"t":"西江月 其一","f":"词","c":["渺渺风吹月上，濛濛雾挟霜回。","百年心事老相催。","人在夕阳落外。","有梦常嫌去远，无书可恨来迟。","一杯浊酒两篇诗。","小槛黄花共醉。"]},{"t":"采桑子 其一","f":"词","c":["恨君不似江楼月，南北东西，南北东西，只有相随无别离。","恨君却似江楼月，暂满还亏，暂满还亏，待得团圆是几时？"]},{"t":"采桑子 其二","f":"词","c":["乱红夭绿风吹尽，小市疏楼。","细雨轻鸥。","总向离人恨里收。","年年春好年年病，妾自西游。","水自东流。","不似残花一样愁。"]},{"t":"南歌子","f":"词","c":["驿路侵斜月，溪桥度晓霜。","短篱残菊一枝黄。","正是乱山深处、过重阳。","旅枕元无梦，寒更每自长。","只言江左好风光。","不道中原归思、转凄凉。"]},{"t":"宣州竹/虞美人 墨梅","f":"词","c":["小溪篷底湖风重。","吹破凝酥动。","一枝斜映庾门深。","冷淡无言香泛、月华清。","已经轻瘦谁为共。","魂绕徐熙□。","耻同桃李困春容。","肯向毫端开发、雨云中。"]},{"t":"浣溪沙 其一","f":"七言古诗","c":["暖日温风破浅寒。","短青无数簇幽栏。","三年春在病中看。","中酒心情浑似梦，探花时候不曾闲。","几年芳信隔秦关。"]},{"t":"浣溪沙 其二","f":"七言古诗","c":["共饮昏昏到暮鸦。","不须春日念京华。","迩来沈醉是生涯。","不是对君犹惜醉，只嫌春病却怜他。","愿为蜂采落残花。"]},{"t":"清平乐 其二","f":"词","c":["柳塘新涨。","艇子操双桨。","闲倚曲楼成怅望。","是处春愁一样。","傍人几点飞花。","夕阳又送栖鸦。","试问画楼西畔，暮云恐近天涯。"]},{"t":"浪淘沙令 其一","f":"词","c":["柳色过疏篱。","花又离披。","旧时心绪没人知。","记得一年寒食下，独自归时。","归后却寻伊。","月上嫌迟。","十分斟酒不推辞。","将为老来浑忘却，因甚沾衣。"]},{"t":"减字木兰花","f":"词","c":["去年今夜。","同醉月明花树下。","此夜江边。","月暗长堤柳暗船。","故人何处。","带我离愁江外去。","来岁花前。","又是今年忆去年。"]},{"t":"清平乐","f":"词","c":["故人何处。","同在江南路。","百种旧愁分不去。","枉被落花留住。","旧愁百种谁知。","除非是见伊时。","最是一春多病，等闲过了酴醾。"]},{"t":"渔家傲","f":"词","c":["小院悠悠春未远。","牡丹昨夜开犹浅。","珍重使君帘尽卷。","风欲转。","绿阴掩映栏干晚。","记得旧时清夜短。","洛阳芳讯时相伴。","一朵姚黄䯳髻满。","情未展。","新来衰病无人管。"]},{"t":"菩萨蛮 其一","f":"词","c":["客愁不到西池路。","残春又逐花飞去。","今日傍池行。","新荷昨夜生。","故人千虑绕。","不道书来少。","去住隔关河。","长亭风雨多。"]},{"t":"菩萨蛮 其三","f":"词","c":["登楼一望南山雪。","使君风味如新月。","月向雪前明。","主人今夜情。","平生相与意。","老病犹堪记。","对酒为君欢。","酒杯嫌未宽。"]},{"t":"菩萨蛮 其二","f":"词","c":["高楼只在斜阳里。","春风淡荡人声喜。","携客不嫌频。","使君如酒醇。","花光人不会。","月色须君醉。","月色与花光。","共成今夜长。"]},{"t":"朝中措","f":"词","c":["病香无力傍栏干。","风雨送春还。","一枕晓来清梦，无人说似西山。","匆匆笑语，时时邂逅，草草杯盘。","莫谓杂花时候，便忘梅蕊冲寒。"]},{"t":"满江红","f":"词","c":["东里先生，家何在、山阴溪曲。","对一川平野，数间茅屋。","昨夜冈头新雨过，门前流水清如玉。","抱小桥、回合柳参天，摇新绿。","疏篱下，丛丛菊。","虚檐外，萧萧竹。","叹古今得失，是非荣辱。","须信人生归去好，世间万事何时足。","问此春、春酝酒何如，今朝熟。"]},{"t":"虞美人 其二","f":"词","c":["平生臭味如君少。","自是君难老。","似侬憔悴更谁知。","只道心情、不似少年时。","春风也到江南路。","小槛花深处。","对人不是忆姚黄。","实是旧时风味、老难忘。"]},{"t":"虞美人 其一","f":"词","c":["梅花自是于春懒。","不是春来晚。","看伊开在众花前。","便道与春无分、结因缘。","风前月下频相就。","笑我如伊瘦。","几回冲雨过疏篱。","已见一番青子、缀残枝。"]},{"t":"蝶恋花 春词","f":"词","c":["巧语娇莺春未暮。","杨柳风流，恰过池塘雨。","芳草满庭花满树。","无情胡蝶飞来去。","睡起小奁香一缕。","玉篆回纹，等个人分付。","桃叶不言人不语。","眉尖一点君知否。"]},{"t":"踏莎行","f":"词","c":["雪似梅花，梅花似雪。","似和不似都奇绝。","恼人风味阿谁知？","请君问取南楼月。","记得去年，探梅时节。","老来旧事无人说。","为谁醉倒为谁醒？","到今犹恨轻离别。"]},{"t":"墨梅","f":"七言古诗","c":["岭南十月春渐回，妍暖先到前村梅。","问君何处得此妙，一枝冷艳随霜开。","长江凛凛欲奔岸，乃见好事移墙隈。","初疑渗漉入瘴雾，更欲寂寞埋烟煤。","微风不动暗香远，淡月入户空徘徊。","坐看粉黛化腐恶，岂但桃李成舆台。","我行万里厌穷独，疾病未已心先灰。","对此不觉三叹息，恐是转侧同南来。","异乡久处少意绪，破壁相对无根荄。","古来寒士每如此，一世埋没随蒿莱。","遁光藏德老不耀，肯与世俗相追陪。","轮囷离奇多见用，牺尊青黄未为灾。","含毫吮墨去颜色，况自不必须穿栽。","岁穷路远莫惆怅，此去保无蜂蝶猜。"]},{"t":"题孙子绍所藏王摩诘渡水罗汉","f":"七言古诗","c":["问渠褰裳欲何往，彷徨徙倚沧波上。","至人入水固不濡，何以有此恐怖状。","我知摩诘意未真，欲以笔端调世人。","此水此渡俱非实，摩诘亦未尝下笔。","孙郎宝藏今几年，往来周旋兵火间。","世人险阻更百难，彼渡水者安如山。","请君但作如此观，莫更思维寻笔端。"]},{"t":"题张君墨竹","f":"七言律诗","c":["张卿画竹今成癖，笑语挥毫不作难。","欻见高标起萧瑟，坐令炎暑变荒寒。","笔头似有千年韵，胸次犹须万斛宽。","岁晚雪霜君记取，此君怀抱要重看。"]},{"t":"阴","f":"七言律诗","c":["凉风森爽遽如许，天气萧条殊未佳。","密径留阴□□竹，败畦藏雨斗蛙蟆。","碧云莫合人千里，丹凤□□天一涯。","唯有双丛庭下菊，殷勤还作去年花。"]},{"t":"符离诸贤诗","f":"五言古诗","c":["穷居日荒凉，杜门与世绝。","亲故日夜疏，诗书固宜缺。","符离虽陋邦，贤士稍罗列。","德操青云器，议论辈前哲。","外貌发英华，中心瑩冰雪。","介然特立士，劲气刚于铁。","攘臂辩是非，孰能逃区别。","信民粹而和，名利诚难悦。","汩没稠人中，独抱云松节。","伟哉二三子，实乃邦家杰。","我来从之游，内顾惭疏拙。","欣然对三益，放怀歌数阕。","已矣不须言，渠当为君说。"]},{"t":"德操充之皆约九月间见过今皆未至扶杖出门悠然有感","f":"七言律诗","c":["病着文书懒出门，偶扶藜杖看行云。","屋头日在转花影，水面风来散縠纹。","不厌莫城千嶂合，稍令明月万家分。","小庭留得清秋在，已见霜红未见君。"]},{"t":"游刘氏园","f":"七言绝句","c":["暖日温风破浅寒，短青无数簇幽兰。","三年止酒偿春意，可忍花梢带面看。"]},{"t":"上元","f":"七言绝句","c":["步屧荒园日已昏，呼儿当径扫苔痕。","春愁不作游人地，细雨残梅过上元。"]},{"t":"柳","f":"七言绝句","c":["含烟带雨过平桥，袅袅千丝复万条。","张令当年缘底事，风流才似女儿腰。"]},{"t":"喜雨","f":"七言律诗","c":["天乞幽人一夜凉，故教微雨送斜阳。","暝阴笼树山更好，爽气侵人土自香。","多病不眠唯药裹，居闲长坐只绳床。","五年谬作江湖客，几对鲈鱼忆故乡。"]},{"t":"舍东旧有花数百株自去岁大雨道路阻绝不复可寻感叹成诗","f":"七言绝句","c":["无数新花替旧丛，兔葵高卧占春风。","向来桃李成蹊处，今在陂塘渺莽中。"]},{"t":"送文潜归因成一绝奉寄","f":"七言绝句","c":["水天空阔片帆开，野岸萧条送骑回。","重到张公泊船处，小亭春在锁青苔。"]},{"t":"谢人送牡丹","f":"七言绝句","c":["晚风初染嫩鹅黄，小雨仍添百和香。","折与病夫元不称，玉瓶留待冶游郎。"]},{"t":"宿州初暑","f":"七言律诗","c":["暑气侵人始欲愁，箪瓢穷巷不堪忧。","乱蝉泊雨林塘静，密径吹花草树幽。","春尽茅檐深着燕，日高田水故飞鸥。","莫欺湫隘无馀地，待借元龙百尺楼。"]},{"t":"夏日书事","f":"五言古诗","c":["小行畏蛇蝎，端坐困蚊蚋。","终日方丈间，茫然但昏睡。","岂唯供病本，兼恐添药费。","小园新雨馀，蔬畦共风味。","饱闻应门柳，清阴妙无对。","便思携杖往，行歌当游戏。","千秋陶渊明，此意渠亦会。"]},{"t":"寄吉州若谷叔","f":"七言绝句","c":["念我江西老斲轮，久无漫鼻与挥斤。","千金莫买蛾眉笑，留寄溪堂病主人。"]},{"t":"寄汪信民","f":"七言绝句","c":["万里江南雨外船，长腰粳米缩头鳊。","广文繫马无由去，更有何人赠酒钱。"]},{"t":"同诸子游城东园","f":"五言古诗","c":["昔闻城东园，欲往常不款。","今来天气佳，茶瓯起衰懒。","杖藜出门去，如膜开病眼。","木叶犯新霜，瓜田带馀暖。","川源疑有无，风云递舒卷。","不期鱼鸟会，偶逐鸥鹭远。","浅水乱菰蒲，荒亭秀苔藓。","青山近在望，更悟秋意晚。","同行二三子，诗语各萧散。","不愁罚觞难，苦恨白日短。","千秋高阳池，令人忆山简。"]},{"t":"杨道孚墨竹歌","f":"词","c":["君不见渭川之阴卧龙横千秋，貌取者谁文湖州。","十年笔意闭黄壤，只今妙手唯杨侯。","杨侯画竹尽真迹，功夺造化令人愁。","满堂回头看下笔，扰扰云烟乱晴日。","大丛纵横高入云，斜风落叶秋纷纷。","小丛攲倾病无力，傍水长根走苍石。","门前车马汗成川，何得阴风动高壁。","杨侯嘻笑辞未工，此意不与丹青同。","粉黛初数无一钱费，酒炙能使千家空。","袜材远寄动盈屋，我子画无由穷。","剡溪寒藤不难致，须君放手为双丛。","须君放手为双丛，与我俱隐南山中。"]},{"t":"谢无逸秦处度诸人皆许省试后见访冬夜有怀作此诗寄之","f":"五言古诗","c":["八年去东都，触事无一好。","沈绵淹岁时，忧虞满怀抱。","欲归故里闾，稀复旧耆老。","悠悠岁欲尽，忽忽身向老。","小堂佳有馀，所恨来不早。","饥虫语夜霜，疏星乱衰草。","支撑坏壁高，侧转寒木小。","诗书久弃置，词林迹如扫。","佳人何时来，路远音信少。","庭前冬开花，扶杖起千绕。","春风回马首，清尊待君倒。","先期留酒钱，仍须具梨枣。"]},{"t":"岁晚","f":"五言律诗","c":["野竹新开径，疏篱自著行。","暮寒收雨雪，落日散牛羊。","生事颜公拙，才名谢奕狂。","药囊无奈汝，春到莫相妨。"]},{"t":"晚步至江上","f":"七言律诗","c":["浦口生春绿未酣，南山初见碧崭岩。","风声入树翻归鸟，月影浮江倒客帆。","破甑不堪充酒券，短蓑真欲换朝衫。","往来泥雨城南路，可见轻鸥定不凡。"]},{"t":"访晁进道归","f":"七言律诗","c":["树阴残雪半成泥，尚想狂花一尺围。","小雨似酥黄草尽，澄江如练白鸥飞。","未辞酒炙为公费，政恐亲知见面稀。","南市津头行艓子，无人识我醉中归。"]},{"t":"怨歌行","f":"词","c":["借君手中板，为君歌一辞。","辞中宛转君不晓，为君说尽长相思。","轻霜夜度吴城暖，枫叶芦花秋意晚。","万里春随驿使归，十年梦逐佳人远。","当时笑语似儿剧，象床玉手无消息。","古岸风江千里船，咫尺春愁那得怜。","君不见信陵门下客，侯嬴不用今头白。"]},{"t":"雪尽","f":"五言律诗","c":["雪尽寒仍在，园荒春欲归。","晴空落雁小，古木聚鸦稀。","肺病犹堪酒，囊空合典衣。","碧云愁不见，千里故山薇。"]},{"t":"三月一日泊舟宿州城外因纵步至城北遂过天庆观道士留饮乃归","f":"五言古诗","c":["冰霜连暮春，既雨寒愈重。","扁舟缆荒亭，浅水咽微冻。","今晨稍和柔，始觉芳意动。","经旬厌拘束，乐事须一纵。","篮舆无俗情，鸱夷当宾从。","千花犯浓云，红紫相饯送。","未知滕薛长，乃若邹鲁鬨。","娉婷北门柳，别泪作凄痛。","陵陂少荒芜，亦未妨耕种。","道人喜我来，清谈破昏梦。","弹琴不须弦，风林助吟讽。","嫩玉捣香粳，浮蛆拨春瓮。","嘉蔬剪朝露，奇果市新贡。","西邻亦可人，明窗碾双凤。","人生一饱适，此外更何用。","七年城北交，事与朱阮共。","长诗不成篇，临行当三弄。","琼瑶报木桃，为子末后供。"]},{"t":"宿青阳驿","f":"五言律诗","c":["灯火客帆尽，人烟村市幽。","晚风号古木，高岸束黄流。","物色淮山近，春光雾雨愁。","栖迟旧游地，来豁十年忧。"]},{"t":"游南山归简张嘉父博士","f":"五言律诗","c":["吾生复何往，乐事亦匆匆。","宝塔千帆外，春城万壑中。","乱花缘侧径，晚照落晴空。","坐想西仓老，掀髯一笑同。"]},{"t":"书怀","f":"七言绝句","c":["拄腹文章未补饥，积瘕潜愧不堪悲。","儿曹怪我疏愚甚，不见田光盛壮时。"]},{"t":"客居书怀奉寄介然若谷才仲兼简信民","f":"五言古诗","c":["客愁如长河，浩荡去不息。","未来已相关，千里在咫尺。","抱疾寄他乡，终年守岑寂。","中虚耗神志，内热损筋力。","长虞二竖撄，复有寒馁迫。","怪渠甑上烟，愧尔囊中帛。","平生所读书，已如不相识。","坐贻乡党笑，敢辞尘埃没。","旧游今几时，转眄忽陈迹。","死者不复见，墓草春已碧。","生者天一涯，未免陈蔡厄。","儿曹乳臭在，瞑目分黑白。","虽无未见书，颇多雌黄笔。","出言辄周孔，而不辨菽麦。","啾啾要酬和，内顾颇牵率。","坐令怀抱恶，更觉天宇窄。","忽忽十年事，俯仰同戏剧。","从来肺腑亲，翻手胡与越。","独馀二三子，肝胆犹铁石。","尚怪东郭贫，亦讶怀祖黠。","西轩来何时，箪瓢共饥渴。","念君不能已，一饭再三噎。","谁能明予心，皎皎霜夜月。"]},{"t":"小园","f":"五言律诗","c":["小园常在眼，春事已天涯。","雨暗堤前路，苔深林外家。","曲池通小径，密树隐残花。","长愧邻翁酒，囊空尚可赊。"]},{"t":"谒雍道士","f":"七言律诗","c":["纷纷乾没混泥沙，暂遣尘言挂齿牙。","妙画已归三语掾，壮游空记五侯家。","古坛背日藏芳草，小树留春放晚花。","能共山翁同活计，隔林分听一池蛙。"]},{"t":"春日即事二首 其一","f":"楚辞体","c":["隐几虚堂俗客稀，片心真与道相宜。","风摇柳带千丝乱，雨勒花心十日期。","瘦病才苏休强酒，良辰虽好少题诗。","贾生词赋常流落，归去来兮在几时。"]},{"t":"寄前镇西杨法曹","f":"七言律诗","c":["杨子文章老更新，狂吟寡和过阳春。","双声叠韵俱难敌，指物程形似有神。","画马已无韩干肉，草书真得伯英筋。","可怜一首闲居赋，解道连蜷能几人。"]},{"t":"饮酒","f":"七言古诗","c":["人生百岁能几何，顾我把酒胡不歌。","穷通大抵梦南柯，我复梦中多蹉跎。","自古英雄亦何有，往事纷纷不如酒。","嗟予真得酒中趣，几度尊前揖星斗。","病起槐阴鹦已老，今日相逢还草草。","匆匆数日是行人，且向尊前一倾倒。","人生乐事亦难并，明月清风况都好。"]},{"t":"读史","f":"五言律诗","c":["陈寿谓诸葛，将略非所长。","私恨写青史，千古何茫茫。","谤议终自破，公论不可当。","是非倘可定，青蝇果何伤。"]},{"t":"戏呈七十七叔","f":"五言律诗","c":["大阮爱我诗，谓我能诗矣。","我诗来无极，爱之终不已。","吾非圣者也，但智虑多耳。","赐始可言诗，吾智由商起。"]},{"t":"偶作","f":"七言绝句","c":["去年芳草又萋萋，休叹王孙犹未归。","更见春深送春雁，三三两两傍云飞。"]},{"t":"谒陶朱公庙","f":"七言绝句","c":["悠悠千载五湖心，古庙无人锁绿阴。","为问功成肥遁后，不知何术累千金。"]},{"t":"睡","f":"七言绝句","c":["终日题诗诗不成，融融午睡梦频惊。","觉来心绪都无事，墙外啼莺一两声。"]},{"t":"读陶元亮传 其一","f":"五言绝句","c":["我爱陶彭泽，解言归去来。","醉眠犹遣客，却使世人猜。"]},{"t":"读陶元亮传 其二","f":"五言绝句","c":["我爱陶彭泽，不求弦上声。","琴中如有趣，曾遣几人听。"]},{"t":"寄璧上人","f":"五言古诗","c":["出门厌交情，袖手看世故。","纷纷驹过隙，忽忽豹隐雾。","生平喜退缩，未到心已悟。","尚馀好事人，相就讨新句。","虽非琢肝肾，终自费调护。","君看雪霜根，岂受桃李妒。","胥疏老支离，肮脏旧宾傅。","何由两行缠，远泛一大瓠。","从君乞妙语，一洗诗酒污。"]},{"t":"寄璧公道友","f":"七言律诗","c":["符离城里相逢处，酒肉如山放手空。","已见神通过鹙子，未应鲜健胜庞公。","且寻扇子旧头角，一任杏花能白红。","破箬笠前江万里，无人曾识此家风。"]},{"t":"用前韵寄商老","f":"七言律诗","c":["先生昔据道玄峰，咳唾珠玉家为空。","只今江西二三子，可到元和六七公。","双鬓只期他日白，千花犹是去年红。","须君吸尽西江水，不假扶摇万里风。"]},{"t":"又寄无逸信民","f":"七言律诗","c":["文字撑肠不疗穷，诗来想见左书空。","虽非问道暏狂屈，犹胜遗书访子公。","银杯久拚浮大白，桃花且看舒小红。","记取浮杯无剩语，他年说似马牛风。"]},{"t":"奉答璧公兼简诸友","f":"七言律诗","c":["江山取别太匆匆，对面难寻一段空。","顾我自无黄阁样，如君合是黑头公。","客尘衮衮催前浪，俗眼纷纷替旧红。","炙日茅檐那接膝，重来肯借一帆风。"]},{"t":"得李去言诗次韵答之","f":"七言律诗","c":["歌呼屡回曹相国，笺书或似魏司空。","半生怀抱向馀子，千载风流独此公。","未用反身藏白黑，更须着眼辨青红。","无人与助求田费，雅称谢家林下风。"]},{"t":"督山伯萧远和诗并示舍弟","f":"七言律诗","c":["爱闲多病老封戎，看子垂天上碧空。","懒惰未须攀此老，典刑政尔赖诸公。","须如震泽三春渌，诗似芙蕖五月红。","坐此逃禅夫可恕，不应独许我乘风。"]},{"t":"用寄璧上人韵寄范元实赵才仲及从叔知止兼率山伯同赋","f":"七言律诗","c":["故人瓶锡各西东，吾道从来冀北空。","病去渐于文字懒，南来犹觉岁时公。","江回夜雨千岩黑，霜着高林万叶红。","政好还家君未肯，莫教惭愧北窗风。"]},{"t":"夜作呈诸公","f":"五言古诗","c":["风江舞暮帆，野树散归鸟。","寒灯上壁角，疏星缀林杪。","归来静无事，独坐搜默藁。","放笔有新功，无人与倾倒。","不知新恨多，但觉旧愁少。","石鼎倚残炉，茶烟看清袅。","明朝寻酒钱，折简唤诸老。"]},{"t":"山阳宝应道中与汪信民兄弟洪玉父杜子师张益中日夕过从自过高邮不复有此乐也因作此诗寄怀","f":"七言律诗","c":["日日南风沙打围，挂帆端为故人回。","长空渺渺水无际，远树冥冥花自开。","疾病久辜鹦鹉杓，江山稍近凤凰台。","月明雪霁山阴道，尚想王郎乘兴来。"]},{"t":"春日","f":"五言绝句","c":["春风未雌雄，尊酒自贤圣。","燕巢楼阁间，莺语花柳静。"]},{"t":"知止啸傲轩","f":"七言古诗","c":["贪夫九鼎犹不足，渊明一轩长有馀。","人生趋向等天壤，鸱嚇腐鼠猜鹓雏。","中郎妙处世不识，风期自与常人殊。","开轩便有千载韵，友葛天氏无怀徒。","坐看松菊换时节，兔葵桃树纷荣枯。","五年却走各南北，千里怀想空烦纡。","双鱼沈浮久不至，三径寂寞今何如。","文章潦倒付丘壑，疾病蹭蹬思江湖。","何时共坐北风里，烦君小摘园中蔬。"]},{"t":"暑夕乍凉二绝 其一","f":"七言绝句","c":["三旬埃郁得清风，领袖犹翻汗摺红。","已是梦清无俗梦，更移凉簟月明中。"]},{"t":"暑夕乍凉二绝 其二","f":"七言绝句","c":["暮蝉萧瑟下斜阳，已似茅檐气味长。","团扇未须忧弃置，竹奴犹可助清凉。"]},{"t":"寄知止二绝 其一","f":"七言绝句","c":["少年乐事未全谙，疾病侵凌已不堪。","尚喜步兵频入梦，梦中犹复似曹南。"]},{"t":"寄知止二绝 其二","f":"七言绝句","c":["竹林还往风流绝，剡县交游气味疏。","今代高人多惜费，千金未抵一行书。"]},{"t":"游北李园三绝 其一","f":"七言绝句","c":["雨映烟笼万竹蟠，枯条高下不堪看。","非干秋后多霜露，自是芙蓉不耐寒。"]},{"t":"游北李园三绝 其二","f":"七言绝句","c":["去马来舟绝往还，此中情味却相干。","明年知是明寒食，待约花梢月下看。"]},{"t":"游北李园三绝 其三","f":"七言绝句","c":["壁间诗字有凝尘，庭下梅梢又作春。","独有城南汪教授，当时同是看花人。"]},{"t":"游北李园","f":"七言绝句","c":["小径纵横出紫苔，绿阴高下缀黄梅。","榴花却是多情思，留宿薰风未肯开。"]},{"t":"寄李怤去言","f":"七言古诗","c":["东南之望庐山英，李郎落落奇后生。","凤凰麒麟在郊薮，芝兰玉树生阶庭。","文章初如滥觞水，行见万里通沧溟。","汪侯爱君笔不停，谓君诗似秋风清。","世间儿子甘缩手，苏过赵楠俱抗行。","少年才气乃如此，后来定是贤公卿。","伊昔先朝文物盛，君家诸父当朝廷。","外兄复是不世才，奇祥异瑞相辉映。","翻云覆雨十年后，昏昏醉梦须君醒。","我生未壮日向衰，疾病侵凌心已灰。","眼中之人不易见，千变百技常追随。","诗书深藏半鼠矢，笔墨高卧封蛛丝。","功名已矣付公等，田园肯放吾先归。"]},{"t":"赠汪莘叔野","f":"五言古诗","c":["汪子宦不达，四海漫声名。","有弟极磊落，气宇和而清。","三冬文史足，十年书剑成。","出言见瑰颖，府库森五兵。","于身则已拙，泛如池中萍。","轻肥置度外，辛苦抱遗经。","乃知佳子弟，必由贤父兄。","念子初来时，我方疾病撄。","相从四寒暑，所历不可听。","昏昏醉梦里，得君时一醒。","拥炉共残火，软语当杯铛。","君亦不我厌，为我双眼青。","勿云躯干小，气吞横海鲸。","悬榻念文举，开径忆渊明。","二子风流远，感君兄弟情。","穷通有时节，此士尔勿轻。"]},{"t":"新冬","f":"五言古诗","c":["西风吹禾黍，落日在陋巷。","杖藜访新冬，霜树眇空旷。","人烟村舍西，行旅古原上。","晚山晴更好，秀色常在望。","居闲得真趣，日欲就疏放。","岂惟憎俗徒，庶自免嘲谤。","东邻酒初熟，清香乱盆盎。","径须骑墙头，挈榼献穷状。","吾生足羁旅，久病非少壮。","银杯多羽化，布帆且无恙。","虽非陶潜隐，不负徐邈畅。"]},{"t":"赠谢无逸","f":"词","c":["君不见城南千树桃，君不见涧底百尺松。","松生偃蹇卧霜雪，桃李一笑随春风。","百年涧底终自若，桃花犹得暂时红。","呜呼志士每如此，衡门高卧不见用，心虽无瑕饥欲死。"]},{"t":"赠张若虚","f":"五言律诗","c":["病忆江湖去，书无尺寸工。","平时窭人子，忽是富家翁。","活计呻吟里，交情梦寐中。","独于张处士，相近数过从。"]},{"t":"赠信民","f":"五言古诗","c":["五年客符离，端坐受贫病。","从来疏出门，今乃懒成性。","官多豪富郎，分明与时竞。","取醉不论钱，定无尘生甑。","岂但相娱乐，颇复自贤圣。","汪侯虽官居，笑语怯豪横。","折腰众人后，琼林自辉映。","背后足官府，眼前谬恭敬。","偷闲过草堂，遣兴眯眼净。","虽非醉红裙，清谈却差胜。","秋高数能来，勿厌阻泥泞。"]},{"t":"符离行","f":"词","c":["符离之民难与居，五年坐此如囚拘。","比屋生涯但剽劫，诸生学问只乡闾。","南邻经年不相见，北里虽见复粗疏。","窄衣小帽走尘土，也复生貌施襟裾。","对此自然忧气满，疾病日益何由除。","君不见图经所记又可哀，此州自古无贤才。"]},{"t":"探梅呈汪信民","f":"七言律诗","c":["缟带银杯欲着尘，小园幽树已含春。","风流王谢佳公子，臭味曹刘入幕宾。","细朵定无泥土涴，暗香犹带雪霜新。","剩摩枵腹搜奇句，去恼城南得定人。"]},{"t":"奉怀张公潜舍人二首 其一","f":"词","c":["颜子置身陋巷，屈原放迹江湖。","何似我公归去，马羸不厌长途。"]},{"t":"奉怀张公潜舍人二首 其二","f":"词","c":["腕中有万斛力，胸次乃千顷陂。","字画颜行杨草，文章韩笔杜诗。"]},{"t":"答无逸惠书","f":"七言古诗","c":["三年读书少馀味，灯火可亲病为祟。","谢侯好事怜我穷，时遣双鱼问憔悴。","交情乃似亲骨肉，学行坐越诸公辈。","胸中万卷书屈蟠，少日力战登诗坛。","下帷却扫谢俗子，冻吟不管儿号寒。","只今食粥已数月，千虑百忧烦笔端。","高才本是栋梁器，苦语终无儒生酸。","乐章短句又清绝，陶写万象嘲江山。","江南草木不得闲，问君何为愁肺肝。","十年行坐想风采，千里魂梦劳追攀。","我无良田归不得，忍穷气味君应识。","囊贮未了岁寒计，学道空愧琳与璧。","交亲零落半鬼录，白日轻去真可惜。","终朝拨火煮芦菔，南山之南待君吃。"]},{"t":"寄知止才仲","f":"七言律诗","c":["一门叔父到卿好，中表弟兄惟尔贤。","往事关心空自语，新诗好句与谁传。","溪山已近堪投老，文史虽穷莫取怜。","仲弟墓头今宿草，为渠先赋补亡篇。"]},{"t":"寄张益中","f":"五言古诗","c":["五年望张子，兀坐四壁空。","今晨千里来，如热濯清风。","笑谈不改旧，怜我衰病攻。","斯人旧豪气，颇似陈元龙。","只今更省事，终岁两颊红。","何知珊瑚树，却倚尘埃中。","晁侯夙所敬，见渠如见公。","网罗枝出脚，远逐冥冥鸿。","同会得玉郎，敲门夜相从。","殷勤一杯酒，目送西归鸿。","人生少如意，此乐难再逢。","君家老季鹰，高韵留吴淞。","风流远孙在，一棹何时东。","不嫌道里远，为我略从容。"]},{"t":"元日赠沈宗师四首 其一","f":"五言律诗","c":["东家起传觞，西家起相唤。","我亦了新诗，成此奇一段。","念无毫发益，但见日月换。","出门语沈郎，造请我亦漫。"]},{"t":"元日赠沈宗师四首 其二","f":"五言律诗","c":["念昔从诸贤，关汪老耆旧。","是事今则无，斯人亦难又。","尔来见公子，却立两公后。","不倦以终之，可以为子寿。"]},{"t":"元日赠沈宗师四首 其三","f":"五言律诗","c":["沈郎固可人，好善乃天性。","迹随万事远，心与一物定。","萧然四立壁，笔墨自温凊。","更持孟贲勇，少折楚士胫。"]},{"t":"元日赠沈宗师四首 其四","f":"五言律诗","c":["君无绮纨气，我有冰雪容。","相期五石瓠，共济万里风。","江山秀句在，内子空洞中。","还身视尘滓，当有一日功。"]},{"t":"梅","f":"五言律诗","c":["南雪看未稳，北风吹已残。","才堪十年梦，不称一生酸。","日月方回首，风霜与凭栏。","迟明出谢客，顿觉帽围宽。"]},{"t":"苦阴","f":"五言律诗","c":["破腊冬仍在，逢正阴更频。","寒流未解冻，雪意欲妨春。","畏病还疏酒，逃寒懒见人。","郊东小桃李，还是一番新。"]},{"t":"赠浃上人","f":"七言律诗","c":["一庵便送渊明老，四海共传摩诘诗。","本自妨人枕边梦，不能陪汝剑头炊。","交游大半饥寒里，疾病中分少壮时。","西寺木鱼东寺鼓，三年三见浃阇黎。"]},{"t":"正月十二日夜作","f":"七言律诗","c":["春来消息未真传，久负蒲团一味禅。","灯火侵寻作佳境，冰霜偃蹇过新年。","江声误落三更雨，野色遥看万斛船。","咫尺风光不相贷，忍令好语到愁边。"]},{"t":"咸安公主","f":"七言绝句","c":["汉朝公主歌黄鹄，秦地佳人唱柳枝。","想见云车度沙漠，一杯湩酪酹明妃。"]},{"t":"明妃","f":"五言古诗","c":["秦人彊盛时，百战无逡巡。","汉氏失中策，清边烽燧频。","丈夫不任事，女子去和亲。","君王为置酒，单于来奉珍。","朝辞汉宫月，暮随胡地尘。","鞍马白沙暮，旃裘黄草春。","人生在相合，不论越与秦。","但取眼前好，莫言长苦辛。","君看轻薄儿，何殊胡地人。"]},{"t":"正月十三日河堤上作","f":"七言绝句","c":["雨着河堤柳着烟，小楼灯火又今年。","东风不与行人便，留滞长亭十里船。"]},{"t":"昨日晚归戏成四绝呈子之兼烦转示进道丈 其一","f":"七言绝句","c":["疏灯欲尽渔商市，小雨似开桃李颜。","一夜檐声鸣瓮盎，无人知我坐蒲团。"]},{"t":"昨日晚归戏成四绝呈子之兼烦转示进道丈 其二","f":"七言绝句","c":["卧疾江边久未回，懒随儿辈走尘埃。","天公尚有馀情在，肯放梅花自在开。"]},{"t":"昨日晚归戏成四绝呈子之兼烦转示进道丈 其三","f":"七言绝句","c":["春愁故故妨人乐，旧藓新苔不暂晴。","想见江郎闭船卧，满川风雨报天明。"]},{"t":"昨日晚归戏成四绝呈子之兼烦转示进道丈 其四","f":"七言绝句","c":["晁卿白发风流在，肯伴香车作夜遨。","借问典衣充戏责，何如沽酒唤吾曹。"]},{"t":"上元夜招沈宗师不至闻已赴郡会作二绝戏之 其一","f":"七言绝句","c":["灯火满城公不来，为公雕句洗尘埃。","春愁不到城西寺，更约梅花缓缓开。"]},{"t":"上元夜招沈宗师不至闻已赴郡会作二绝戏之 其二","f":"七言绝句","c":["白酒红灯称意春，知公未免踏黄尘。","绳床好在休相忆，输与琅琊浃上人。"]},{"t":"浃上座求枯木庵诗戏成两绝赠之 其一","f":"七言绝句","c":["枯木庵中浃道人，百年无影卧轮囷。","未须特地通身去，放取枝条自在春。"]},{"t":"浃上座求枯木庵诗戏成两绝赠之 其二","f":"七言绝句","c":["前身石霜后身浃，如印印泥风去尘。","认得当时侍者意，无人知是密庵人。"]},{"t":"正月末雪中小酌","f":"七言绝句","c":["柳着河冰雪着船，小桃应误取春怜。","床头有酒须君醉，又废蒲团一夜禅。"]},{"t":"次韵张生","f":"七言律诗","c":["密庵居士渠不识，齿发则衰心未然。","樽下不知公子贵，酒中差觉孟生贤。","已吞舌本三千丈，却住人间五百年。","触忤风光君莫怪，棒头无地可逃禅。"]},{"t":"追成旧作","f":"七言绝句","c":["满江风月一船霜，无计留君只自狂。","灯火隔帘香隔坐，无人知是竹枝娘。"]},{"t":"久不得才仲书因成二绝寄之 其一","f":"七言绝句","c":["望大赵书如渴骥，忆老汪胶无续弦。","看遍江南与江北，小屏微雨是斜川。"]},{"t":"久不得才仲书因成二绝寄之 其二","f":"七言绝句","c":["病去诗无一点尘，亦知摩诘是前身。","怜君更似西江水，合伴倚松庵里人。"]},{"t":"晚晴","f":"五言律诗","c":["斜阳入花柳，浑欲不胜情。","春事乃如此，病躯安得平。","尚堪冲宿酒，复作快新晴。","荒檐足乌鸟，莫厌晚来声。"]},{"t":"连日与一上人会话密庵清坐附火乃有山居气息因成一诗奉呈","f":"五言古诗","c":["春风吹茅檐，落日半花柳。","馀寒盛气来，佳辰为谁有。","公来但默坐，有味皆可口。","端如列鼎食，衣被以醇酒。","烦言不知要，实自费斗薮。","南泉山下人，了不计可否。","山柴晚复焰，当为一举手。","荒江甚泬寥，此味亦长久。","不嫌薰病眼，重当为公取。"]},{"t":"一上人屡言琅琊南塔之胜予盖乐之而未能往也","f":"七言绝句","c":["二顷良田一亩宫，好山当自属林公。","须君留我卓锥地，安听飕飗万壑风。"]},{"t":"夜坐有怀","f":"五言律诗","c":["西还岂不好，本自乏周旋。","道有鲁一变，岁无官九迁。","疾风惊半夜，恶况极今年。","咫尺沙头路，犹堪着钓船。"]},{"t":"晚春即事","f":"五言律诗","c":["春色不自惜，晓寒摧折之。","残花带雨去，薄酒信风吹。","尚有寻行债，初无了事痴。","论诗得奇味，当使阿戎知。"]},{"t":"广陵道中寒食日 其一","f":"七言绝句","c":["风雨属连春事休，碧鳞三尺荐行舟。","短墙不见桃花面，付与长江自在流。"]},{"t":"广陵道中寒食日 其二","f":"七言绝句","c":["南来消息不真传，正恐相逢却未然。","何处青帘足沽酒，粥香饧白是今年。"]},{"t":"就宁子仪求酒","f":"七言绝句","c":["鼻息咈然君莫惊，饥肠渠自作雷鸣。","须公一勺羔儿酒，伴我夜窗听雨声。"]},{"t":"广陵","f":"五言律诗","c":["往来六十里，各是一江郊。","柳色团涡岸，春风扬子桥。","好山当断岸，野鸟度空巢。","一任雷塘路，暮天风雨号。"]},{"t":"沈宗师甚喜江梅而微贬酴醾因成一绝","f":"七言绝句","c":["淡绿衣裳玉作妆，好风凉月自相当。","沈郎笑汝多情在，不似江梅满意香。"]},{"t":"劝张李二君酒","f":"七言古诗","c":["张侯好诗如好色，不敢为主而为客。","李侯好酒如好诗，心虽甚壮无人知。","两侯风味俱不恶，如芙蓉与木芍药。","午窗留客看笔快，晓枕无人犹睡着。","广袖渐变天宝妆，大字不作元和脚。","世人讥笑乃其分，政是仍叔之子弱。","病夫坐隐无所求，荒檐断雨鸣春鸠。","炉烟未尽消百忧，恨不缓带从公游。","何时清江横小舟，与公一醉荻花秋，却来密庵参牧牛。"]},{"t":"庵居","f":"七言律诗","c":["鸟语花香变夕阴，稍闲复恐病相寻。","正应独有江山分，素自都无廊庙心。","堂上老亲双白发，门前稚子旧青衿。","儿曹不会庵居意，古涧寒泉疑至今。"]},{"t":"小园即事","f":"五言古诗","c":["千花老无踪，众草来可喜。","欣然得幽寻，我亦病良已。","飞飞两蝴蝶，不悟尘土里。","禽声甚可人，亦似相汝尔。","人生贵惬志，不必须甚美。","三年白沙诗，已费千幅纸。","问君何所乐，赤手费磨洗。","短屏看远山，心作千万里。","此岂画者功，实自一念起。","君当如是观，在此不在彼。"]},{"t":"登舟","f":"五言律诗","c":["夜雨晓犹滴，怒风晴更吹。","已无行役念，宁有别离悲。","舟楫三年路，江山一月期。","东庵旧还往，不废百篇诗。"]},{"t":"张袆秀才乞诗","f":"七言律诗","c":["白莲庵中张居士，梦断世间风马牛。","风尘表物自无意，神仙中人聊与游。","澄江似趁北城晓，苦雨不放南山秋。","君当先行我继往，向吴亭东留小舟。"]},{"t":"效古乐府三首 其一","f":"五言绝句","c":["君住长江边，妾上长江去。","长江日夜流，相思不相顾。"]},{"t":"效古乐府三首 其二","f":"五言绝句","c":["长江日夜流，妾心终不改。","谁谓江头人，相思不相待。"]},{"t":"效古乐府三首 其三","f":"五言绝句","c":["东家石榴红，西家石榴紫。","俱是一种花，同生不同死。"]},{"t":"读太真外传","f":"五言律诗","c":["上尽马嵬路，东风吹旧京。","乾坤已新主，草木自秋声。","锦袜千年恨，皇舆万里程。","宁知挽船士，亦有别离情。"]},{"t":"简宁子仪二绝 其一","f":"七言绝句","c":["只恐老去被花恼，更欲忘忧须酒浇。","何似山堂病居士，闭门高枕过春朝。"]},{"t":"简宁子仪二绝 其二","f":"七言绝句","c":["新晴欲上南楼月，柳可藏鸦水蘸墙。","无限客愁芳草里，不知风雨阻斜阳。"]},{"t":"书寄浃上人","f":"词","c":["胸中无一毫事，笔下有千斛力。","走遍江南江北山，满堂禅和不相识。"]},{"t":"呈愚上人","f":"七言律诗","c":["不能归续侍中貂，遂有声名伴老饶。","万里更行看騕袅，一枝才足赋鹪鹩。","诗囊磈礧君其漫，药裹侵寻我亦聊。","举目云天尽新语，殷勤收寄一牛腰。"]},{"t":"赠浃上人一上人","f":"五言古诗","c":["君行南山南，我在北山北。","不闻浴鹄白，但见染丝黑。","老境欲垂垂，快意须得得。","孰知百雉坚，而有一日克。","浃如涧底松，纵老终不踣。","一如云间鹤，不复可羁勒。","我如千里风，遇此两鸿鹄。","明珠脱氛翳，晓日破昏塞。","宿障不尽除，胸次犹笔墨。","君看说诗口，乃是拔山力。","冷霜卧偃蹇，岁月饱封殖。","谁能窥藩篱，未易得阃阈。","政当敛光芒，不必须缘饰。","相从无何乡，败衲依破裓。","更令好事人，妙语添一则。"]},{"t":"雨后月夜怀沈宗师承务","f":"五言古诗","c":["雨云揽江色，偃蹇破昏睡。","千花闭红紫，妙见一室内。","披衣行夜永，明月在船背。","微风过萧瑟，古柳立苍翠。","翛然一蒲团，坚坐觅诗对。","我生无南北，所到意趣遂。","孰知十年游，保此清净退。","颇念城北人，结友老杉桧。","漫随长铗归，甘作短檠弃。","出门万里涂，已驾安得税。","何当持被来，把酒相就醉。"]},{"t":"秋夜示李十","f":"五言古诗","c":["晴鸠不时鸣，雨鸠不暂歇。","相去跬步间，屡见屐齿折。","寒泥拥衰草，秋扇罢残热。","今晨好风景，稍贷屋头月。","清光冷相照，玉艳满金玦。","唤客坐前窗，文字相澡雪。","殷勤傍诗律，未暇了曲糵。","澜翻谈经口，邂逅如意铁。","我歌君辄书，字字有行列。","不须陛枑严，但要兵卫设。","譬如南山石，瑑齿当井渫。","真成一战霸，未可三鼓竭。","人生各泾渭，世事亦滕薛。","高堂食肉人，两马方踶齧。","何知缊袍底，犹有不安节。"]},{"t":"中秋日沈宗师约游城西泥雨不果因成四十字兼寄赵才仲","f":"五言律诗","c":["遂阻城西步，兼怀霅上游。","长风掠归燕，苦雨应鸣鸠。","月向谁边好，寒催社后秋。","传杯有新韵，能忆老兄不。"]},{"t":"桃花菊","f":"七言绝句","c":["嫩粉殷勤换浅黄，郁金丛里见新妆。","已翻百叠红衣润，更沐九回沈水汤。"]},{"t":"九日晨起","f":"五言律诗","c":["渐歇驱蚊手，真成把酒天。","长河印晓月，老木聚荒烟。","了了江山梦，区区文字缘。","南阶两三菊，极意作今年。"]},{"t":"王氏郊居","f":"五言律诗","c":["江山处处好，落日极登临。","雨续蔬畦润，风吹杮叶阴。","客船频上下，水鸟故浮沈。","尚有南飞雁，丁宁可寄音。"]},{"t":"对菊","f":"七言绝句","c":["稚子寻花莫漫狂，已知衰疾负重阳。","新霜有意留青蕊，更放残枝十月黄。"]},{"t":"雨后至江上有怀诸子","f":"五言律诗","c":["落日满寒雨，长江收夕霏。","定知聊复尔，敢望不相违。","野鸟晴相唤，残萤晚自飞。","殷勤两山口，好为放朝晖。"]},{"t":"登南楼","f":"七言律诗","c":["疾风吹沙不成雨，十日狂阴倒残暑。","江头树木半焦枯，不厌潮头洗尘土。","南楼反照千丈红，落日却在洪涛中。","舟父渔子莫惆怅，更借朝来东北风。"]},{"t":"岁晚作","f":"七言古诗","c":["南山雪云千丈高，北山晚田无寸毫。","富儿巨家饱欲死，笑我陋巷长蓬蒿。","道人坐稳忘作劳，百念解纵如垂櫜。","但当折简唤我曹，并坐择虱烦抑搔。","笔力可借秋江涛，莫学人间膏火熬。"]},{"t":"吊古冢","f":"五言律诗","c":["荆榛闭莽苍，千岁一孤坟。","生则无是叟，死应冥漠君。","略无他日念，唯有不堪闻。","想得西陵道，荒台亦暮云。"]},{"t":"奉送子之还京师","f":"五言古诗","c":["日月老投闲，文字今削迹。","便然腰十围，欲吐啄三尺。","颇怀平生友，相就语肝膈。","诸江好兄弟，夫子眉最白。","词林三二公，子实门下客。","布帆千里来，许我间宾席。","阶庭出兰树，户牖照圭璧。","诗如驾高浪，万顷随笔力。","宁为首阳饿，不作嬖奚获。","乃知工语言，要是饱糠覈。","茫然李杜坛，未免陈蔡厄。","出门观善阵，敛手避勍敌。","澄江摇夜霜，岁晚见沙石。","钗头罥蛛丝，即有梁宋役。","士生多艰虞，道远自古昔。","相期逍遥游，不计天地窄。","名声了三黜，谈笑供百谪。","别君为此言，可当绕朝策。"]},{"t":"外弟赵才仲数以书来论诗因作此答之","f":"五言古诗","c":["君才如长刀，大窾当一割。","正须砻其锋，却立望容发。","平生江海念，不救文字渴。","茫然揽辔来，六骥仰朝秣。","病夫百无用，念子故疏阔。","未能即山林，颇复便裘褐。","前时少年累，如烛今见跋。","胸中尘埃去，渐喜诗语活。","孰知一杯水，已见千里豁。","初如弹丸转，忽若秋兔脱。","旁观不知妙，可受不可夺。","君看掷白卢，乃是中箭筈。","不闻铁甲利，反畏彊弩末。","舆薪遵大路，过眼有未察。","君能探虎穴，不但须可捋。"]},{"t":"过子之泊船旧亭","f":"五言律诗","c":["江郎泊船处，草径不胜秋。","客里终年别，春前万斛愁。","山横采菱口，月满望江楼。","政可梦春草，莫令吟白头。"]},{"t":"望金陵偶成两绝 其一","f":"七言绝句","c":["台城南望入斜阳，尚想能诗玉树郎。","乘兴风流莫相笑，眼看直北走雷塘。"]},{"t":"望金陵偶成两绝 其二","f":"七言绝句","c":["雷塘别有风流坐，可作南舟两日行。","江水自流春自好，不知芳草为谁生。"]},{"t":"烹茶","f":"七言绝句","c":["水光欲尽琉璃影，玉色初浮翡翠斑。","便觉曲生风味好，小炉新火对蒲团。"]},{"t":"西楼","f":"七言绝句","c":["小院无人日自长，隔帘时有芰荷香。","客游未作安居计，更借西楼一夜凉。"]},{"t":"寄信上人","f":"五言律诗","c":["笑语三年别，舟航十里淮。","新霜变草木，好雨过风霾。","万事不如意，一生常好乖。","何因伴明月，特地入君怀。"]},{"t":"秦处度与一上人同宿密庵处度为一画断崖枯木","f":"七言绝句","c":["小庵无客亦无毡，遂有高人借榻眠。","一夜西风撼枯柳，不知春在石崖边。"]},{"t":"寄谢无逸并汪叔野兄弟","f":"七言律诗","c":["老谢风流绿绮琴，小汪兄弟亦南金。","文章已误半生事，江海略酬他日心。","好酒不当愁偪仄，旧书差慰病侵寻。","平生恩义伴宫老，断绠寒泉百尺深。"]},{"t":"月下","f":"七言绝句","c":["白鸥笑汝不能饮，澄江恼人勤作诗。","可惜南楼好风月，只无春柳对琼枝。"]},{"t":"刘穆之","f":"七言绝句","c":["金柈一斛贮槟榔，戏调儿童走欲狂。","不谓林间有元亮，念公时在酒中藏。"]},{"t":"戏赠浃上人","f":"七言绝句","c":["忽逢邗沟道人浃，如见锡山居士秦。","问着世缘浑忘却，知公不是个中人。"]},{"t":"喜章仲孚朝奉见过十韵","f":"五言古诗","c":["苦语不难好，旧交今则无。","但能留客坐，已胜折腰趋。","只有连根煮，初非满眼酤。","苔痕记拄杖，雪影傍跏趺。","语道我恨晚，说诗公不迂。","丁宁入汉魏，委曲上唐虞。","历历有全体，匆匆或半涂。","真当置度外，不敢望庭隅。","日月换新岁，江山非故吾。","他年佳句在，与画密庵图。"]},{"t":"观宁子仪所蓄维摩寒山拾得唐画歌","f":"词","c":["君不见寒山子，垢面蓬头何所似。","戏拈拄杖唤拾公，似是同游国清寺。","又不见维摩老，结习已空无可道。","床头谁是散花人，堕地纷纷不须扫。","呜呼妙处虽在不得言，尚有丹青传百年。","请公着眼落笔前，令我琢句逃幽禅。","异时净社看白莲，莫忘只今香火缘。"]},{"t":"寄朱时发","f":"七言律诗","c":["菱桥脊梁硬如铁，天下拄杖打不折。","倒骑佛殿出三门，南头学来北头说。","昔苗未生今作米，更判阿师三尺觜。","公但吸尽西江水，莫怕庭前簸箕尾。"]},{"t":"寄颖昌诸叔","f":"七言律诗","c":["身如许县老聋丞，心是江湖版下僧。","万事聊凭曲肱梦，一尊时近短檠灯。","旧游可数终难又，恶况虽多不厌曾。","尚忆少年情语否，夜窗相对发鬅鬙。"]},{"t":"谢人送琼花白沙人谓琼花为无双花戏成两绝 其一","f":"七言绝句","c":["凝尘欲满读书窗，忽有琼花对小缸。","更喜风流好名字，百金一朵号无双。"]},{"t":"谢人送琼花白沙人谓琼花为无双花戏成两绝 其二","f":"七言绝句","c":["断肠风味久难寻，尚有名花寄此心。","折尽长枝已春晚，只宜凉月不宜阴。"]},{"t":"观宁子仪朝奉山堂诸石三绝 其一","f":"七言绝句","c":["个中真味久难忘，但觉人间万事忙。","今日为公留不得，剩分诗思入山堂。"]},{"t":"观宁子仪朝奉山堂诸石三绝 其二","f":"七言绝句","c":["向人怀抱终何有，过眼峥嵘得暂醒。","更唤秦髯与湔祓，为公题作小南屏。"]},{"t":"观宁子仪朝奉山堂诸石三绝 其三","f":"七言绝句","c":["知公心似山堂石，误落人间几案间。","今日风光已相负，看朱成碧未能还。"]},{"t":"十一月五日与才仲弟相别于白沙东门之外怅然久之不能自释乃知谢安石作恶之语不为过也因成八诗奉寄可见别后气味亦可并示京洛间亲旧也 其一","f":"五言律诗","c":["终年想颜色，未有食顷忘。","君宁不我念，苦畏冰雪妨。","斯文百战罢，阅士如堵墙。","孰知五湖口，一苇可以航。"]},{"t":"十一月五日与才仲弟相别于白沙东门之外怅然久之不能自释乃知谢安石作恶之语不为过也因成八诗奉寄可见别后气味亦可并示京洛间亲旧也 其二","f":"五言律诗","c":["君才不长贫，太阿之在匣。","故知谗慝口，不受龙象踏。","此道有从来，肮脏端不乏。","相期瓮头春，夜语重一呷。"]},{"t":"十一月五日与才仲弟相别于白沙东门之外怅然久之不能自释乃知谢安石作恶之语不为过也因成八诗奉寄可见别后气味亦可并示京洛间亲旧也 其三","f":"五言律诗","c":["盛欲与子谈，乃复为此别。","匆匆得馀欢，把酒到耳热。","人生不如意，肝胆有楚越。","何知若人胸，中有积立铁。"]},{"t":"十一月五日与才仲弟相别于白沙东门之外怅然久之不能自释乃知谢安石作恶之语不为过也因成八诗奉寄可见别后气味亦可并示京洛间亲旧也 其四","f":"五言律诗","c":["伯姑无恙时，令我与子友。","周旋以至今，各是遗种叟。","文字种声名，于身亦何有。","还书问两弟，是事君识否。"]},{"t":"十一月五日与才仲弟相别于白沙东门之外怅然久之不能自释乃知谢安石作恶之语不为过也因成八诗奉寄可见别后气味亦可并示京洛间亲旧也 其五","f":"五言律诗","c":["妇如先姑贤，儿似乃翁好。","识君相与心，见我亦倾倒。","频年作离情，悟赏到丘嫂。","卜邻洛水阳，此语当在早。"]},{"t":"十一月五日与才仲弟相别于白沙东门之外怅然久之不能自释乃知谢安石作恶之语不为过也因成八诗奉寄可见别后气味亦可并示京洛间亲旧也 其六","f":"五言律诗","c":["低头拜东野，未厌擿抉穷。","停车问缩酒，不讣牛马风。","胸次绝尘滓，欲与秋水同。","斯人未遽远，当在阿堵中。"]},{"t":"十一月五日与才仲弟相别于白沙东门之外怅然久之不能自释乃知谢安石作恶之语不为过也因成八诗奉寄可见别后气味亦可并示京洛间亲旧也 其七","f":"五言律诗","c":["往者汪信民，爱我不自胜。","以我如古人，得与子并称。","若士不复有，斯言当伏膺。","期君极膏沃，更作无尽灯。"]},{"t":"十一月五日与才仲弟相别于白沙东门之外怅然久之不能自释乃知谢安石作恶之语不为过也因成八诗奉寄可见别后气味亦可并示京洛间亲旧也 其八","f":"五言律诗","c":["锻以百鍊刚，淬以万里流。","闭门待彊敌，忽见天地秋。","以石投水中，万岁终不浮。","堂堂倚松老，于今忘百忧。"]},{"t":"山水图歌","f":"词","c":["君不见南江老龙夜不眠，令我破屋开青天。","千岩倒壁卷角上，一榻却在洪涛前。","又不见江头古木一尺围，猿猱接手悬高枝。","雨中寒芦披靡去，天际风帆先后归。","陈生故是可怜人，笔虽未到心已亲。","南村北村渴欲死，怪此一室无纤尘。","郑虔祁岳不解奇，韩干画马空多肥。","万里咫尺君得之，更看湘江雷雨垂。"]},{"t":"庚寅年正旦郡中客次作","f":"七言律诗","c":["晓霜挟雾入寒厅，四座伊优不暂停。","剩欲禅房作新岁，念无馀沥到空瓶。","诙谐与世聊从俗，啸傲他年可乞灵。","更为旁人住俄顷，坐间愁杀两螟蛉。"]},{"t":"题李伯时维摩画像图","f":"七言古诗","c":["老松搀天四无壁，小庵不劳容一室。","野竹入户芭蕉肥，下有无言病摩诘。","文殊妙对亦未真，身如浮云那得亲。","惊倒同行问话人，彼上人者何所云。","龙眠好事笔有神，不避世间狐兔群。","扫渠胸中千斛尘，多口阿师闻不闻。"]},{"t":"遣怀三首 其一","f":"五言古诗","c":["何山不堪隐，何家不可居。","古来子华门，亦着荷畚夫。","荒田脱积雨，未免供晚租。","今日视昨日，但见有不如。","故人劝加餐，老亲怜嗜书。","宁知毛锥子，不可一日无。"]},{"t":"遣怀三首 其二","f":"五言古诗","c":["秋风袭残暑，忽过江上林。","旦日扶杖来，不见十亩阴。","蔬畦甚寂寞，亦受霜雪侵。","念此不常好，如我宿昔心。","涛头落崩岸，野鸟助讴吟。","潜鱼着沙底，避网冬更沈。"]},{"t":"遣怀三首 其三","f":"五言古诗","c":["异时忘言人，马鬣今宿草。","生平不如意，欲伴寒木槁。","遂令藜苋肠，更尽组绣巧。","三年对空案，诵子诗可饱。","从来文字工，不解颜色好。","相逢期后身，再访西院老。"]},{"t":"符离阻雨","f":"五言古诗","c":["东风吹船窗，未晓天复雨。","篙师促添缆，卧听泥㶁㶁。","不知城北园，春事今几许。","旧游如宿昔，花柳默可数。","邻里先后来，颇复相劳苦。","东家献牛酒，西家馈鸡黍。","感渠长久情，愧我无所取。","汪侯哦诗处，积水败环堵。","念此不忍行，不但出入阻。","七年此端居，畏病如畏虎。","故人饶与黎，此老可出语。"]},{"t":"伍员祠","f":"七言律诗","c":["伍员庙前一丈碑，上有野鹤双来栖。","水云杳杳凉去远，风雨冥冥秋到迟。","江花相趁野花发，旧燕不随新燕归。","大夫遗恨竟何许，楚越勾吴今是非。"]},{"t":"东园","f":"五言律诗","c":["垢污久思出，江山秋更新。","荒田拆龟兆，老桧落龙鳞。","风月犹堪夜，蒲莲浪作春。","篮舆亦乘兴，实自厌冠巾。"]},{"t":"寄琦监院","f":"七言律诗","c":["往时济阳晁公子，今日灵岩琦上人。","千山不碍一月晓，北树忽见南枝春。","个中有味渠不识，底处无情公得亲。","不知碧眼之面壁，何如魋颜西入秦。"]},{"t":"即事戏答季一","f":"五言律诗","c":["斜阳着高柳，环堵半黄昏。","小圃三年旱，荒池一尺浑。","粗知诗有味，宁使妇无裈。","不信晁公子，犹招楚些魂。"]},{"t":"湘竹","f":"七言绝句","c":["小雨催寒入夕曛，湘江风味可怜人。","斑斑玉泪无时尽，袅袅金梢别是春。"]},{"t":"有怀宿州城北因作诗寄才仲","f":"七言律诗","c":["宿州古城城北隅，雨罢晴开如画图。","杂花乱蕊未须道，白杏一枝天下无。","香风袅袅入短袖，明月萧萧随蹇驴。","二年不复见此乐，清江万顷正愁予。"]},{"t":"示沈宗师 其一","f":"七言绝句","c":["十日儿号不出房，残梅犹在小瓶香。","沈郎唤客煮汤饼，政恐匆匆未得尝。"]},{"t":"示沈宗师 其二","f":"七言绝句","c":["九日狂阴一日晴，落花飞絮作清明。","与君携手南楼去，共听长江月下声。"]},{"t":"夜坐戏成两绝呈迪吉宗师二友 其一","f":"七言绝句","c":["夜窗灯火著新寒，喜见蒲团一味闲。","纵有好诗人不要，却须还与槛前山。"]},{"t":"夜坐戏成两绝呈迪吉宗师二友 其二","f":"七言绝句","c":["疏帘欲上梧楸影，远枕微闻盆盎鸣。","甚欲分身就公宿，只愁尘土变江声。"]},{"t":"戏成两绝奉简章仲孚兼呈宗师 其一","f":"七言绝句","c":["日日勃鸠相应鸣，年年春草趁愁生。","道人不怕冰霜面，又作南舟十日行。"]},{"t":"戏成两绝奉简章仲孚兼呈宗师 其二","f":"七言绝句","c":["沈郎爱客如爱酒，章子问诗如问禅。","肯共寒炉拨残火，共搜佳句作新年。"]},{"t":"老松","f":"词","c":["奉君以绿绮琴，报我以双南金。","杯中琥珀不须尽，听妾一声行路吟。","君看庭前老松树，上有杳默不断之清阴。","墙低未碍髯发古，岁晚不辞霜雪侵。","东园桃李自妍好，与君百岁同此心。"]},{"t":"扬州雍熙寺纳凉","f":"五言古诗","c":["高楼有馀凉，但见旗脚动。","鸟语檐角来，仰听风响弄。","江山旧还往，草木老宾从。","平生一笑适，可得万钧重。","翛然六尺床，更许佳月共。"]},{"t":"访张鉴秀才兄弟","f":"七言绝句","c":["眼看霍霍万钱食，便就匆匆五鼎烹。","何似张侯五兄弟，闭门相对饱芹羹。"]},{"t":"邵伯埭路中","f":"七言律诗","c":["行前蒲柳后鸥鸟，乃似白沙之旧居。","忽见云天有新语，不知风雨对残书。","往来河树几倾盖，上下江船如贯鱼。","更与河山结香火，夜窗重枉故人车。"]},{"t":"寄周司理","f":"五言古诗","c":["日月走劻勷，舟楫卧烦暑。","凉秋在万里，客子安得语。","周侯磊落人，怜我自熬煮。","殷勤半月留，可得一笑许。","别来今几日，坐此百里阻。","清风不时来，晓月仍半吐。","卷帘看脩竹，忽似对眉宇。","人生行乐耳，舍此皆自苦。","终期卜邻归，重听对床雨。","虽无呜呜歌，亦有坎坎鼓。"]},{"t":"山光寺前泊舟值雨","f":"五言律诗","c":["轻雷唤小雨，忆在白沙时。","绿酒留连醉，红灯取次诗。","好风那复有，凉月自相随。","独上山光寺，清歌无柳枝。"]},{"t":"步月有怀","f":"七言绝句","c":["平生最爱花梢月，可与青楼一等看。","病去老来浑忘却，晓窗晴日上蒲团。"]},{"t":"扬州留一上人","f":"七言律诗","c":["日日东风吹客衣，小园春在掩芳菲。","残花过雨飘零尽，好鸟穿林自在飞。","往事虚成采薇瘦，故人频有食言肥。","知公未厌西行晚，且伴江船缓缓归。"]},{"t":"送一上人之京师","f":"词","c":["东风吹云十日雨，卧听城头打衙鼓。","道人远自山中来，共坐南窗濯泥土。","自然高韵到羲皇，岂止微言变齐鲁。","万牛回首不震掉，一叶横江且掀舞。","未能入水取蛟蜃，尚欲投戈代貔虎。","念公守此非一朝，木病磈瘣无枝条。","已尽千峰西岭雪，更梦八月钱塘潮。","京城尘沙深一尺，是中莫留公履迹。","权门蹲?儿女笑，我一思之不能食。","片帆无事早归来，为公一洗山中石。"]},{"t":"拟古 其一","f":"五言古诗","c":["狡兔死三窟，老松坚百寻。","物生各有愿，共此分寸阴。","荒城六月旱，长江三日霖。","稻苗不遂死，幸无蟊贼侵。","皇天不私覆，一语销百壬。","先王典刑在，落落传至今。","愿以小人腹，而为君子心。"]},{"t":"拟古 其二","f":"五言古诗","c":["寒鸡不能晨，苦雨自朝夕。","上为云雷巢，下乃龙蜃宅。","坐怀阴外天，缺月挂残魄。","少来可喜人，牖户陈玉帛。","平生千万言，略省二三策。","牛山所种木，日在斤斧厄。","念君十年心，使我双鬓白。"]},{"t":"潘邠老尝得诗云满城风雨近重阳文章之妙至此极矣后托谢无逸缀成无逸诗云病思王子同倾酒愁忆潘郎共赋诗盖为此语也王子立之也作此诗未数年而立之邠老墓木已拱无逸穷困江南未有定止感叹之馀辄成二绝 其一","f":"七言绝句","c":["漫营新句补残章，寄与乌衣玉树郎。","他日无人识佳景，满城风雨近重阳。"]},{"t":"潘邠老尝得诗云满城风雨近重阳文章之妙至此极矣后托谢无逸缀成无逸诗云病思王子同倾酒愁忆潘郎共赋诗盖为此语也王子立之也作此诗未数年而立之邠老墓木已拱无逸穷困江南未有定止感叹之馀辄成二绝 其二","f":"七言绝句","c":["好诗政似佳风月，会赏能知已不凡。","万里潘郎旧乡县，半江斜日落归帆。"]},{"t":"寄李商老","f":"词","c":["竹不可一日无，酒不可饮不醉。","平生嗜酒爱风竹，此意不许凡儿会。","南来经年饱尘垢，袖手甘随百夫后。","文章漫作无功身，只了儿曹补窗窦。","黄沙障日江漫流，青山唤我十年旧。","忆昔泊船鹅翎口，把酒遥为故人寿。","只今身在心已老，千岩想像灵芝秀。","君家兄弟固不凡，解挽三友勤相就。","中郎卧病过春晚，昔则酒狂今诗瘦。","山房大名不坠地，诸老风流未宜弃。","老桧参天可乞盟，粢食铏羹乃无味。","如君高韵千载同，可更托身三数公。","丈夫劲挺要长久，百万叩关一夫守。","胸中江海不须道，此流何必计升斗。","眼前勃窣诉二友，听客所为公绝口。"]},{"t":"雨中作","f":"五言律诗","c":["咄咄真成梦，悠悠复未知。","宁为牛背语，不作剑头炊。","雨挟秋声乱，江含暝色悲。","故知无事饮，犹胜顷来诗。"]},{"t":"示内","f":"五言古诗","c":["贫贱不可忘，富贵安足羡。","我生未三十，种种厌贫贱。","宦情肱九折，老味金百鍊。","稍回功名心，来结香火愿。","平生所知人，久已焚笔砚。","是中无真实，不在儒术缘。","有如退飞鹢，更借逆风便。","病妻颇痴绝，可与共开宴。","小女真吾儿，语学春鸟啭。","初非本来有，且作梦中见。","君看手捉鼻，绝胜扇障面。","他年从我居，同入隐士传。"]},{"t":"寄外弟赵楠才仲","f":"五言古诗","c":["长年更多疾，念尔不能忘。","梦去关山静，书来道里长。","形骸且憔悴，草木自苍唐。","古县疏还往，微官绝簸扬。","颇闻能吏事，仍不废文章。","客舍襄江下，人家筑水傍。","屡成千里目，虚断九回肠。","我老知无用，身闲欲半藏。","预愁章服裹，仍怯簿书忙。","事业烦诗卷，生涯在药囊。","得非嵇叔懒，宁似次公狂。","野桧多鳞甲，寒松半雪霜。","高天一雁远，小径百年荒。","每惜朱丝断，空怀素锦张。","旧交浑潦倒，此语更微茫。","欲判五斗米，先寻百本桑。","残羹得共啜，薄酒要同尝。","匣里出鸣剑，眼中除眯糠。","未容窥突奥，虚自倚门墙。","指点飞鸿路，何人识故乡。"]},{"t":"京师赠大有叔","f":"七言古诗","c":["尊酒相逢十载前，绿发红颜俱少年。","尊酒相逢十载后，皮黄肉皱俱白首。","叔如鸿鹄但高飞，侄似麇鼯更深走。","南来行李初一逢，长安旧第冰雪中。","闭门不识故人面，豪气直欲轻元龙。","平生为道不为食，少小所期皆目击。","何时相就过江南，同访曾游旧泉石。"]},{"t":"寄蔡伯世赵才仲 其一","f":"七言绝句","c":["我恨不识鹿门公，蔡郎心期千载同。","不随吏部曹中板，去赴长芦寺里钟。"]},{"t":"寄蔡伯世赵才仲 其二","f":"七言绝句","c":["一坐十月长江滨，自君之来心转亲。","还书起居清源君，人间纷纷何足云。"]},{"t":"寄蔡伯世赵才仲 其三","f":"七言绝句","c":["同行者谁平原孙，于我不但骨肉亲。","谁言不为桃花去，只爱江山亦可人。"]},{"t":"寄蔡伯世赵才仲 其四","f":"七言绝句","c":["二子逃禅不计年，江湖重去水粘天。","直饶透尽三关语，到底终成百漏船。"]},{"t":"寄蔡伯世赵才仲 其五","f":"七言绝句","c":["木鱼光里两蒲团，意气与我平生欢。","尽底告君君不会，空得痴人寻笔端。"]},{"t":"寄范子","f":"七言律诗","c":["范郎平生万人杰，只今未免儿号寒。","三江五湖在胸次，琨玉秋霜看笔端。","旧疾祇令肝肺热，春风欲开桃李颜。","待约南江今夜月，与渠万里报平安。"]},{"t":"春风","f":"五言古诗","c":["春风随长江，一日行万里。","萧条起岷山，欻忽度扬子。","江南千酒楼，春风楼上头。","金樽开翠幄，青帘吹客愁。","长堤二月暖，寒溪千古流。","纷纷桃李花，处处作芳华。","不见梁间燕，空悲王谢家。"]},{"t":"听琴","f":"词","c":["君不见龙门之下百尺桐，漂霰飞雪愁寒空。","何年班尔落君手，小窗伴坐歌南风。","恍然如著山岩里，不知身在尘埃中。","初闻平野飞鸿鹄，欻听金盘起珠玉。","绕坛古树郁嵯峨，六月吹霜作寒绿。","折杨黄华不须道，别鹤离鸾尚堪续。","君不见开元天子醉西都，音声十院留欢娱。","当时临轩奏此曲，径须解秽烦花奴。","乃知恬淡世莫识，无弦之趣何时无。","归家愁厌筝笛耳，此声一听还已矣。","会须流水访钟期，试向炉中觅焦尾。"]},{"t":"雨后","f":"七言律诗","c":["新花欲尽竹当栏，喜见空墙野色团。","稚子乘阴莳兰菊，仆夫留水灌莴蔓。","茶香于汝初无分，酒熟逢人也强欢。","恼乱春光君会否，小瓶犹占一枝残。"]},{"t":"送山伯良佐东归以务道期息涂为韵 其一","f":"五言古诗","c":["荆棘生良心，米盐入尘务。","芬芳老不达，岂不以此故。","人生锥处囊，颖末要立露。","玉壶近青蝇，没没自点污。","刳心万物表，却立看脱兔。"]},{"t":"送山伯良佐东归以务道期息涂为韵 其二","f":"五言古诗","c":["临别当一言，恳恳念忠告。","缥囊可取足，往结万古好。","默识古则然，愚智同一道。","远师颜氏子，近比伯业操。","文章有妙斲，期子开窔奥。"]},{"t":"送山伯良佐东归以务道期息涂为韵 其三","f":"五言古诗","c":["吾诗如清风，去留不可期。","洒然或一来，不繫凡子知。","两郎从我游，岂但窥藩篱。","山房光焰在，实藉众木枝。","斯言可三复，如我清风诗。"]},{"t":"送山伯良佐东归以务道期息涂为韵 其四","f":"五言古诗","c":["昔我同学生，文字虎而翼。","仲弟最多才，去以六月息。","自吾失若人，每语辄气塞。","子如求数君，慎莫怪蟊贼。","胸怀但明了，几案付尘黑。"]},{"t":"送山伯良佐东归以务道期息涂为韵 其五","f":"五言古诗","c":["赠我貂襜褕，报以明月珠。","古来声名人，一一行此涂。","汉中屠沽儿，适可曹公奴。","人生嗜好异，至有海上夫。","孰能识其然，饱此万卷书。"]},{"t":"河水清赠良佐兼寄商老","f":"词","c":["河水清，江水黄，南山北山自相望。","恨君不止白石房，与谁同游南郡郎。","白玉刻佩明月珰，如凤四海求其凰。","道里辽远日月长，爽气自足陵朝阳，举酒送君君莫忘。"]},{"t":"同晁季一李天纪过沈宗师北庄因成长韵","f":"五言古诗","c":["三年城南居，不识城北土。","但闻玉雪郎，去作猿鹤主。","今晨篮舆来，握手相劳苦。","胜游有佳士，洗耳听妙语。","晴窗背云壑，落日在环堵。","晚风生白杨，想像原野古。","断崖悬老木，小港聚寒雨。","却观城市人，努力自熬煮。","畏涂出衽席，祸福有未睹。","杜陵怀壮游，无忌笑豪举。","二者觅真是，政恐君未许。","千秋柴桑翁，妙句聊一吐。"]},{"t":"邮上祈雨","f":"七言绝句","c":["泥龙蜴蜥困追求，旱遍淮南二十州。","寄语天公莫轻许，少留明月作中秋。"]},{"t":"清风","f":"五言古诗","c":["清风如君子，所至有馀情。","忻然破烦溽，有醉时一醒。","嗟我二三友，飘散秋叶零。","不知城南王，何以识我名。","攲斜左手字，劳苦如平生。","会写登楼赋，一吊漳滨灵。"]},{"t":"学视","f":"五言古诗","c":["学视睹悬虱，病耳闻斗蚁。","纷然酬六凿，万劫费揩洗。","君看杯中蛇，妄想从何起。","忽然一妙语，初无强料理。","回观积年疾，乃是一念使。","谁能明此心，香山老居士。"]},{"t":"寄舍弟","f":"五言律诗","c":["残暑坠空屋，旧书穿破帷。","才蒙小雨润，遽得好风吹。","逸少每作恶，渊明常病羸。","他乡忆吾弟，苦语自成诗。"]},{"t":"断云","f":"五言古诗","c":["断云西南来，好风东北去。","翩然两无心，空中忽相遇。","化为一尺雪，照我亭前路。","昔者甚可怜，今来渺无处。","故人多勌色，留我不少住。","羁愁动中肠，疾病增百虑。","虚庭著明月，皎皎如积素。","不见乘鸾子，空怀旧烟雾。"]},{"t":"如皋道中","f":"五言律诗","c":["客路三日雨，颇知袍裤单。","长河贯沃野，薄酒动新寒。","晚日鱼虾市，秋风藜藿盘。","衰颜定可笑，不必镜中看。"]},{"t":"初去白沙再望路中江南诸山慨然有怀","f":"五言古诗","c":["青山如美人，浓淡各有态。","挽之不肯来，乃似孤竹隘。","念无千里风，限此一衣带。","夏木与藩屏，不畏炎日晒。","三年白沙游，藉尔宽眼界。","脱身尘垢中，一笑终不坏。","别君更举酒，未了清净债。","虽无丝竹娱，会有诗律快。","何如少陵翁，亦为杜鹃拜。","吾诗有馀欢，此语君勿怪。"]},{"t":"赴济阴留别一公","f":"五言古诗","c":["近别君莫嗟，远别君莫惜。","往来天壤间，谁为不相识。","十年几相别，日月虚弃掷。","见君长江口，已作胡眼碧。","别君广陵城，妙语摧霹雳。","今别知几时，复念驹过隙。","坐成千里阻，当有片言益。","不劝君爱身，不劝君强食。","劝君以勇决，万事要努力。","愚夫之所欣，智士之所戚。","譬如醉而颠，亦有傍震虩。","声色纠缠人，万劫困封植。","本自骄惰生，亦以因循得。","实惟招侮慢，岂止碍空寂。","居然耳目内，反务化勍敌。","谁能深山中，弄此无孔笛。","芳草变萧艾，每为长太息。","如公定不然，此语当谩忆。","何妨膏腴地，更论去荆棘。","君看一壶用，亦有千金直。"]},{"t":"五月五日泊舟北神与关圣功唐充之李元辅作别意殊惘然端午日行次洪泽把酒北望已如异世事矣因念屈大夫之死正是此日慨然有感于心辄成长韵奉寄李民师翁士时来可求和也","f":"五言古诗","c":["麦上蝴蝶飞，水边鸂鶒卧。","却望山阳城，已若一梦过。","今晨又端午，把酒意亦惰。","风回浪蹙船，闸浅沙著柂。","故人阻情话，客子且清坐。","更念屈大夫，是日遇奇祸。","空馀后世名，第子只增些。","宝璐与明月，皎皎不受涴。","固知汨罗沈，可到首阳饿。","还书二三老，此语君可和。"]},{"t":"赠唐充之兼简益中","f":"七言古诗","c":["三年白沙看江山，可当中原故人面。","今来千里逢故人，笑谈却作江山见。","江山故人不相远，平生志愿于君满。","唐侯独立一代无，张侯与之来集枯。","老松本自岁寒外，良马不畏长途驱。","饥年百室仰粟廪，暑路六月悬冰壶。","念昔关汪不相贷，视世好爵如机械。","上书索去不作难，云我未了平生债。","后生少年延颈观，诸公故人思一快。","基本未定天夺之，赖有君侯数人在。","龙媒已远风驭回，坐叹四海梁木摧。","尔来老谢又继往，但觉眼界常尘埃。","长江无津出光怪，迥野入夜开风雷。","此语不诬君可验，请君更讨防身剑。"]},{"t":"夜雨","f":"五言绝句","c":["梦短添惆怅，更深转寂寥。","如何今夜雨，只是滴芭蕉。"]},{"t":"出门见明月","f":"五言古诗","c":["出门见明月，入门思故人。","故人如此月，一见一回新。","明月相见多，故人相见少。","问尔何因缘，长似此月好。","故人在何处，南北东西路。","明月在咫尺，夜夜庭前树。","明月莫亏缺，故人莫离别。","愿月如故人，故人亦如月。"]},{"t":"往岁在白沙见江上往来祀神者杀猪羊鹅鸭日夕相属也有感于心后至济阴因成长韵当托白沙故人投之庙前庶几神少知自戒乎","f":"五言古诗","c":["今日杀一羊，明日杀一猪。","问神何所乐，而必为此欤。","羊死噤无声，猪死足号呼。","伤哉鸭与鹅，闭目颈已朱。","问神此何负，神亦何所取。","吾知斯民愚，非是神所许。","江船一帆风，江田一犁雨。","民或谢神劳，尚使相告语。","但采涧溪毛，足以荐筐筥。","何须污刀几，而后羞鼎俎。","于物固无怨，于神亦无苦。","更令呜呜歌，时送坎坎鼓。"]},{"t":"济阴野次","f":"七言绝句","c":["去年骑马古城西，雨涴鞍鞯一尺泥。","今日重来转无绪，强扶衰疾绕河堤。"]},{"t":"毛彦谟容膝轩","f":"七言古诗","c":["黄金为楼玉为梯，画旗素锦生光辉。","不如一庵醉而归，倒卧侧立无东西。","君才于用无不宜，会稽竹箭梁山犀。","贾而不售君不疑，亦不自以为珍奇。","渊明妙处君得之，万古一首归来辞。","一庵容膝君所知，不用芥子藏须弥。","望风怀想三归依，眼前有睫见者谁。","世人纷纷不自治，何异羊质蒙皋比。","见豺而战忘其皮，墙头燕雀莫漫肥。","汝不仰看鸿鹄飞，伯夷去采西山薇。","想渠瘦亦不胜衣，不羡汝曹腰十围。"]},{"t":"晁叔用得古镜二一以遗法一上人澄澈可爱底水隐然蜃楼突起又作杯渡禅师像翩然衣动正在中流间也一求记于予因为作歌","f":"七言古诗","c":["晁郎高居卧冰雪，得此悬空两秋月。","已将屋角倒魑魅，更与人间洗炎热。","一月团团如扇面，一月菱花光掣电。","怜君囊中一物无，意欲分君托方便。","菱花入袖世莫识，空堂夜留疏雨滴。","天生宝气有期会，复恐藏去终无益。","君行万里寻剑术，山精唤君君莫出。","寒泉百尺傍枮树，狡兔九月投霜鹘。","未须潘谓苦哦诗，或自苏公识神物。","下有禅和不笑人，须君一照蛟龙窟。"]},{"t":"别离行","f":"七言古诗","c":["城头草木日夜黄，九月北风天雨霜。","月色入户侵我床，美人乃在天一方。","旧游可乐不可忘，恨君不随雁南翔。","恨妾愧守此空房，晓风忽来吹梦长。","梦中与君还故乡，黄金为屋玉为堂。","与君更笑亿千场，不须合佩双鸳鸯。"]},{"t":"李念七久不见过二绝 其一","f":"七言绝句","c":["不随残暑退青蝇，入眼嚣尘渐可憎。","静里工夫君莫厌，夜窗重对短檠灯。"]},{"t":"李念七久不见过二绝 其二","f":"七言绝句","c":["罗襦襟解烛灭后，喝雉喝卢人散时。","愿君莫忘点轩老，少小先蒙国士知。"]},{"t":"往年与关止叔相别甬上止叔见勉学道甚勤且曰无为专事文字间也及今五年矣尚未有所就因作诗见志且以自警也","f":"五言古诗","c":["老关别我时，笑我勤苦甚。","曰吾与子然，同此一味静。","收功粥鱼底，笔墨有讥评。","五年念此语，但见日月竞。","虽无蛾眉斧，亦有晏安鸩。","斯人今何往，想作大树荫。","我走足欲茧，始学两鸟噤。","君看齐声讴，何异众哭临。","繁红成春条，本自其天性。","风雨颂繫之，不有十日盛。","人生亦作聊，共未免此病。","乃知钁头通，已胜狗脚朕。"]},{"t":"六月初三日雨后步至城东","f":"五言古诗","c":["凉秋生郊原，快雨洒庚伏。","曲肱访幽睡，朝梦不可续。","开门招此山，爽气满岩谷。","村蹊没衰草，古院蟠翠木。","东行得幽亭，小径来已熟。","下有十里濠，暑退万荷绿。","恨无沽酒钱，一醉起枵腹。","人生要快意，岂止寄幽独。","若看后池蛙，声韵故不俗。","怡然供清欢，何必丝与竹。"]},{"t":"得扬州书","f":"七言律诗","c":["书来每恨日月晚，书去还忧道里长。","但得老亲常健好，不辞新岁且穷忙。","文章已受尘埃涴，禅观多为疾病妨。","趁得残春北归否，近箕临颍是吾乡。"]},{"t":"归计未成作诗寄怀","f":"七言律诗","c":["万里田园半有无，十年归梦阻江湖。","文章谬忝声名在，气体犹须药饵扶。","客路因风起舟楫，水田无雨卧菰蒲。","青帘白酒斜阳外，不与行人满眼酤。"]},{"t":"阅旧诗卷有怀","f":"七言律诗","c":["好诗无过亦无功，准拟还家赠阿宗。","会有江山与湔祓，且无尘土共从容。","大汪矫矫云间鹤，老谢森森涧底松。","回首百年俱一梦，暮年文采更谁从。"]},{"t":"高邮道中荷花极目平生所未见","f":"七言律诗","c":["绿净红深水不流，炎天烈日自然秋。","只供野父已无计，便与行人亦暗投。","明月不来江北岸，好山应在石城头。","何年得映潘妃步，更放君王作意游。"]},{"t":"高邮遇大热作","f":"五言古诗","c":["南风极炎暑，赤日不可傍。","扁舟在地底，浅水安得强。","坐怀长河冰，未尽暍饮状。","甚憎食案蝇，意欲不相让。","旱苗乾欲死，蒲藕秋可望。","平生投笔手，中有无尽藏。","尔来夜深藏，稳着犊鼻上。","有如三年艾，更复加百壮。","黑云翻日脚，好雨终不放。","雷声无事来，殷殷车百两。","东街暴泥龙，西街设铜像。","利害有不同，未易相得丧。","农夫责催租，日夕困大杖。","那知清歌前，把酒有馀量。"]},{"t":"题孙广伯主簿家壁","f":"七言绝句","c":["古木轮囷老岁寒，好花无力便凋残。","秋风只在盆池上，但见江湖万里看。"]},{"t":"赠孙广伯","f":"五言古诗","c":["人皆笑君拙，我独喜君直。","拙则世所无，直则未易识。","昔者中丞公，事主以一德。","从容进退间，多士所取则。","朝廷九鼎重，冠冕万夫特。","尘埃困大路，此老难再得。","至今门下士，必以身许国。","孰知强弩末，而有百钧力。","贤孙后来秀，见我好颜色。","收功却扫中，欲任门内责。","空弮入善阵，匹马见勍敌。","不嫌不识察，但恨无此获。","欲赤莫如丹，欲黑莫如墨。","吾常持此言，以辨主与贼。","苟无牛羊害，则有天地塞。","君能但拙直，亦莫忘黑白。"]},{"t":"与吴迪吉诸人赴晁季一陈塘范园之游因成十韵","f":"五言古诗","c":["春风未寂寞，频枉故人车。","客舍轻寒下，村烟宿雨馀。","晓红留隐映，新绿上扶疏。","妙墨悬高榜，残章得旧书。","蛟龙忽舒卷，草木自清虚。","渺渺登临地，悠悠水竹居。","只今那复有，本自不关渠。","塘水空遗庙，鼍淙亦故墟。","同行喜佳士，所到即吾庐。","政恐习池饮，风流却未如。"]},{"t":"送晁季一罢官西归","f":"七言古诗","c":["少年阅人若邮传，汉廷公卿日千变。","故人一蹙便青云，咫尺相逢不相见。","丈夫须髯但如戟，黄尘没马渠未识。","晁侯文采老不闻，两耳壁塞目为昏。","三年刺促簿书里，更觉和气生春温。","谁能种兰生九畹，从公不辞堕车蹇。","冰霜入眼蚊蚋去，桃李成蹊草茅远。","胸中沧海无水旱，眼底浮云看舒卷。","顷来江上几送迎，聚蚊成雷公不惊。","笙竽沸地不知晓，公但寒窗延短檠。","乃知风雨昼窈冥，我亦不废晨鸡鸣。","箕山之下颍水边，脱冠便归须壮年。","诸公先寻买山钱，我亦从今当着鞭。"]},{"t":"侯嬴","f":"七言古诗","c":["游士纵横翻覆手，山东诸侯望关走。","历下邯郸无使来，长城易水非燕有。","大梁宾客旧如云，夷门监者未有闻。","谩将苦语送公子，市井屠儿虚见存。","后来毫发争得丧，纷纷小儿誇跌宕。","不知世有公子牟，一生放迹江海上。"]},{"t":"昭君","f":"词","c":["冻云霾空风折木，乌孙公主歌黄鹄。","昭君请自嫁单于，当时各倚颜如玉。","露鬓云鬟胡地尘，帐中谁是可怜人。","左抱琵琶右挥手，胡地汉宫能几春。","呜呼古来出妇嫁乡曲，何曾肯望秦云哭。"]},{"t":"戏呈外弟赵才仲","f":"七言律诗","c":["赵郎风味春月柳，可到阮公青眼边。","秋水黏天剧空阔，晓霜扶月作婵娟。","北来好句传新雁，一夜客愁如少年。","安得琼枝更当眼，沙头同理钓鱼船。"]},{"t":"城北别江子之","f":"五言律诗","c":["但觉与君别，孰知归兴长。","乱畦分宿雨，老木挂晨霜。","未计缘诗瘦，只知如许忙。","他年风雨夜，重约细商量。"]},{"t":"访晁季一","f":"七言律诗","c":["近人鸟雀昆弟语，堆案簿书凫鹜行。","是中亦自有佳趣，公但徐之渠自忙。","西风忽来凉月晓，枫叶芦花秋意少。","劝君多饮莫多谈，截断中流公更参。"]},{"t":"吴君求诗因作四韵寄之并简小吴与宁生","f":"七言律诗","c":["文字缚人同束湿，吴君不言如坐忘。","知公胸中有馀地，万顷亦在一苇航。","寒梢倒挂夜来雨，细草已披秋后霜。","寄语两吴兼小宁，莫因诗律废相望。"]},{"t":"古剑歌","f":"词","c":["寒江九月雷殷空，落日倒射千山红。","江头树木半倾倒，衮衮不尽洪涛风。","风中有物如长戟，电光忽来倾霹雳。","雨罢晴开不复知，乃是潜蛟倚长石。","苍皮半卷颇飞动，涩藓中开欲跳掷。","青荧野火下绝水，夭矫长烟转空壁。","天生神物有时出，岁月飘流为谁得。","铜花欲尽秋水浑，尚有千年妖血痕。","向来天地亦儿戏，俄顷变怪徒纷纭。","君不见丰城之来亦不久，宝气何为上牛斗。"]},{"t":"初夏即事","f":"七言律诗","c":["歌呼连墙亦任渠，移门宾从又何如。","晴阶仰日卧红药，野水趁船跳白鱼。","多病且参箍桶话，得闲时近养生书。","平生不尽幽居兴，付与长江拯钓车。"]},{"t":"偶作","f":"七言绝句","c":["鄙夫养病苦不足，诸公觅官常有馀。","自是闲人不更事，可随云鸟更深居。"]},{"t":"癸已自南京过泗上","f":"七言律诗","c":["昔我往矣天欲霜，今我来思梅已黄。","淮山澡雪尘垢面，鱼稻扫除藜藿肠。","好风肯伴客帆远，故国不辞归梦长。","塔中老人莫相笑，我自寂然渠自忙。"]},{"t":"泗上赠杨吉老二首 其一","f":"词","c":["杯中蛇去无恙，醉里诗成有神。","相逢不及世故，长年倍觉情亲。"]},{"t":"泗上赠杨吉老二首 其二","f":"词","c":["置王坦之膝上，着陈长文车中。","何似维摩丈室，萧然一榻清风。"]},{"t":"题宝应张氏草堂","f":"七言绝句","c":["好风残暑不同涂，稳看饥蚊自扫除。","不谓南轩有佳竹，捲帘相对一床书。"]},{"t":"学仙行","f":"词","c":["长松拂云根合抱，雪虐霜凌不相到。","下有千岁老茯苓，化为琥珀光自照。","食之便可登广寒，不但无病长少年。","浮生溷浊那可言，和气乃为尘务煎。","坐看灵药置泥土，五味杂置成薰膻。","岂不闻齐天子，黄金丹成不肯仙。","且贪人间乐，不能从汝飞上天。","惜哉韦郎之妙语，一失毫釐千万年。"]},{"t":"冬日访朱深明博士二首 其一","f":"七言绝句","c":["北风迎马入裘茸，来访残炉半日红。","败屋数间书百箧，无人知是陆龟蒙。"]},{"t":"冬日访朱深明博士二首 其二","f":"七言绝句","c":["见公便是倚松老，念我不忘担板心。","万里江山一尊酒，主人无古亦无今。"]},{"t":"初别清源姑才仲弟过楚丘作","f":"七言律诗","c":["前村后村鸠乱鸣，梨花点雪柳半青。","断云忽过楚丘县，骤雨已见龙丘亭。","故人愁绪各南北，宿酒别时同醉醒。","语离情绪乃如此，故园可归公不听。"]},{"t":"宿楚丘怀石子植颜平仲赵才仲","f":"五言古诗","c":["暮行楚丘北，适与寒雨值。","旅舍一尺泥，又乏刍秣费。","故人渺天涯，客子初夜至。","披衣附残火，煮茗当晚馈。","昏昏傍晚枕，悄悄入清睡。","向来谈笑声，已若异世事。","但觉舌本间，尚有宿酒味。","鸿鹄乘秋风，意在网罗外。","强饭无多谈，此语敢失坠。"]},{"t":"发召伯埭二首 其一","f":"七言绝句","c":["柳外鹁鸠相应鸣，屋头新月半轮生。","知公未便为官去，且放扁舟自在行。"]},{"t":"发召伯埭二首 其二","f":"七言绝句","c":["晓日烘窗不得眠，夹河高柳乱鸣蝉。","西风种种入愁思，更有长亭十里船。"]},{"t":"余病不能蔬食惧有五味口爽之责作诗自戒","f":"词","c":["君不如屈大夫，夕餐但秋菊。","又不如颜平原，未昼且食粥。","虽知舌本欠滋味，颇觉和气实其腹。","痴人要盈馀，椒有八百斛，钱有一百屋。","鼎俎涴腥膻，杯盘眩红绿。","四方采珍异，亦未极所欲。","宁知下箸处，但有一饱足。","坐偿姓命债，百死有未赎。","何如野僧饭，晚菜下脱粟。","撞钟击鼓坐高堂，童奴唱饭来相续。","竹间新笋大如椽，树头老耳肥于肉。","亦不见蟹躁扰，亦不见牛觳觫。","石郎爱惜韭萍齑，晋侯睥睨熊蹯熟。","以此相重轻，于君未为福。"]},{"t":"南山","f":"五言古诗","c":["南山佳有馀，我病不自得。","今日饮君家，把酒到曛黑。","秋风浩万顷，凉月挂江色。","对此不能欢，何以消偪塞。","人生少如意，百语输一默。","喜逢佳主人，略为解羁勒。","欢然有馀味，即此自温克。","阳春内空洞，隐如一敌国。","世贤首阳饿，我爱郑朝穆。","却怀三年艾，未尽一醉力。","青蝇鬨残暑，小雨频败北。","渐须把蟹螯，莫讣舟摧抑。","君看女儿笑，终胜官事逼。","残杯盖馀沥，慎勿贷鸡肋。","要看知我真，不独观酒德。"]},{"t":"与诸弟诸李同登塔山愚壁以事不能来因成二绝 其一","f":"七言绝句","c":["李家漾南江漫流，幕阜山前春更愁。","无人肯会西来意，且作小诗盟白鸥。"]},{"t":"与诸弟诸李同登塔山愚壁以事不能来因成二绝 其二","f":"七言绝句","c":["道人不来花满山，蹇驴出没松声间。","待约江头今夜月，与渠他日报平安。"]},{"t":"春日二首 其一","f":"七言绝句","c":["春日纷纷一段奇，无言桃李任春欺。","要须及热芦湾去，莫看风吹雨打时。"]},{"t":"春日二首 其二","f":"七言绝句","c":["谁将旧日狂蜂蝶，误入春风桃李蹊。","咫尺风光不相贷，无因乞与上天梯。"]},{"t":"东园","f":"七言绝句","c":["暂开还落不停枝，雨湿东园柳絮稀。","遥想钓船今夜月，暗随潮信与春归。"]},{"t":"即事","f":"七言绝句","c":["经旬无客事亦少，多病闭门身更轻。","我自不能知许事，暮江斜雨送蛙声。"]},{"t":"和李二十七食蛙听蛙二首 其一","f":"七言绝句","c":["膏香未即输鲑菜，煎和真同食蛤蜊。","北人惊叹不下箸，乞与韩公南食诗。"]},{"t":"和李二十七食蛙听蛙二首 其二","f":"七言绝句","c":["莫惊朋类多惊爆，曾伴中郎鼓吹来。","今日属官本渠分，晚江烟雨闹池台。"]},{"t":"题秦惇秀才园亭","f":"七言绝句","c":["秦郎重构水边亭，仿佛疏林过雨声。","更唤清泉入屏坐，少留他日濯吾缨。"]},{"t":"别夜","f":"七言绝句","c":["薄酒残灯欲别情，暗萤依草不能明。","悬知先入他年话，一夜蛙声连雨声。"]},{"t":"寄题苏州灵岩","f":"七言绝句","c":["水分西子采香径，山是吴王避暑宫。","可惜同来不同赏，落花飞絮晓濛濛。"]},{"t":"呈甘露印老","f":"七言绝句","c":["水满南河月满床，市楼灯火隔秋江。","无人可会庵前事，一夜北风吹破窗。"]},{"t":"璧上人欲行为雨止戏成一绝用前韵","f":"七言绝句","c":["东风不借南舟便，细雨轻寒锁暮江。","更想乱山明日路，暮天风雨打船窗。"]},{"t":"江口送璧上人二绝 其一","f":"七言绝句","c":["小雨浮江霜送秋，晓山晴绕读书楼。","道人不作当时面，万里一帆随白鸥。"]},{"t":"江口送璧上人二绝 其二","f":"七言绝句","c":["今日钵囊南去人，当时雕句作新春。","更知自昔相逢意，定是他生骨肉亲。"]},{"t":"送朱时发","f":"七言绝句","c":["眼底家乡不自归，痴人争忍劫前灰。","直饶古庙香炉去，也要披毛戴角来。"]},{"t":"送宁子仪","f":"七言绝句","c":["洪波奔放不停尘，万劫茫茫寄此身。","毕竟无人会休去，满堂栝木不能春。"]},{"t":"唐张琯书记梁时妇人黄鼎因侯景乱没北齐为小校胡儿所虏生二子后附海舶归闻鼓角得岸乃知是会稽郡鼎先在梁许嫁张固及归固适为剡令求与相见不可乃遣令送之宣城鼎在齐时作秋风曲渡海时又作诗三章琯书称其词凄怨自琯时已不传","f":"五言律诗","c":["万里秋风曲，三章渡海诗。","绝胜汉公主，略似蔡文姬。","故国山河在，荒城鼓角悲。","何如觅张固，不用忆胡儿。"]},{"t":"夜坐呈吴迪吉","f":"五言律诗","c":["伏暑不能旱，楚天频复阴。","疾雷冲雨断，乱草接江深。","旧圃可小摘，老盆馀数斟。","明朝有倾倒，相待沃愁吟。"]},{"t":"与李夫言诸人分题得之字","f":"五言律诗","c":["人生行乐耳，此去复何之。","酒忆侯公圣，月如京兆眉。","未须誇敏捷，或恐胜肥痴。","不作别离见，却忧儿辈知。"]},{"t":"访秦氏北庄","f":"五言律诗","c":["午日城西路，篮舆疑旧寻。","稻田疏野水，草径接秋阴。","饭忆分盘玉，书藏遗子金。","不须千里目，枉费百年心。"]},{"t":"喜才仲兄弟至偶成四十字","f":"五言律诗","c":["落日下乔木，好风来暮船。","径思投辖饮，复作对床眠。","寂寂驱愁外，纷纷着酒边。","平生五经笥，不直一囊钱。"]},{"t":"春日","f":"七言律诗","c":["数亩幽畦满小园，儿童无事亦嘲喧。","水摇日影上檐角，风送花香来鼻根。","病去只留花作伴，客来常欠酒应门。","城南旱夌尘埃里，不借春江一尺浑。"]},{"t":"甲午送宁子仪归洛","f":"五言古诗","c":["异时从公游，颇恨相得晚。","同参长芦禅，共听资福板。","公今三年病，我亦百事懒。","春风广陵城，笑语有未款。","嵩阳有归路，河水渐清暖。","岂无一言赠，慰此千里远。","青松老合抱，意不在俗眼。","岂如山上苗，共尽白日短。","一身随药囊，万事付茗盌。","炉烟袅晴窗，自足了迟缓。","奈何孔文举，苦思坐客满。","更知苏门公，远效嵇中散。","舟行傥见念，此语试三反。"]},{"t":"读旧诗有感","f":"七言律诗","c":["但闻微雨响梧桐，不悟高楼尽日风。","团扇向人仍有意，短檠于汝渐无功。","误游兀者形骸外，恐堕渊源云雾中。","剩搅饥肠供好句，为君常占一生穷。"]},{"t":"别后寄舍弟三十韵","f":"五言古诗","c":["还家日已短，况此独行情。","客路三年别，秋帆十日程。","小船携手上，斜柳纵篙撑。","岸失乖龙蛰，窗留素月萦。","重回召伯埭，虚住广陵城。","破屋仍坚坐，残莺只强鸣。","江犹渺漭去，草欲蔓延生。","水缩蛙蟆斗，场空雾雨横。","土风沾疟疠，民俗混蛮荆。","岂识排门入，鱼无倒屣迎。","好诗思共读，薄酒念同倾。","枕席烦团扇，膏油乏短檠。","可无道里念，或恐梦魂惊。","惟昔交朋聚，相期文字盟。","笔头传活法，胸次即圆成。","孔剑犹霄鍊，隋珠有夜明。","英华仰前辈，廓落到诸卿。","敢计千金重，尝叨一字荣。","因观剑器舞，复悟担夫争。","物固藏妙理，世谁能独亨。","乾坤在苍莽，日月付峥嵘。","凛凛曹刘上，容容沈谢并。","直须用款款，未可笑平平。","有弟能知我，他年肯过兄。","初非强点灼，略不费讥评。","短句箜篌引，长歌偪侧行。","力探加润泽，极取更经营。","径就波澜阔，勿求盆盎清。","吾衰足欿㙳，汝大不攲倾。","莫以东南路，而无伊洛声。"]},{"t":"记夜","f":"五言古诗","c":["残暑薰炙人，安梦不得长。","忽蒙千里风，慰此六尺床。","高梧舞清影，上悬明月光。","初知枕簟稳，未厌尘土忙。","中宵有臭虫，其大如蛣蜣。","排闼触屏帐，怒欲凌空翔。","熟视不得名，但见两翼张。","本草所不载，尔雅所未详。","夏虫盛百族，此物尤猖狂。","东窗不得睡，幸无疾病妨。","惜哉有知物，点污此微凉。","人生要更事，美恶无不尝。","悉除粪壤念，顿悟服食方。","去为千丈松，凛然冲雪霜。","慎勿学瓜瓠，置身篱落傍。"]},{"t":"夜坐","f":"七言古诗","c":["广陵城中听夜雨，倒床不眠问更鼓。","西风万里卷长河，遍与淮山洗尘土。","淮南米贱鱼亦好，敢复摧颓叹羁旅。","重帘复幕懒相负，细字寒灯且如许。","漫如尔雅注虫鱼，更就篇章考齐古。","粗知俛首受寒饿，未暇着意寻豪举。","床头有酒不敢饮，况复闺门画眉妩。","故人此去今几时，亦有文字相撑拄。","东明县前济阳路，每一梦至犹能数。","少年不惮道里远，平生未省别离苦。","只今多病须已白，尚能呼渠醉而舞。","田园未还君可恨，岁月渐晚吾何取。","饥虫绕壁不自聊，尔独何情促机杼。"]},{"t":"寄唐充之二十韵","f":"五言古诗","c":["俗事自相促，吾生常作难。","长河已万折，险路复千盘。","坎壈深藏步，岑嵚稳转鞍。","谁知守樗散，略不误泥蟠。","末学多乖谬，微躯寔控抟。","小儿成顶领，烈士吐心肝。","许下少文举，吴中无伯鸾。","直须识根柢，始是极波澜。","念此欲谁语，想公还自宽。","屡成长剑倚，得洗夜虫酸。","解后终年别，殷勤一笑欢。","已除舌本强，仍斲鼻端漫。","直节群公念，高名四海间。","相期更无事，所祝在加餐。","晚日留残雪，春雷续浅寒。","欲行殊未必，坚坐只长叹。","不厌道里远，敢辞裘褐单。","却寻三语掾，重对两蒲团。","剩欲洗胸次，先留倒笔端。","何须灞陵岸，回首望长安。"]},{"t":"竹西亭","f":"五言律诗","c":["十年走尘土，重上竹西亭。","草木新容态，江山旧典刑。","狂风扫毒暑，落月伴疏星。","认取扬州路，荒城一抹青。"]},{"t":"邵伯路中途遇前纲载茉莉花甚众舟行甚急不得细观也又有小盆榴等皆精妙奇靡之观因成二绝 其一","f":"七言绝句","c":["花似细薇香似兰，已宜炎暑又宜寒。","心知合伴灵和柳，不许行人仔细看。"]},{"t":"邵伯路中途遇前纲载茉莉花甚众舟行甚急不得细观也又有小盆榴等皆精妙奇靡之观因成二绝 其二","f":"七言绝句","c":["玉桧盆榴作队来，异香相趁不相猜。","从今闭向深宫里，莫学江湖自在开。"]},{"t":"饮秦少方家","f":"七言绝句","c":["秦郎家畔一瓯茶，何处清凉不是家。","客子三杯玉泉酒，主人一曲浪淘沙。"]},{"t":"孙量臣约游乾明借秦少方韵见赠复次韵答之","f":"七言绝句","c":["睦州香火赵州茶，走遍丛林不着家。","今日为公拈出也，两桥人语是高沙。"]},{"t":"春晚郊居","f":"七言律诗","c":["柳外楼高绿半遮，伤心春色在天涯。","低迷帘幕家家雨，淡荡园林处处花。","檐影已飞新社燕，水痕初没去年沙。","地偏长者无车辙，扫地从教草径斜。"]},{"t":"外姊赵夫人智量以良人没祝发感叹成诗","f":"七言律诗","c":["故人前去冢累累，为恨为忧未肯归。","从有青山可藏骨，却无红泪与沾衣。","饶三笑汝参禅误，晁四怜渠祝发非。","犹胜同侪二三子，枉随秋草闭斜晖。"]},{"t":"代赠","f":"七言律诗","c":["十年流落漫西东，想见谢家林下风。","晋邑自思栾孺子，鲁儒空望叔孙通。","风花已分飘藩外，玉树何情著土中。","纵有春梢堪寓目，却无人面与争红。"]},{"t":"又代赠","f":"七言律诗","c":["略无归梦绕湖湘，漫逐微阴出建章。","月里寒珠一生露，镜中衰鬓十年霜。","逢人莫唱相思调，阅世终无却老方。","想得扁舟北还路，断云衰草更斜阳。"]},{"t":"临川王坦夫故从溪堂先生谢无逸学北行过广陵见余意甚勤其行也作诗送之","f":"七言古诗","c":["王郎别我春已晚，索我题诗敢辞懒。","读书万卷君所闻，只要躬行不相反。","圣人遗言凛可畏，小事未免书之简。","衣冠瞻视有法则，何独文章要编刬。","譬如逆风曳长舰，竭力正在千夫挽。","君行念此须饱参，即是溪堂句中眼。"]},{"t":"登淮南楼","f":"七言律诗","c":["楼上西风日脚斜，楼前广道更人家。","高林稍稍变黄叶，细草重重冒白花。","薄酒尚堪绕舌本，故人何事走天涯。","蓬笼只繫南亭下，乞与寒江整钓车。"]},{"t":"题淮上亭子","f":"七言律诗","c":["亭下长淮百尺深，亭前双树老侵寻。","暮云秋雁且南北，断垄荒园无古今。","露草欲随霜草尽，归樯时度去樯阴。","秋风未满鲈鱼兴，更有江湖万里心。"]},{"t":"夏夜大雨呈若谷叔并晁叔用江子之一上人","f":"五言古诗","c":["中庭电光垂，四壁雨脚溜。","初如单车驰，忽若万马骤。","并墙不相语，灯影照圭窦。","翻思共按乐，日月不得又。","叔能糠覈肥，侄且藜藿瘦。","买田嵩颍间，欲往今已后。","旦夕呼晁江，把酒且相就。","更烦一上人，不语居坐右。"]},{"t":"赠一上人","f":"七言律诗","c":["细褥纱幮卧软绫，岂知秋色到襄陵。","饥乌乍定门门树，宝塔新晴夜夜灯。","晚菜聊充肉一脔，残林才当饭三升。","平生积懒成骄惰，惭愧空房独坐僧。"]},{"t":"久雨路绝宾客稀少闻后土祠琼花盛开亦未果一往也","f":"七言古诗","c":["卧闻更鼓湿不鸣，晓窗但有摧檐声。","云横不放山入坐，风怒欲倒江冲城。","东家酒熟花烂漫，折简唤客留娉婷。","街头泥潦一尺许，意虽欲往无由行。","儒生活计亦不恶，蒲团坚坐到日落。","映窗香穗触凝尘，过眼文书开病膜。","明朝新晴有佳处，稳看小槛翻红药。","无双亭下一枝春，玉洁霜清未寥廓。","闭门懒出君莫笑，看汝多愁吾独乐。","故人无事倘能来，为君试举舒州杓。"]},{"t":"同狼山印老早饭建隆遂登平山堂","f":"五言古诗","c":["尘埃障西风，草木被朝日。","篮舆郭北门，未厌来往疾。","僮奴懒不进，颇复费呵叱。","道人先我行，宴坐已一室。","殷勤劝客住，午饭当促膝。","炉烟窗纸明，鸟语树叶密。","却上平山堂，晚景更萧瑟。","澄江渺天际，妙句不容乞。","平生泉石念，固自有遗失。","何能从儿曹，十事九不实。","兹游岂不快，此老固坦率。","尚从文殊师，一往问摩诘。"]},{"t":"舟行次灵璧二首 其一","f":"七言绝句","c":["往来湖海一扁舟，汴水多情日自流。","已去淮山三百里，主人无念客无忧。"]},{"t":"舟行次灵璧二首 其二","f":"七言绝句","c":["小市荒桥贯浊河，故人虽在懒谁何。","只因远地经过少，更觉新年坐卧多。"]},{"t":"己亥上元数同晁季一叔用清坐不出","f":"七言古诗","c":["北风凛凛吹月高，万木夜作穷猿号。","卧听车马赴尘土，爱此一室明秋毫。","小炉著火晚收焰，短檠照坐寒无膏。","主人忘言客亦懒，更烦赤脚送茗盌。","子云事业本清净，维摩方丈常萧散。","出游苦畏今日闹，归坐略尽平生款。","自知衰病损刚肠，只要文书遮病眼。","公能却扫趁闲暇，渠自低头费牵挽。","明朝乘兴尚能来，咫尺吾庐不嫌远。"]},{"t":"寄李商老","f":"五言古诗","c":["黄尘车马流，金火战残暑。","西风迎潮来，密云复无雨。","江淮旱已甚，映眼但尘土。","田畴杂芜秽，草树翳洲渚。","缅怀平生欢，捐弃各秦楚。","千言偪胸次，到口不能吐。","君非一臂旧，此意复可许。","青蝇暗藩溷，有似嚇腐鼠。","须君济川手，略为虹蜺举。","念之不能眠，清坐听鸣橹。"]},{"t":"晚至城南","f":"五言律诗","c":["来往城南路，今年又作冬。","荒林挂落日，古寺叠疏钟。","职事日三出，交游时一逢。","可怜河上水，唯少莫山重。"]},{"t":"汴上作","f":"七言律诗","c":["不使西风便解维，且留残暑震馀威。","累累野水循河下，摄摄榆虫扑面飞。","五斗漫随王绩隐，一裘聊待晏婴归。","平生事业新诗在，送与江南旧钓矶。"]},{"t":"初抵曹南四首 其一","f":"五言律诗","c":["未辨归山计，今年学作官。","簿书妨好梦，尘土败馀欢。","但有妻孥累，初无肺腑宽。","从来畜鲑菜，不上八珍盘。"]},{"t":"初抵曹南四首 其二","f":"五言律诗","c":["久罢摄生术，虚藏种树书。","病多诗辄废，秋到客仍疏。","约带何辞缓，穿靴不暇徐。","犹胜策高足，辛苦曳长裾。"]},{"t":"初抵曹南四首 其三","f":"五言律诗","c":["并足经庭右，褰裳入座隅。","频容著帽进，雅称折腰趋。","燥吻应难湿，残杯莫强濡。","平生驷跛蹩，今日更长途。"]},{"t":"初抵曹南四首 其四","f":"五言律诗","c":["往时汪博士，劝我便归休。","细雨檐花夜，长江枫叶秋。","欲行殊未必，高卧恐无由。","感叹思亡友，端居可泪流。"]},{"t":"言志","f":"五言古诗","c":["冯驩客传舍，弹铗歌不已。","托身孟尝君，惟有一剑耳。","何事食无鱼，何事出无舆。","先生犹有剑，至我剑亦无。","一来曹南郡，优游聊自娱。","春风吹我衣，春草生庭除。","小便胞略转，晚发手自梳。","仰面送归雁，低头羡游鱼。","幸有薄薄酒，浸渍满腹书。","安得待天命，吾心亦何如。","长铗莫漫弹，何必忆吾庐。"]},{"t":"学道","f":"五言古诗","c":["学道如养气，气实病自除。","验之寒暑中，可见实与虚。","颓然觉志满，乃是气有馀。","岂惟煖脐腹，便足荣肌肤。","但能严关键，百岁终不枯。","道苟明于心，如马得坚车。","养以岁月久，自然登坦途。","江河失风浪，草莽成膏腴。","熟视八荒中，何物能胜予。","时来与消息，吾自有卷舒。","死生亦大矣，汝急吾自徐。","捷行不为速，曲行不为迂。","一沤寓大海，此物定有无。","谁能具此眼，况望捋其须。","学有不精尽，遂至玉珷玞。","昔人中道立，为汝指一隅。","千言不知要，徒自费吹嘘。","所以季路勇，不如颜氏愚。","请子罢百虑，一念回须臾。","忽然遇事入，此语当不诬。"]},{"t":"和赵承之","f":"七言古诗","c":["十日九日昏梦集，职事向人如束湿。","看朱成碧有底忙，然萁煮豆相煎急。","长官抵几入门去，小吏垂头就行立。","尘埃上下久可厌，学问峥嵘老难入。","平生谬欲师古人，遇事始知吾不及。","正须眼底去泾渭，便自胸中无棨戟。","丈夫盖棺事则已，破屋颓墙使谁葺。","要随归雁刺天飞，莫待枯鱼过河泣。"]},{"t":"曹州后囿夜行","f":"七言绝句","c":["衣欲生棱梦不成，城头高下打三更。","月明如昼柳如画，更向瑶池南岸行。"]},{"t":"风吹蒲苇丛三首 其一","f":"五言绝句","c":["风吹蒲苇丛，中有霜堕意。","美人天一涯，行子初夜至。"]},{"t":"风吹蒲苇丛三首 其二","f":"五言绝句","c":["风吹蒲苇丛，秋色日向晚。","美人何时来，行子饥未饭。"]},{"t":"风吹蒲苇丛三首 其三","f":"五言绝句","c":["行子惜日月，美人轻别离。","风吹蒲苇丛，及时当早归。"]},{"t":"曹南试院怀向子諲兄弟兼呈张扩","f":"七言律诗","c":["大向金相玉为表，小向坚车取长道。","闭门不见今几日，尘埃满城何时好。","病夫坐稳百不闻，读书聒人到夜分。","朝来雨过凉气足，思与张侯同叩门。"]},{"t":"试院中作二首 其一","f":"五言律诗","c":["客梦断复续，角声寒更长。","疏篱拥残月，老木犯新霜。","斗絷身何恨，驰驱汝自忙。","稍知诗有味，复恐道相妨。"]},{"t":"试院中作二首 其二","f":"五言律诗","c":["诸生未下笔，客子且安眠。","老觉文章退，官忧簿领缠。","短檠仍有味，高枕自无缘。","但愿无他苦，今年如去年。"]},{"t":"拟古","f":"五言古诗","c":["西邻有佳人，开户纳明月。","月照衣上缨，同心为谁结。","此结今几时，未解心已折。","隔林闻捣练，起坐更呜噎。","情人在万里，我独音问缺。","不闻行路难，但见思归切。","年来契阔久，烈士或丧节。","如何空床居，初未见短阙。","胡马与越鸟，本自无离别。","草摇新霜白，秋送池中竭。","君心有断绝，妾恨无盈歇。"]},{"t":"正月十五日试院中烹茶因阅溪碑","f":"七言古诗","c":["小炉方鼎蛙蚓鸣，那知帘外东风惊。","乱云初破盘凤影，缺月半堕春江明。","已驱簿领出门去，更洗肝肺令愁醒。","大碑古字久寂寞，高堂素壁空峥嵘。","坐看光焰扫尘土，便觉冰霰临窗屏。","文章断绝生气在，妙句直欲无兰亭。","峄山野火烧欲尽，瘗鹤半在江中陵。","不知此书更奇古，反覆餍饫无讥评。","山精地神肯爱护，至今欧虞来乞灵。","要令石鼓举吉日，不必细字临黄庭。","生平访古少如意，对此自足忘经营。","世间儿女争媚好，纸上姓名谁重轻。","迩来半月得坚坐，一室当行千里程。","南楼灯火漫明灭，北里笙竽频送迎。","儒生事业了不恶，故人浮沈吾懒听。","更阑更自取书读，唤起奴仆寻短檠。"]},{"t":"试院夜坐","f":"七言律诗","c":["急雨翻灯夜不眠，小床攲侧似乘船。","平生万事不如意，病后一身私自怜。","海中神仙渺茫里，方外酒徒憔悴边。","本自无心觅馀地，问公何苦爱逃禅。"]},{"t":"清都行","f":"七言古诗","c":["我昔谒帝白玉墀，独驾翠虬骖赤螭。","御风而行过日围，遂登清都游太微。","广殿上建明月旗，缀以列宿悬双蜺。","帝顾而叹怜其痴，寸田不治来何迟。","我拜稽首心自疑，世俗逼隘臣所知。","黜慢之故还无期，后有美人云雾衣。","玉坐交映生光辉，不必翠被缘珠玑。","秘文玉简手自持，见我而笑扬蛾眉。","问我此去来何时，握手赠吾蓝田芝。","汝生甚良学则宜，无自轻厌令神驰。","一来人间今几时，恍如梦觉不可追。","骨肉腥秽颜忸怩，北风吹寒霜露微。","想视倒景凌空飞，却从帝居寻玉妃，为汝更赋无言诗。"]},{"t":"试院中呈工曹惠子泽教授张彦实","f":"七言律诗","c":["十日虚房罢送迎，不知新雁已南征。","忍穷有味知诗进，处事无心觉累轻。","残叶入帘收薄暑，破窗留月漏微明。","知公坐稳无他念，识我阶前拄杖声。"]},{"t":"寄知止","f":"七言律诗","c":["近有书来欲见寻，扁舟南下已春深。","浊河远贯长淮水，峡岸遥瞻宝塔临。","杨子宦游常落拓，茂伦心事转崎嵚。","云横雪拥蓝关路，总是平生愿学心。"]},{"t":"印累累","f":"词","c":["印累累，绶若若，不如相逢一饷乐。","谷量牛马斗量珠，不如闭门细读平生书，居闲意气或有馀。","利害毫发过，不能以手援其躯。","风吹月明，落我庭树。","宿乌夜惊，徐徐飞去。","昼夜有程，汝何不住。","前畏弹射，后畏网罗。","孰视鸿鹄，云霄可摩。","亦知人生，如意少不如意多。","富贵欲长保，执斧不见柯。","印累累如此，宿鸟飞去何。"]},{"t":"曹南过五丈河堤入城访颜岐夷仲清谈久之乃归","f":"五言古诗","c":["春色不自惜，落花如许愁。","晴天一望远，漕水十分流。","每绕长堤去，频因好句留。","相随觅季主，不必贷河侯。","论极文章秘，居兼竹石幽。","和风落香烬，晚日泛茶瓯。","壮节知无用，诸儒误见收。","江山亦在眼，岁月忽忘忧。","南郭今丧我，长卿仍倦游。","漫成长韵律，胜与小蛮讴。","簿领憎频过，尘埃懒再谋。","何须五湖口，风雨转船头。"]},{"t":"雪夜","f":"七言古诗","c":["曹州城南三日雪，半夜疾风吹石裂。","先生睡美唤不闻，不信衾裯冷如铁。","病妻索火少声韵，稚子哦诗应歌节。","残书向人老可爱，旧剑空在磨先缺。","未能去寻泉石伴，未用深藏狐兔穴。","新正已过今几日，岁事懒复从人说。","长江略无千里梦，故人动有十年别。","相逢一笑又艰阻，所向端坐成痴绝。","城中诸公不相弃，时有妙句扶衰拙。","颇知晴意在明日，泥深不怕车轮折。","便当脱帽过君家，共放南窗看新月。","一杯冻酒君莫辞，预借炎天洗烦热。"]},{"t":"曹南官舍书事","f":"五言律诗","c":["去岁头已白，今年眼复昏。","不忧穷刺骨，仍有病伤魂。","酒薄如官冷，年丰荷主恩。","空庭闲草木，终未答乾坤。"]},{"t":"早出","f":"五言古诗","c":["早出公莫厌，此心吾已灰。","严风逸月落，晓气浃霜回。","疾病冲寒怯，衰迟畏事催。","匆匆节渐去，衮衮事方来。","破壁诗犹在，荒城菊半摧。","还家一樽酒，思与故人开。"]},{"t":"寄江端太子之晁冲之叔用","f":"五言古诗","c":["往岁孟秋月，我行东出关。","人烟眇归路，风雨转河湾。","别恨友游失，心成木石顽。","有随妻子叹，无语鸟乌闲。","曩事空回首，微官真强颜。","旧谙尘土迸，频辱簿书颁。","日月勤忧患，庭闱实阻艰。","自忘身窘束，时得泪潺湲。","疾病衰犹活，漂流老未还。","误沾文字癖，虚觉鬓毛斑。","苦语终难好，芜辞漫不删。","绝知出意表，敢复见颜间。","二子今怀璧，群公时赐环。","寄书常恨草，雕句得无悭。","晚照云千叠，新凉月半弯。","相忘有道术，那得厌尘寰。","圣治光三辅，皇威极百蛮。","物能同应瑞，民自不藏奸。","薄技宁堪奏，馀光或许攀。","何须阳翟望，咫尺是箕山。"]},{"t":"两鹤行","f":"五言古诗","c":["西风引湖光，上与月色乱。","化为两白鹤，飞来洞庭岸。","洞庭无网罗，两鹤愿为伴。","鸣声既清好，羽翼又璀璨。","一鹤飞上天，久厌俗眼玩。","一鹤不能飞，摧颓自悲叹。","三年望绝壁，念汝肠已断。","昔既薄恩情，今还恨霄汉。","未忍学鹪鹩，裁求一枝换。"]},{"t":"陵城歌","f":"词","c":["北风吹沙秋草黄，汉家故陵当路傍。","残墓断垄趁风雨，狭径小树行牛羊。","当时王子朝未央，飞燕姊弟承龙光。","大策已定回朝阳，不知外家诸舅忙。","后来变化尤猖狂，佞贤贼莽分行藏。","岂知汉运中更长，济阳舍中方赤光。","终亦变化随飞扬，何独此地令人伤。","人生睹此当自顾，位高金多终此路。","君不见五陵佳气且如此，更复何情说丁傅。"]},{"t":"早至天宁寺即赵州受业院也","f":"五言古诗","c":["残月晓未落，疏星点寒林。","严车城南路，先闻钟磬音。","道人迎我入，共步重廊深。","瀹盏施净供，冰味杂海沈。","蒲团近宿火，不受尘埃侵。","欲求半日息，簿领勤相寻。","东堂老禅师，枯木尚龙吟。","一转庭前柏，诸方疑至今。","我生晚闻道，所向足崎嵚。","谬传无字印，尝恐力不任。","淮海罢行役，吾人多滞淫。","于焉一枕梦，可见平生心。"]},{"t":"曹南寄亲旧","f":"七言律诗","c":["净名居士默无语，翰林子卿虚见寻。","半世泥涂催老大，中年诗律费光阴。","江湖每有同归志，酒炙初无独饱心。","三尺枯桐取煨烬，断弦遗谱有知音。"]},{"t":"大雪不出寄阳翟宁陵","f":"五言古诗","c":["簿书终岁忙，风雪一日静。","闭门近残火，稍觉诸事胜。","平生汗漫游，已负麋鹿性。","微官不能归，但见日月竞。","老人去已远，我行复未定。","训言实在耳，无因问温凊。","归心止阳翟，悲梦识新郑。","大女痴无比，有语多未听。","小女索乳啼，不与穷屋称。","想唤添丁来，与汝相和应。","低头坐儿曹，气血安得盛。","非无车马心，未忍求捷径。","顾自阻饥寒，畴能免讥评。","诸郎何时逢，相作玉树映。","文章有活法，得与前古并。","默念智与成，犹能愈吾病。"]},{"t":"与宁陵叔弟别后有怀兼寄赵才仲二首 其一","f":"五言律诗","c":["一别又经月，欲来浑未期。","宁知万卷读，难疗十年饥。","长物新添女，生涯旧有诗。","更伤新况味，不报老亲知。"]},{"t":"与宁陵叔弟别后有怀兼寄赵才仲二首 其二","f":"五言律诗","c":["表弟今何在，中郎亦漫游。","平生足艰阻，今日倍迟留。","误辱琼瑶报，兼蒙札翰投。","南窗五更月，常照别离愁。"]},{"t":"大雪不出","f":"五言律诗","c":["晶晶日欲出，翻翻风自横。","近阶三尺雪，附火一杯羹。","老树春难别，深檐乌或鸣。","新春第三日，坚坐若为情。"]},{"t":"自曹南至阳翟追怀江上旧游呈叔弟","f":"七言律诗","c":["醉别白沙江上亭，晚蝉高树各秋声。","风乘小艇凫鹥进，雨历疏檐环佩鸣。","家事不随王事了，新愁常接旧愁生。","只今疲病嫌鞍马，十日同居眼暂明。"]},{"t":"自阳翟至宁陵与虚已叔诸弟别还曹未久知止复来偶成二十八字","f":"七言绝句","c":["绿遍墙头杨柳枝，小亭春尽阻归期。","头昏目暗无情绪，不比少年离别时。"]},{"t":"试院中作","f":"七言律诗","c":["职事侵人畏作官，略偷身去不能还。","树移午影重帘静，门闭春风十日闲。","尚有文书遮病目，却无尘土犯衰颜。","故人何处蓬笼底，看尽江南江北山。"]},{"t":"去冬试院中尝作诗云衣敝虱可舍发垢栉不下披衣坐墙角尚有微火跨平生足拘窘今日幸闲暇新文加点窜欲歇不能罢虽微尘事妨颇畏俗子骂出门见诸老此语君可画今年复入试院职事多窘迫者簿书满前如赴蹈汤火也再次前韵","f":"五言古诗","c":["谁令君作官，衮衮簿书下。","谁令君不学，陷阱乃欲跨。","缅怀北窗翁，斯人盖多暇。","田畴望家远，日月已秋罢。","尚蒙诸公怜，未至官长骂。","何时归来图，更作一段画。"]},{"t":"雨后数与李仲辅兄弟往来且约十七日同过士特因成长韵","f":"五言古诗","c":["邻鸡再三鸣，不改风雨晦。","束装向前涂，恐与泥潦会。","故人时一来，共此一室内。","微言久已绝，苦语或未遂。","子孙甚奇古，却立有馀地。","旧从伯氏游，则已闻令季。","斯文倘未远，吾今尽憔悴。","相期无何乡，获保清净退。","收身稠人中，着眼世事外。","山空倚岩石，雪立老杉桧。","往来相遇难，更自少如意。","旦日过城南，把酒公一醉。"]},{"t":"首夏二首 其一","f":"五言古诗","c":["生平寡嗜欲，颇愿得少闲。","尽读未见书，遍寻云外山。","往来二十年，昔者盟未寒。","妻子见驱迫，低头言作官。","朝翻朱墨案，暮对藜藿盘。","岂无一亩宫，令汝得少安。","向来栖息地，苔竹奉馀欢。","何时二三子，共驾牛车还。","汝实江海人，误令尘土干。","旧游在彷佛，欲往当不难。","但去眼界窄，自然心地宽。"]},{"t":"首夏二首 其二","f":"五言古诗","c":["空庭下疏箔，乐此树荫美。","鸟声相续来，百种皆可喜。","日长少文字，俗事不到耳。","开窗略须夜，月露欣瀰瀰。","颇念闲居乐，感叹投笔起。","吾家老清源，爱我入骨髓。","还家治场圃，唤我共料理。","会同江海去，更欲附船尾。","平生跨款段，不敢废鞭箠。","谁云马中龙，一日有万里。","卜邻吾所知，江晁老兄弟。"]},{"t":"问晁伯宇疾二首 其一","f":"五言古诗","c":["晁子卧京城，岁月晚不用。","偷身出尘土，闭户忍疾痛。","客来不与语，有口吾懒动。","今年又请老，气力当少纵。","生平厌笔墨，弃去不复弄。","颇念白头亲，甘旨须子奉。","呻吟不衽席，妙语时一讽。","谁令稻粱谋，未答泉石梦。","鄙夫托未契，义实忧患共。","天定或胜人，寡固不敌众。","请公但缩手，保此清净供。","因书报安否，兼与问群从。"]},{"t":"问晁伯宇疾二首 其二","f":"五言古诗","c":["取骥伏盐车，更欲絷其足。","于物未有害，罚汝则已酷。","晁子江海士，老去自窘束。","平生万卷书，岂止十年读。","随身几箱箧，一一手自录。","初无解衣赠，未免操戈逐。","仲也抱瑚琏，幼亦好奇服。","西堂老弘微，与子同轨躅。","过门有江谢，共语喧破屋。","弃官吾已懒，覆种子未孰。","逢人强应接，遇事多诟辱。","何时把锄头，得止季路宿。"]},{"t":"商村河决","f":"七言律诗","c":["今年河口决商村，远望飞涛匹马奔。","曲港定无蛟鳄横，下田甘受雨泥浑。","衣裳虮虱藏针缝，头面尘沙露爪痕。","犹恐因循葬鱼腹，故人无地与招魂。"]},{"t":"新霜行","f":"五言古诗","c":["新霜下幽兰，昔在顾眄间。","时过理当尔，敢复致一言。","物生无荣贱，悉是君所见。","相值有相违，谁能满吾愿。","田园弃荒芜，官居走邮传。","误寻文字盟，秣马当百战。","一饭或未饱，逢人足嫌怨。","穷于投林猿，窘若巢幕燕。","忍学少年子，羽翼偷绚练。","百万买缠头，千金奉娱宴。","愿为匣中玉，不作秋后扇。","丈夫重许与，正尔未为倦。","绝粮有不死，酒肉虚健羡。","古人马伏波，吾犹识君面。"]},{"t":"将去曹南连得江晁书因叹存没诸友遂成长韵","f":"五言古诗","c":["西风脱残暑，我病不自聊。","吏舍少还往，亦复长蓬蒿。","欣然脱帽去，念此非一朝。","阳翟未遽往，宁陵虚见招。","初无食息地，未免柴水劳。","故人数遗书，尚有江与晁。","穷途感节义，俗耳受风骚。","向来相知人，昔盛今寂寥。","落日送汪谢，荒小留老饶。","关侯最杰立，亦以膏自烧。","后生有向子，更尽儿女娇。","出门天夺之，不令上云霄。","坐看朋友泪，未减春秋褒。","怪我但羸疾，误蒙风雨摇。","日月费奔走，文章勤琢雕。","会须领妻子，更欲投吾曹。","耆旧唤归隐，诸公怜久要。","出同赴鸡黍，归但守箪瓢。","相将访云山，所至杂渔樵。","还当古渡口，卧听西江潮。"]},{"t":"精卫诗","f":"词","c":["西山有鸟，其状如乌。","名曰精卫，其名自呼。","精卫堙海，不堙不止。","问谁之报，云帝之子。","帝子女娃，往游不还。","精卫求之，不敢有安。","海流不改，汝堙不迁。","嗟哉精卫，志则可怜。","我昔读书，惟圣之求。","竭力从之，以春及秋。","老人宴居，审吾之学。","惟时友朋，日就雕琢。","圣言甚微，吾意则近。","近以识微，退或有进。","三年于曹，惟罪之恐。","人虽甚厌，子亦不勇。","舒舒其云，沄沄其水。","子不与归，而曰有以。","豕羊在牢，刍秣之恋。","烹庖及之，抑又谁怨。","予学日远，子道日疏。","有愧精卫，其谁与居。","精卫之飞，不必戾天。","子之不如，宁有智焉。","惟作与否，愚智之择。","小人作诗，惟一劝百。"]},{"t":"宁陵弟相送至南京因成四韵寄季一子之叔用","f":"七言律诗","c":["白发无端巧上头，镜中颜状不能羞。","要寻扬子一廛地，未用刘公百尺楼。","野竹连阴护苍藓，暮云生雨续黄流。","秋风有信鲈鱼在，更约江晁共小舟。"]},{"t":"十一月一日步河堤上","f":"五言古诗","c":["簿书纠缠人，欲出不自许。","老叟环我前，更作附耳语。","脱身上河堤，颇似昼伏鼠。","河堤平如掌，下有千岁土。","夕阳敛残照，草木过寒雨。","游鱼著钩饵，舟子快新煮。","煮鱼得放饭，尚叹行役苦。","江湖平生心，岁月可逆数。","故人书断绝，吾事有去取。","归来讨清尊，妙句还一吐。"]},{"t":"留侯","f":"五言古诗","c":["留侯下邳时，豪气或未除。","晚节欲轻举，效在黄石书。","其书本无言，一叹三呜呼。","彼公实天人，识此鹓凤雏。","良田有芜秽，令子痛自锄。","万事不得已，一身常晏如。","袖手默无语，四方瞻步趋。","不知隆准公，果能知子无。","小儿荀彧辈，下及崔浩徒。","谓能明子心，此语亦已诬。","不能处其知，正足杀其躯。","所恨生已晚，圣门无坦途。","学不尽其才，未免风俗驱。","诗书在煨烬，子何不回车。","试问礼之本，更观心地初。"]},{"t":"送韩撝秉则赴棣倅","f":"五言古诗","c":["公如玉壶冰，见即离烦热。","况当清秋悬，更自贮霜月。","中边本无垢，何处觅焚爇。","盛以百鍊铜，此亦不得折。","初蒙一日款，遽有千里别。","扁舟转青齐，岁事当雨雪。","远行不赢粮，已悟服食诀。","古来饕餮徒，颇谓一世杰。","唾壶彼何知，便为如意缺。","观其所用心，俱不异鼠窃。","首阳独往人，渠自饱薇蕨。","举头公一笑，百虑无以绝。","江源初滥觞，末乃流不竭。","伤哉韝上鹰，一饱便飞掣。"]},{"t":"读秦碑","f":"五言古诗","c":["秦人跨九州，欲以传万世。","立石名山傍，往往章得意。","至今见遗刻，字体甚雄异。","壮哉苍藓文，未改回屈势。","风雨所侵蚀，中有千丈气。","严如虬龙蟠，深若铁石利。","馀威到山鬼，谨守敢失坠。","汉魏能书人，亦岂可睥睨。","未能识藩篱，何止趁姿媚。","初无一日雅，但有三舍避。","文章又奇古，迁雄盖苗裔。","观其所称述，肯为尊者讳。","巧言未大失，末乃为俗累。","呜呼结绳前，此又谁与记。","君臣共无为，垂拱天下治。","春秋纪日月，大易垂彖繫。","嬴氏厌休息，动以衡石计。","斯翁变古文，程邈分篆隶。","自此更滋蔓，日以趋简易。","驰驱千百年，漫有纸笔费。","谁能罢烦文，尽扫诸天外。","此书虽见存，或以少为贵。","持此槁木枝，我亦无甚愧。"]},{"t":"次韵答曹州同官兼简范寥信中","f":"七言律诗","c":["好诗有味终难舍，俗事无功莫羡渠。","破历屡翻深瓮酒，短檠时检旧窗书。","何年鸡黍先投社，是处田园可结庐。","更请二公搜好句，一身疴痒要爬梳。"]},{"t":"龚彦承观轩","f":"五言古诗","c":["爱山不能归，常恐山怪责。","终岁在行役，感动头已白。","高秋强僮仆，路过龚掾宅。","蒙君开南轩，除我眼界窄。","白波绕青嶂，彷佛见颜色。","江上飞来峰，却立对君侧。","萧萧蒲苇丛，不受尘土隔。","知君有奇趣，笑我常偪仄。","人生无穷已，得一乃愿百。","床头贮美酒，窗下著好客。","请公但默然，岁晚当有获。"]},{"t":"画马图","f":"七言古诗","c":["平沙远草春未生，万木夜起争悲鸣。","秋云欲坠都护垒，急雪暗下屯田营。","胡人却走畏深入，汉家飞将已云集。","此时一马直万钱，陇右河湟更供给。","边尘净尽今百年，万马潦倒西风前。","天生骏骨例艰阻，是处雕鞍蒙受怜。","君家九幅开新帐，欻见腰袅华堂上。","长鞭不用羁络远，雾縠云罗倚惆怅。","高旌袅袅霜露微，苜蓿得雨连山肥。","同时战士今不归，曹霸弟子能神奇。","毫端妙处君得之，驽骀往来空尔为。"]},{"t":"堤上","f":"七言律诗","c":["落花吹尽不堪忧，只见河堤水漫流。","晚日强穿城北市，春风犹驻驿南楼。","妻孥转觉为身累，岁月终难望汝留。","万里长江一樽酒，故人何处倚扁舟。"]},{"t":"将赴海陵出京治泎觅舟候送客不至遂行","f":"五言古诗","c":["子行殊未来，我马已再秣。","略投故人饭，苦厌从者聒。","长河见舟楫，尚恐尘事夺。","风翻蝉急噪，雨漱岸欲脱。","南山已在眼，想望淮水阔。","别离古所重，况在交友末。","翩然欲行际，所寄一短褐。","路长书来稀，何以慰饥渴。"]},{"t":"京师新郑与诸晁兄弟往还前后数诗 其一","f":"五言律诗","c":["夜语不嫌久，凛然天欲秋。","客灯吹屡灭，细雨落还休。","未许金张并，虚为鄠杜游。","江河少归梦，知为故人留。"]},{"t":"京师新郑与诸晁兄弟往还前后数诗 其二","f":"五言律诗","c":["我发日已短，公愁安得长。","墙根春荠老，瓶水腊梅香。","侍立无天女，相随有漫郎。","平生湖海兴，今夜宿连床。"]},{"t":"京师新郑与诸晁兄弟往还前后数诗 其三","f":"五言律诗","c":["发短各已白，眼昏谁复明。","残春断花柳，晚日闭柴荆。","潦倒书常废，驱驰梦或惊。","尚于团聚乐，虽老未忘情。"]},{"t":"京师新郑与诸晁兄弟往还前后数诗 其四","f":"五言律诗","c":["今弟穷颜蠋，书生老仲舒。","相招得共处，何往更安居。","岁月尘埃外，桑麻雨露馀。","送行无别物，圮上一编书。"]},{"t":"京师新郑与诸晁兄弟往还前后数诗 其五","f":"五言律诗","c":["苦语相留极，虚床会宿频。","山东今出相，海内不无人。","妇女能尊客，儿童不厌贫。","长途有如遇，今日倍情亲。"]},{"t":"本中将为海陵之行念当复与子之作别意殊愦愦偶得两诗上呈并告送与壮舆叔用也 其一","f":"五言古诗","c":["斯人如玉雪，可爱不可忘。","助以濯沧海，亦复閟馀光。","今兹困尘土，更伴众翼翔。","时来唤我语，共此一榻凉。","风雨来颊舌，冰霜清肺肠。","我老渐窘束，公才方颉颃。","春秋有体制，子盖能文章。","要当纂微言，不以近故妨。","粲然东园花，不登葵藿场。"]},{"t":"本中将为海陵之行念当复与子之作别意殊愦愦偶得两诗上呈并告送与壮舆叔用也 其二","f":"五言古诗","c":["老仆倦日长，羸马困道远。","东行数日间，尚欲一再款。","我能喻子意，子亦识我懒。","追怀十年游，仅得一笑莞。","时能煮汤饼，更复下茗盌。","晁郎本京邑，刘子盖楚产。","江山两秀异，与子日在眼。","南风动归兴，感慨毛发短。","相寻倘有日，岁月亦未晚。"]},{"t":"雁","f":"五言古诗","c":["雁从何方来，云自燕赵北。","今当何所往，暖日近旸谷。","寒云堕江汉，未见所栖宿。","朝忧稻粱少，暮畏罗网逐。","惜哉还往频，愈觉岁月促。","悔不近藩篱，随群伴鸡鹜。","羽干何必好，志愿亦易足。","物生有高下，终恐厌摧伏。","公看沧海头，万里飞鸿鹄。"]},{"t":"赴海陵行次宝应","f":"七言律诗","c":["半升浊酒试莼羹，贱买鱼虾已厌烹。","浅水依蒲有船过，淡烟笼月更人行。","交游潦倒肠先断，疾病侵陵涕自横。","北望中原一千里，故人谁复唤归耕。"]},{"t":"海陵杂兴八首 其一","f":"五言律诗","c":["四海今谁托，飘然未有归。","先生作诗瘦，稚子食言肥。","未忍萤枯死，甘随鹢退飞。","故人取坚坐，不为赋无衣。"]},{"t":"海陵杂兴八首 其二","f":"五言律诗","c":["相见各已老，壮怀如昔然。","蛟龙夜改穴，风雨暗移船。","把酒犹堪醉，逢人懒问禅。","还家有馀地，留我买山钱。"]},{"t":"海陵杂兴八首 其三","f":"五言律诗","c":["诸老今无恙，秋来数寄声。","尚能无事饮，犹胜不平鸣。","行李虚长铗，生涯共短檠。","江湖日在眼，恐负白鸥盟。"]},{"t":"海陵杂兴八首 其四","f":"五言律诗","c":["荒城足风雨，今日更新冬。","草木山岚暗，人家水影重。","漫看文字过，时有簿书逢。","目极横塘路，西楼闻暮钟。"]},{"t":"海陵杂兴八首 其五","f":"五言律诗","c":["曾子不复见，斯人绝可怜。","梦回千嶂里，气夺万夫前。","异日文章社，平生香火缘。","高楼更南望，霜露倚江天。"]},{"t":"海陵杂兴八首 其六","f":"五言律诗","c":["万事不如意，自然添白须。","极知少馀韵，何敢厌穷途。","土俗尊鱼婢，生涯欠木奴。","东行见李白，谁为致区区。"]},{"t":"海陵杂兴八首 其七","f":"五言律诗","c":["空山鹤夜鸣，海风令人惊。","对月且愁思，看书终眼明。","斗酒不为薄，客帆那计程。","犹怜他夜雨，曾作打窗声。"]},{"t":"海陵杂兴八首 其八","f":"五言律诗","c":["轻帆载晓月，和梦到扬州。","木落山光寺，江横北固楼。","漫抛王倕隐，虚有十年游。","尚胜刘师命，才因越女留。"]},{"t":"往来送迎城南道中二绝 其一","f":"七言绝句","c":["破裘重补却胜寒，暗减头围觉帽宽。","数顷桑麻绕城路，每随妓吏去迎官。"]},{"t":"往来送迎城南道中二绝 其二","f":"七言绝句","c":["海气如烟跨市楼，北风连夜舞梧楸。","平生事业难牵强，坐听寒灯守聒囚。"]},{"t":"家叔舍弟与黎介然会于符离因用两绝奉寄 其一","f":"七言绝句","c":["漫约同归久未偿，只今留滞各他乡。","春风有信勤归雁，夜雨何时复对床。"]},{"t":"家叔舍弟与黎介然会于符离因用两绝奉寄 其二","f":"七言绝句","c":["老觉为官百不宜，故人虽在鬓如丝。","遥知再踏同游地，更想汪饶曳杖时。"]},{"t":"病中夜闻雪作时尧明有广陵之行未归思为数语奉寄久之未就他日尧明归携诗相过飘然有御风凌云之气因以前诗答之","f":"五言古诗","c":["公方他山行，我此一室病。","拥炉听夜雪，若与风势竞。","萧条中疑休，狼藉久未定。","平明望屋瓦，入我眼界净。","所恨子猷远，无复肯乘兴。","想当岩壑间，玉立与辉映。","时来有杰句，遂入风雅正。","寒威固深避，草木自温凊。","公家鹤氅翁，韵与羲皇并。","流风及远孙，笔力如此劲。","雕缋或过眼，惟我乃弗称。","新春上河堤，梅柳当历聘。","过从不厌数，荒畴取微径。"]},{"t":"次韵尧明贡院诗","f":"五言古诗","c":["忍穷不能归，强饭亦良计。","东风频报春，草木可次第。","厌为龙头缩，宁作龟尾曳。","从来翰墨场，即有闻见滞。","譬如已耕田，更欲深种艺。","或蒙卤莽报，未肯即卖弃。","不闻太仓粟，亦校毫发细。","王卿固倦游，秽浊有蝉蜕。","声名动时人，我实托末契。","泥涂倒屐齿，尘埃涴衣裌。","要为无用用，乃作不事事。","下马旧战场，午日在庭戺。","向来槁木枝，忽有红绿缀。","来非偶然住，去亦无所诣。","聚蚊著瓯中，得听此鹤唳。","窗前有馀馥，胜韵入松桂。","扁舟下淮南，闾里思少憩。","熟观昔所历，请与居士戏。","江湖要同归，不假木兰枻。"]},{"t":"海陵夜作","f":"七言古诗","c":["夜长夜长天复霜，海陵城中今夜长。","夜长夜长冬向晚，寒阶无人看月满。","路长家远来信稀，水阔山深归梦短。","堂上书生头已白，朔方健儿十年客。","想渠当此夜长时，抚剑虽长酒杯窄。","明妃爱惜汉宫衣，乌孙公主终不归。","戚姬去视鸿鹄举，更为君王作楚舞。","当此夜长谁送迎，此月还如今夜明。","夜长夜短公莫厌，寒即重裘热须簟。","夜长夜短公莫忧，多忧多厌公白头。"]},{"t":"秋夜行","f":"七言古诗","c":["八月九月啼寒螀，十月北风天雨霜。","客游无聊思故乡，乡书不来空断肠。","鸿飞何为满夕阳，举头揽取明月光。","置我堂上方天床，满酌玉杯碧淋浪。","唤取姮娥来共尝，人间欢乐寿命长，不须辛苦老桂傍。"]},{"t":"腊梅","f":"五言绝句","c":["学得汉宫妆，偷传半额黄。","不将供俗鼻，愈觉更清香。"]},{"t":"洞庭","f":"五言古诗","c":["尝闻洞庭湖，秋至清皎洁。","往来八百里，长风驾明月。","中有仙人居，容颜若冰雪。","我愿从之游，问渠传宝诀。","脱冠着霞佩，长与尘世别。"]},{"t":"细雨","f":"五言律诗","c":["细雨不成雪，北风来解纷。","冥冥小江树，漠漠暮空云。","谁惜江东弟，令修地下文。","西齐千万里，遗恨不堪闻。"]},{"t":"王阳","f":"五言古诗","c":["王阳作黄金，才了车马费。","苦身邀声名，未免遗俗累。","何如陶渊明，萧散尘世外。","公田二顷馀，觅酒偿一醉。","高风久寂寞，斯文若旒缀。","白眼看世人，此意渠不会。"]},{"t":"题赵丞瑞薏苡图","f":"词","c":["甘泉殿中芝九茎，不与百草同条生。","当时祥瑞已稠叠，薏苡亦未来争衡。","汉星不容矍铄翁，此物不与明珠同。","尔来万物更变化，薏苡宁甘死荒野。","故遣根苗霜雪白，炯若微月来清夜。","赵郎好事古亦无，俯拾傍观尽图画。","画师不辞粉绘费，遇时亦得千金价。","君不见古来异瑞与奇祥，何曾不致南宫下。"]},{"t":"即事","f":"五言古诗","c":["清阴庭中槐，绿润墙外草。","职事苦见妨，令人恶怀抱。","朋从多飘徙，今我独枮槁。","高床书数帙，时节岂不好。","不能遂尔去，但觉归思浩。","人情便久习，世态嫌衰老。","闭门了残诗，昔者迹已扫。","何时北窗风，清尊为君倒。"]},{"t":"寄晁以道","f":"五言古诗","c":["朝辞陉山清，暮宿赖水绿。","往来百里间，得此意已足。","吾人少如愿，夫子更绝俗。","闭门观易象，未用伤局促。","使我三日留，共此一室独。","皎如岭头月，凛若霜后竹。","欲为斯文寿，以作学者福。","洛阳佳少年，抚事多恸哭。","此其于圣学，何异狗尾续。","宁知草玄翁，万事不挂目。","深湛而雅澹，亦不在反覆。","吾祖早闻道，晚与夫子熟。","相期千载外，未得一世伏。","渫山窜鼯鼬，晚日度鸿鹄。","谁能从公游，岁月如转烛。"]},{"t":"桥上口占二首 其一","f":"七言绝句","c":["城北城南柳絮飞，街东街西鹁鸪啼。","海陵三月与春别，一夜雨成三尺泥。"]},{"t":"桥上口占二首 其二","f":"七言绝句","c":["风雨属连春事休，十日九日转城头。","虽无俗物败人意，可使澄江消客愁。"]},{"t":"次韵逊叔直门见寄兼请尧明同和","f":"七言律诗","c":["纷纷尘土计秋豪，忽送长江八月涛。","陶令且为州祭酒，邓公才可掾功曹。","但看秋到犹絺绤，即是花时合缊袍。","待得公归吾已老，满田荼蓼与谁薅。"]},{"t":"雨后至城外","f":"七言律诗","c":["日日思归未就归，只今行露已沾衣。","江村过雨蓬麻乱，野水连天鹳鹤飞。","尘务却嫌经意少，故人新更得书稀。","鹿门纵隐犹多事，苦向人前说是非。"]},{"t":"庞公","f":"七言绝句","c":["卧龙雏凤不曾闲，举世皆危子独安。","应念桥公无特操，晚将情话向曹瞒。"]},{"t":"卫青","f":"七言绝句","c":["将军相继出天山，汉主吞胡意未阑。","本自无心接宾客，故人犹有一任安。"]},{"t":"杂诗三首 其一","f":"五言古诗","c":["烹葵去王畿，剥枣在海角。","岁序忽已周，月亦频告朔。","向来手中扇，今此已倦捉。","尚嫌簿领繁，不厌朋友数。","尘埃向奔走，文字费雕琢。","途人有前知，子乃独未觉。","出门见大路，夫子焉不学。"]},{"t":"杂诗三首 其二","f":"五言古诗","c":["结发在简编，俗事方刺促。","往来三十年，未见可栖宿。","微官不能去，尚恐遭逼逐。","归栖则在念，所望一枝足。","频蒙故人误，岂有邻可卜。","出门虽无车，径自骑黄鹄。","重寻置锥地，青灯一盂粥。"]},{"t":"杂诗三首 其三","f":"五言古诗","c":["饥蚊青而化，怒目虬两须。","黄昏与我遇，且复少踟蹰。","肌肤恣啖齧，熟视不可驱。","中宵盛徒党，意气若有馀。","伤哉陷阱虎，有时被囚拘。","求食至摇尾，曾此蚊不如。","云龙困蝼蚁，此语不可诬。"]},{"t":"秋日三首 其一","f":"七言绝句","c":["诸卿谈笑赏先登，我欲从之病不能。","门闭日长公事少，祇疑身是住庵僧。"]},{"t":"秋日三首 其二","f":"七言绝句","c":["尘满文书灯暗檠，荒城相望数残更。","莫言愁罢无佳处，睡正熟时闻雨声。"]},{"t":"秋日三首 其三","f":"七言绝句","c":["往来奔走看渠忙，疾病低回却未妨。","唤客不须嫌酒恶，隔墙时喜送橙香。"]},{"t":"橙二首 其一","f":"七言绝句","c":["西风吹雁欲斜行，小槛寒花却未香。","将谓诸公频载酒，枉留橙菊十分黄。"]},{"t":"橙二首 其二","f":"七言绝句","c":["不辞玉露著新行，漫作人间彻骨香。","知道输棋偿旧约，故留残菊一时黄。"]},{"t":"寄京师亲旧","f":"七言古诗","c":["屋头橙实如李梅，庭下葵花深覆杯。","豆田失雨不称意，野菊出苗虚见猜。","故人相望一尊酒，问我此住何时回。","江山空自污敲扑，笔砚洗复生尘埃。","交情自惜少同调，人事只今多好乖。","欲随明月觅公处，限以白浪摇长淮。","舟楫误逢蛟鳄横，岁月苦遭霜露催。","侧身西望莫回首，堂上书生心已灰。"]},{"t":"和成士瑴鹿女泉诗","f":"七言律诗","c":["成子东游十日程，驼裘颠倒帽攲倾。","新诗顿数神仙事，病耳忽闻京洛声。","去住闲经几尘刹，往来相望一牛鸣。","再寻六月山前路，分我寒泉数勺清。"]},{"t":"春申君","f":"七言绝句","c":["少年谈笑解秦兵，便欲连从却未成。","莫谓江东可长保，暮年无意引朱英。"]},{"t":"秋日三首 其一","f":"五言律诗","c":["罢马厌鞭策，征鸿思稻粱。","终年在泥土，永路困风霜。","慎勿鞍鞯爱，直须矰缴防。","吾衰亦已甚，念尔不能忘。"]},{"t":"秋日三首 其二","f":"五言律诗","c":["交游大半死，吾亦老相侵。","古木十围大，寒泉百尺深。","恨犹能切骨，愁或至伤心。","寄语南飞雁，君无笑苦吟。"]},{"t":"秋日三首 其三","f":"五言律诗","c":["狱掾酸寒极，官曹冗长催。","真同鹤久住，不学雁轻回。","妇女能相笑，儿童忍见猜。","犹怜旧耆老，时有一书来。"]},{"t":"和成士瑴海安道中见寄","f":"五言律诗","c":["成侯老更懒，处世一虚舟。","暂脱尘埃梦，还寻江海秋。","从来仙圣宅，不数凤麟洲。","有意相随否，因公更一游。"]},{"t":"送虞澹季然之官京师","f":"七言古诗","c":["车如鸡栖马如狗，劝君莫美循墙走。","车如流水马如龙，不如还家行御风。","以尻为轮神为马，世人计出车马下。","出门险阻道里远，只今谁是能行者。","海陵事剧俸则薄，得公相从亦不恶。","小吏相欺官长怒，我自作烦公笑乐。","庾公故是丰年玉，道貌更自见不足。","断崖独立老松柏，青天何处飞鸿鹄。","汴堤六月尘自障，请公登高更南望。","马烦车怠早归来，且从夫子濠梁上。"]},{"t":"海陵病中 其二","f":"七言绝句","c":["先生高卧了残冬，我亦年来不讳穷。","夜半打窗人不会，满天风雨角声中。"]},{"t":"海陵病中 其三","f":"七言绝句","c":["客游历历都如梦，身事悠悠略似僧。","只么随缘作官去，不知从古更谁曾。"]},{"t":"海陵病中 其四","f":"七言绝句","c":["往来车马闹泥涂，一室萧然百事无。","语默二途俱不涉，不劳辛苦对文殊。"]},{"t":"海陵病中 其五","f":"七言绝句","c":["久谙罢卧懒呼医，剩读文书不疗饥。","数有故人来问疾，更烦耆旧与传诗。"]},{"t":"次韵季叔友贺尧明登第叔友丹阳人也本中得其人之详于王尧明恨未之识也尧明擢第叔友作诗贺之尧明令继作既喜叔友能不妄许可又嘉尧明进退取舍皆中乎道也三首 其一","f":"七言绝句","c":["柴桑无复陶元亮，谷口虚传郑子真。","二子风流知有在，且留馀味及吾人。"]},{"t":"次韵季叔友贺尧明登第叔友丹阳人也本中得其人之详于王尧明恨未之识也尧明擢第叔友作诗贺之尧明令继作既喜叔友能不妄许可又嘉尧明进退取舍皆中乎道也三首 其二","f":"七言绝句","c":["澄江虽近不容亲，亦是人间可喜人。","枯木岩前有岐路，一杯浊酒自成春。"]},{"t":"次韵季叔友贺尧明登第叔友丹阳人也本中得其人之详于王尧明恨未之识也尧明擢第叔友作诗贺之尧明令继作既喜叔友能不妄许可又嘉尧明进退取舍皆中乎道也三首 其三","f":"七言绝句","c":["二子深居笔吐虹，从来节气万夫雄。","欲知圣主求贤意，不为相如词赋工。"]},{"t":"次韵尧明见和因及李萧远五诗 其一","f":"七言绝句","c":["小阁才堪置一床，病躯虽在鬓沧浪。","随身行李无长剑，犹胜堆钱与窟郎。"]},{"t":"次韵尧明见和因及李萧远五诗 其二","f":"七言绝句","c":["交游潦倒漫虚名，误结他生文字盟。","踏尽尘埃公莫厌，不应因酒爱江清。"]},{"t":"次韵尧明见和因及李萧远五诗 其三","f":"七言绝句","c":["故人飘散各穷途，诸老交情却未疏。","赖有清诗在书案，时时翻读伴更初。"]},{"t":"次韵尧明见和因及李萧远五诗 其四","f":"七言绝句","c":["万里星河指顾间，此中何自著江山。","精金百鍊终无用，才与佳人照指镮。"]},{"t":"次韵尧明见和因及李萧远五诗 其五","f":"七言绝句","c":["阮公游宦喜东平，贺监从来忆四明。","但得从容饱粗粝，不须辛苦辨肴鲭。"]},{"t":"西归舟中怀通泰诸君","f":"七言律诗","c":["一双一只路傍堠，乍有乍无天际星。","乱叶入船侵破衲，疾风吹水拥枯萍。","山林何谢难方驾，诗语曹刘可乞灵。","酒碗茶瓯俱不厌，为公醉倒为公醒。"]},{"t":"寄马巨济察院时监泰州酒得宫祠归南京","f":"五言古诗","c":["新春款南园，积雨寒不歇。","起望海陵城，幸未还往缺。","闻公得安还，未放车轨折。","毫端倒江海，胸次湛明月。","东风片帆来，乃复为此别。","田园到荒芜，岁事有曲折。","不见南山松，高卧拥霜雪。","鬓髯凛可畏，此岂念容悦。","愿公考其然，一向鼻头说。"]},{"t":"寄赵十弟","f":"七言律诗","c":["十年流落各西东，再见初非旧阿蒙。","晋邑自思栾孺子，鲁儒空望叔孙通。","宦情潦倒三荒径，世味衰颓一秃翁。","石室度筹吾岂敢，且看鲜健胜庞公。"]},{"t":"叔度季明学问甚勤而求于余甚重其将必有所成也因作两诗寄之 其一","f":"五言律诗","c":["两章后来秀，头角固崭然。","但语强弩末，不争驽马先。","寓言有十九，曲礼至三千。","所要在守节，末言能与权。"]},{"t":"叔度季明学问甚勤而求于余甚重其将必有所成也因作两诗寄之 其二","f":"五言律诗","c":["念我少年日，结交皆老苍。","曹南见颜石，甬上拜饶汪。","敢幸江海浸，得沾藜藿肠。","诸郎但勉力，馀事及文章。"]},{"t":"与季宏子植同过信中饮薜荔亭下夜分乃散别后奉怀遂成长韵","f":"七言古诗","c":["残花无言卧风雨，小亭寂寞延初暑。","范侯置酒呼我来，共坐阶前洗尘土。","坐间问有李与韩，文字峥嵘各奇古。","起卧逡巡失杯杓，笑语澜翻杂歌舞。","满城车马閧侵淫，谁解墙阴着樽俎。","薜荔扶疏出枝叶，老气横空君一吐。","人生此会不可常，昔者各在天一方。","簿书相急如探汤，好风吹我来君旁。","莺啼燕乳各自忙，明日酒醒空断肠。"]},{"t":"秋日呈颜夷仲","f":"五言古诗","c":["老去身已衰，事过意愈懒。","斯人未寂寞，吾此归亦晚。","疏篱带落叶，秋色忽已满。","南窗可炙背，唤妇同茗盌。","旧读无新功，亦复费编纂。","凝尘乱朱墨，妙句折编简。","往者荷蓧翁，实具世外眼。","不能与之游，只有兴尽返。","曹南二三老，夙昔荷推挽。","平生万卷书，未尽一日款。","微词绝端兆，自怪识者罕。","愿闻片言佳，庶用收褊短。"]},{"t":"谢任伯夫人挽诗","f":"五言古诗","c":["幽兰在深山，无人终自芳。","岂伊桃李颜，取媚少年肠。","高氏有潜德，奕世被辉光。","自其父祖来，低首不肯昂。","夫人生既贤，岂止秀闺房。","出身事夫子，和鸣更锵锵。","笙镛列两序，圭币罗中堂。","云何去日远，遂弃凌风翔。","伋也奉慈训，将见久必昌。","瞻彼汝南路，松柏泣新霜。","凄然马鬣封，千岁终不亡。"]},{"t":"赠笔工安伋","f":"七言古诗","c":["昔人三年学屠龙，技成不试身已穷。","安生不愿洴澼封，嗜好乃与屠龙同。","使世淬砺磨其锋，侧出逆曳求新功。","伋也中立无适从，随所欲用吾能供。","歙溪孕石南山松，四方万里时一逢。","病夫乍闲百念空，败毫破管尘埃蒙。","明窗净几聊从容，眼无列宿罗心胸。","使汝得见文章公，展卷略书吾已慵。"]},{"t":"寄共诚贾秀才","f":"七言绝句","c":["万里归来四壁空，旧游浑在默然中。","明年我欲江南去，何处留诗可寄公。"]},{"t":"题大名官舍","f":"五言绝句","c":["宿昔尚残暑，晚风吹欲无。","不知留此住，更白几茎须。"]},{"t":"秋日即事四首 其一","f":"七言绝句","c":["瓦炉香烬欲凝尘，小槛黄花更一新。","络纬戒寒鸠唤雨，世间那有自由人。"]},{"t":"秋日即事四首 其二","f":"七言绝句","c":["鬓发苍然雪欲垂，问君何苦读书为。","旁人不会回头意，犹记田光盛壮时。"]},{"t":"秋日即事四首 其三","f":"七言绝句","c":["簿书尘土乱蒙茸，无复江船万里风。","卧听秋声满檐溜，不知墙下有梧桐。"]},{"t":"秋日即事四首 其四","f":"七言绝句","c":["何处螳螂欲捕蝉，主人初未觉鸣弦。","稍知东里能堪事，一任神龙斗洧渊。"]},{"t":"闰月九日","f":"七言绝句","c":["疏林渺渺下新霜，留得黄花小槛香。","莫道穷秋少风味，一时顿有两重阳。"]},{"t":"恶木","f":"五言古诗","c":["恶木不忍伐，留我窗户前。","人皆笑我拙，我独为汝贤。","共生天地间，谁不愿长年。","如何枝叶内，便纵斤斧穿。","人或甚于斯，同被恩爱缠。","燕昭与汉武，所享固已偏。","乐极未肯休，更欲求神仙。","孰能以此心，扩为无尽泉。","大哉周文王，尚结枯胔缘。","伤生有禁止，亦具月令篇。","好木虽云好，不须公爱怜。","恶木虽云恶，莫自生雠冤。","岁晏霜雪稳，夏深雷雨颠。","扶疏有震落，与公常晏然。"]},{"t":"江上二首 其一","f":"五言律诗","c":["南山稍疏阔，病眼不能明。","月挟清霜下，风随细浪行。","未蒙青鸟信，虚负白鸥盟。","不见台城路，年年春草生。"]},{"t":"江上二首 其二","f":"五言律诗","c":["甚欲从此去，作烦渠未休。","风期竹万个，活业橘千头。","汉水觅二老，青门寻故侯。","情知作寒士，不解杀袁刘。"]},{"t":"寄外弟蔡明善","f":"七言律诗","c":["相见还须未白头，只今君是富春秋。","莺花与梦飞腾去，甲子如川日夜流。","白酒可浇千卷读，青山欲唤十年愁。","无因早办归耕计，更就深公买沃洲。"]},{"t":"秋夜","f":"七言律诗","c":["鸣鸠唤雨入西楼，草树虫声旋作秋。","明月自如常夜好，晚山仍发去年愁。","久抛诗酒寻思去，胜与儿童作队游。","辜负禅心多少事，石城看渡木兰舟。"]},{"t":"蛇","f":"七言古诗","c":["山云楼起风旋磨，百毒乘阴出相贺。","中庭夜夜蛇作堆，草堂病夫愁欲破。","时须兵子设符咒，更遣狸奴旁坐卧。","虽非当道白帝子，恐是多年老书佐。","蛟龙变化未可量，草莽连岗足逋播。","农夫催租正苦辛，莫向零陵作奇货。"]},{"t":"谢新酒螃蟹","f":"七言绝句","c":["提壶满送小槽春，尖团未霜亦可人。","略借毕郎左右手，为公一洗庾公尘。"]},{"t":"寄诸子","f":"五言律诗","c":["南国旱愈甚，西郊雨复休。","蝇蛆作残暑，蛙黾斗清秋。","草暗黄沙尽，风吹白日愁。","祇应有相忆，时倚仲宣楼。"]},{"t":"湘水","f":"五言绝句","c":["湘水一番竹，下有千亩阴。","宁知竹上泪，是妾一生心。"]},{"t":"顷与知止相别于曹州西门外盖今十四年矣闻尝自澶渊过此感叹","f":"五言律诗","c":["昔别是兹土，今游还偶然。","似闻尝少憩，犹自未真传。","所过有陈迹，相逢多少年。","长涂守病马，何敢更争先。"]},{"t":"双庙","f":"七言古诗","c":["唐四叶孙德下衰，久厌坐稳思奔驰。","外由骄胡内艳妻，杨李气燄相夺移。","太宗之业甚整齐，尔曹忽来撞㨋之。","旁人为之掩涕悲，处之甚安渠不疑。","贼风忽来吹白陂，翠舆走避弯弓追。","倒立却视千熊罴，猛将不解河北围。","睢阳失守东南危，城中月馀析骨炊。","两公奋髯死不回，鼎镬在前惟恐迟。","蜀中消息未可期，此辈未易折箠笞。","念公不量势力微，本自不辱国士知。","大厦又非一木支，何必感慨如此为。","往时开元全盛时，公胡不念鲈鱼归，亦不往吊湘江累。","死后声名何足奇，商山老人吾所归。"]},{"t":"归自成园","f":"五言古诗","c":["新春今几时，忽有檐外朵。","病眼久不明，念此岁月颇。","桥南数亩园，风雨与关锁。","主人厌敲门，荆棘生道左。","还家续残章，妙句仍帖妥。","虽无炉锤工，亦有盘礴裸。","归帆渺江湖，宿疾眩风火。","扶犁伴老农，此语当自我。","君看乡闾斗，则有闭户可。","慎无学春蚕，作茧自缠裹。"]},{"t":"与诸舍弟游董村","f":"五言律诗","c":["来往无十里，颇能妨昼眠。","疏篱董村水，远树洛城烟。","酒薄诗牵强，身闲病接连。","荒田点残雪，知在甬山前。"]},{"t":"见信民旧书有感","f":"七言绝句","c":["蜗涏狼籍阁残书，仿佛黄公旧酒垆。","试问东山谢安石，不知能似此人无。"]},{"t":"同叔用宿子之家","f":"五言律诗","c":["老足交亲薄，江晁尔独贤。","文章未遽绝，岁月成堪怜。","薄酒宁非道，寒灰却会禅。","犹须五湖口，风雨夜同船。"]},{"t":"游西池归","f":"五言古诗","c":["偶为池上游，入郭天尚早。","香尘入晚雾，柳色映驰道。","我马亦未疲，归路贪月好。","还舍了无事，百念纷未扫。","近店酒可沽，重当为君讨。"]},{"t":"出顺天门归阳翟二首 其一","f":"五言古诗","c":["迟明出都城，夹路多柳色。","行人半歌哭，莽不见阡陌。","西池已春晚，我复道里迫。","枯田甚渴雨，久作龟兆拆。","屡遭人马饥，更悟坡垄隔。","微官恋升斗，恐负朋友责。","初无秦楚遇，亦有陈蔡厄。","沉忧能伤人，今汝头已白。"]},{"t":"出顺天门归阳翟二首 其二","f":"五言古诗","c":["渊明在柴桑，意亦惮远役。","岂无好事人，助子了耕植。","还家赋归来，破自悔平昔。","向时经由地，风雨晦行迹。","欣然倚南窗，谓此可容膝。","孰知刘檀辈，生有五鼎食。","流风未遽远，此士真有力。","伤哉谢太傅，辛苦至折屐。"]},{"t":"新郑路中","f":"词","c":["柳絮飞时与君别，南楼把酒看新月。","月似当年离别时，柳絮随君何处飞。","落花寂寂长安路，陌上十人九人去。","准拟归鸿寄得书，回头已失秦州树。","丈夫薄情多可念，尔独何心守贫贱。","劝君以金屈卮，赠君以长短歌。","城南城北春草多，明月如此奈愁何。"]},{"t":"离新郑","f":"五言律诗","c":["荒村更柳色，节物近清明。","去国三年恨，还家一日程。","故人投晓别，骡马傍山行。","何事逢寒食，春来苦要饧。"]},{"t":"宿颍昌范氏水阁","f":"五言古诗","c":["溪流浅无声，月色初到竹。","主人中夜归，客子睡已熟。","向来湖海兴，岁事方窘束。","云何蟋蟀歌，更自伤局促。","相寻觅旧约，见子故未足。","翛然解衣卧，高枕被数幅。","贤哉五年别，有此一室独。","我须日已白，子发良未秃。","尚怀平生欢，歌呼声彻屋。","何须豕腹胀，更伴狗尾续。","明朝寻故人，戏语公一读。"]},{"t":"闻南寇已平欢快之甚作诗五十韵","f":"五言古诗","c":["日月开南极，山河拱上都。","圣朝频决胜，贼党莫狂图。","驿道传烽燧，官军下舳舻。","弄兵心已壮，渫血气犹粗。","腊月杭州破，驩声歙县屠。","迹虽连劲越，势欲动全吴。","剑戟排空上，刍粮夹路输。","予方在衰杖，意不保头颅。","岂谓除关传，都非验汉符。","坐看前乘没，谁救左轮朱。","守将仍安枕，乡豪肯弃躯。","百川归巨浸，一命仰洪炉。","抚事思同辈，低头失壮夫。","风雷蛰龙卧，名字列仙臞。","遇寇来淮口，迎家傍海隅。","未随霜雪死，甘伴甲裳趋。","每有妻孥问，宁知道里虞。","荒城补泥土，旱水著菰蒲。","交友多流寓，人烟乍有无。","相逢可恸哭，掩泪只长吁。","羽檄迹锋数，江船取路迂。","艰难脱纷扰，润泽到焦枯。","屡辱分金送，兼容折简呼。","同群见鸑鷟，猛兽伏于菟。","往往投僧饭，时时就客厨。","苦留春骀荡，勤对色敷腴。","不有沟中断，其如屋上乌。","身犹访安佚，意独离囚拘。","行李催归疾，生涯与旧殊。","裹粮违战地，举足值穷途。","误厌韩城僻，虚随颍水纡。","旧书犹酱瓿，破屋但绳枢。","蒋诩空三径，杨雄更一区。","生平从学圃，老复厌为儒。","爱草骑驴稳，看云借杖扶。","几年供坎廪，尽室付崎岖。","触热医频唤，倾囊酒漫酤。","素冠穷偪仄，白发鬼揶揄。","侧转骥絷足，往还狼跋胡。","众怜东郭困，自学北山愚。","取别方摇扇，成诗欲断壶。","疏篱倒禾黍，骤雨落楸梧。","苦语终难好，清谈却未须。","家犹近坟墓，晚或望桑榆。","今日祅氛涤，新秋暑气苏。","如闻旧巢覆，尽伏逆臣诛。","遣卒宽平贾，令民内半租。","文章元典则，刑赏旧规摹。","桀恶先函首，渠魁已献俘。","书地问安否，尚足慰驰驱。"]},{"t":"还韩城三首 其一","f":"五言律诗","c":["乍喜全家脱，虚疑匹马奔。","乾坤德甚大，盗贼尔犹存。","稻垄秋仍旱，溪流晚自浑。","素冠兼白发，愁绝更谁论。"]},{"t":"还韩城三首 其二","f":"五言律诗","c":["老有幽禅着，穷知俗事疏。","渐谙深屋病，无复故人书。","日月驰驱后，江山疾病馀。","新凉有佳句，端为述离居。"]},{"t":"还韩城三首 其三","f":"五言律诗","c":["读易初无说，言诗既有功。","客游千里异，心事一尊同。","药裹难休老，经函可御穷。","江淮足知遇，耆旧忆徐公。"]},{"t":"秋日至孟明庄","f":"七言律诗","c":["野色幽花静有馀，好山虽近不同途。","荒村被雨泥三日，草具留僧饭一盂。","断垄入秋频放水，老农垂手怕催租。","平生粗识田园兴，更复何门可曳裾。"]},{"t":"韩城纪事五首 其一","f":"七言绝句","c":["老耻为儒不学禅，还家常欠买山钱。","成州太守怜衰病，时有书来说太玄。"]},{"t":"韩城纪事五首 其二","f":"七言绝句","c":["糠豆犹悭不到盘，小儿寒至尚衣单。","虽无事业传惇史，或有声名托稗官。"]},{"t":"韩城纪事五首 其三","f":"七言绝句","c":["稳看飞虫着网黏，炉香欲尽不须添。","未嫌秃顶如壶赤，何处香醪似蜜甜。"]},{"t":"韩城纪事五首 其四","f":"七言绝句","c":["病来每有为僧兴，老去初无涉世心。","它日三江五湖口，断云寒水有知音。"]},{"t":"韩城纪事五首 其五","f":"七言绝句","c":["老不谋身望子公，少年豪气想元龙。","倚松庵下香严路，今日书来第一封。"]},{"t":"阳翟冬夜","f":"五言律诗","c":["便往吾何敢，长闲力未能。","寒炉夜篝火，急雪暗翻灯。","唤客初无酒，敲门尚有僧。","不嫌空四壁，相对倚枯藤。"]},{"t":"孟明田舍","f":"七言律诗","c":["未嫌衰病出无驴，尚喜冬来食有鱼。","往事高低半枕梦，故人南北数行书。","茅茨独倚风霜下，粳稻微收雁鹜馀。","欲识渊明只公是，尔来吾亦爱吾庐。"]},{"t":"宿田舍","f":"五言律诗","c":["饥肠不贮酒，冻粟自生肤。","旅枕三年梦，荒村一事无。","不愁风折木，时有火添炉。","尚想崔夫子，冬来体更臞。"]},{"t":"除日","f":"五言律诗","c":["我食已并日，子来能隔年。","溪山出城路，风雪探梅天。","纳息初闻妙，翻经旧有缘。","相陪得清坐，不敢叹无毡。"]},{"t":"将游嵩少题石淙","f":"七言古诗","c":["南山吐云柳絮飞，北山之外烟草微。","南山北山日在眼，问公此去何时归。","石淙山水更奇绝，水怒决石山崩摧。","长空无声晓色静，忽听万壑悬惊雷。","珊瑚缺折玉破碎，月落倒卷从天回。","中流险绝不须道，笑侮滟滪怜离堆。","平生好事心突兀，时于图画见仿佛。","褰衣度水公莫畏，何须苦避蛟龙窟。","明朝更作嵩少游，五更绝顶看日出。"]},{"t":"登太室绝顶","f":"五言古诗","c":["生平仰嵩丘，今日上绝顶。","苍天不能高，星斗閟光景。","风云乍起伏，雷雨半苏醒。","下看飞鸟背，错乱松柏影。","神龙不深遁，偃蹇卧半岭。","旧闻飞石斗，不受悬瀑梗。","大河东北流，渺渺黄数顷。","五更看日出，平地涌金饼。","谁能啜其华，夜气初未冷。","诸峰环而立，一一皆秀整。","中居此丈夫，众象不得骋。","巍然万物表，独阅百代永。","同来有奇士，可得一笑领。","不用贮微言，区区吊箕颍。"]},{"t":"与崔德符田元邈别后奉寄","f":"五言律诗","c":["处僻犹多事，陪公得暂闲。","直缘怕酒去，不为忆家还。","苦语知无策，微官直强颜。","高城更南望，林断有青山。"]},{"t":"出游","f":"七言律诗","c":["日日春浓病不知，偶游僧寺送春归。","长年误跨将军马，渐老空悲游子衣。","山路有泥知雨过，村场无酒验人稀。","今秋定作江东计，趁得鲈鱼八月肥。"]},{"t":"董村归路马上口占","f":"七言绝句","c":["水声高下竹回环，薄酒无功不耐寒。","白塔忽从林外出，青山常在马头看。"]},{"t":"嘲拄杖","f":"七言绝句","c":["王郎赠我桄榔杖，三岁庵中伴我闲。","只为懒行常靠壁，不能随我过嵩山。"]},{"t":"朮煎","f":"五言古诗","c":["断苗取灵根，斸石不到土。","道人扫落叶，闭户手自煮。","晴烟溜窗几，初夜过风雨。","老盆酌天醴，春瓮发膏乳。","檐囊到城市，馈我一勺许。","中年血气败，今我饮此醑。","色如胶饴重，味有荷心苦。","京城旧交游，臡醢乱鼎俎。","谁能供此饮，远视鸿鹄举。","一洗肝肺尘，但咽公勿吐。"]},{"t":"有客","f":"七言律诗","c":["燥砚渴水不濡笔，浊酒欠钱长卧瓶。","此中定自有佳处，纸帐蒲团增眼明。","故人江南江北岸，千书不如一见面。","人生欢会不可常，画梁已送西飞燕。"]},{"t":"李文若季敌访余高安留连累日临行赠之","f":"七言古诗","c":["十年奔走风尘中，学殖不进身愈穷。","梦断江南不得往，坐叹岁月如惊鸿。","君家政当匡庐路，时有僧行附书去。","每念君家草堂好，便欲移家就君住。","当时气象已参差，今日情怀况迟暮。","斯文未丧欲谁托，交游十人九不乐。","百川东下障狂澜，伯兄嶷然如断山。","苍苍在上久无意，空使妙句留人间。","两季只今名籍籍，北方人士所未识。","未歇中原胡马尘，且喜沙头风浪息。","高安相遇一长吟，盛夏苦雨成淫霖。","顾我无能甘畎亩，如君岂合在山林。","豫章老矣栋梁在，莫厌它时斤斧寻。"]},{"t":"木芙蓉","f":"七言绝句","c":["小池南畔木芙蓉，雨后霜前著意红。","犹胜无言旧桃李，一生开落任东风。"]},{"t":"食笋","f":"五言古诗","c":["穷乡未寂寥，五月富笋茁。","近山新得雨，此物晚亦发。","初看数寸出，意有千尺拔。","长条不成鞭，乃以美见伐。","锦绷罢骈头，玉指已不袜。","坐令藜藿口，如受滫瀡滑。","连年江海病，未免鱼蟹罚。","甘津到齿颊，恐此或未察。","居闲快一饱，我已久断杀。","更莫厌比邻，时时听羹戛。"]},{"t":"白须","f":"五言绝句","c":["不作韩城住，虚为河朔行。","白须镊更出，知为阿谁生。"]},{"t":"宿刘固寺佛殿下即刘伶坟也","f":"五言律诗","c":["刘伶坟上土，佛殿古崔嵬。","坐久野僧出，天寒饥雁来。","千年醉里魄，一锸死前灰。","未尽先生意，空留数字回。"]},{"t":"怀卫道中寄京师诸友三首 其一","f":"五言古诗","c":["客舍冷如浆，客梦甘如饴。","初无远行念，况有徂年悲。","平生好交游，大半走路岐。","不如亭前月，所到长相随。","何时脱身去，共采西山芝。","有儿当似公，尚能传我诗。"]},{"t":"怀卫道中寄京师诸友三首 其二","f":"五言古诗","c":["直莫如两王，清莫如两方。","孙谢岂不美，久滞尚书郎。","黎子老归国，只今须鬓苍。","邵子住山云，欲出未肯忙。","高子出林壑，坐看天际翔。"]},{"t":"怀卫道中寄京师诸友三首 其三","f":"五言律诗","c":["人谁不小康，李赵常窘束。","穷阎爨温火，老未饱饘粥。","它长未遽数，此事已绝俗。","为人死不厌，自奉一米足。"]},{"t":"河堤","f":"五言古诗","c":["平田接长河，眼界起突兀。","今日兹堤行，麦垄青已出。","客行不知晚，但感此节物。","新霜被西山，久厌尘土没。","坐怀故人面，于此见仿佛。"]},{"t":"寄浚州张掞","f":"七言绝句","c":["张卿留客酒如渑，我欲从之病不能。","忆过公家更东望，断崖高树雪层层。"]},{"t":"田家乐","f":"七言律诗","c":["东家西家蚕上簇，南村北村麦白熟。","小儿腰镰日早归，大儿去就田间宿。","斗酒相邀不为薄，邻翁相对且斟酌。","圣主当阳亿万年，年年岁岁田家乐。"]},{"t":"梅","f":"五言绝句","c":["独自不争春，都无一点尘。","忍将冰雪面，所至媚游人。"]},{"t":"寄崔德符","f":"五言律诗","c":["江城昔还往，耆旧各能文。","暂别犹相忆，虽忙亦见存。","好诗能愈疾，浊酒不胜浑。","它日经行地，相寻夜叩门。"]},{"t":"还家","f":"七言律诗","c":["解鞍歇马倦西游，过眼文书且罢休。","薄酒向人殊有味，长年于世已无求。","常情未语沟中木，俗眼能惊海上鸥。","何处云山不堪隐，更谁辛苦访菟裘。"]},{"t":"即事","f":"七言律诗","c":["晚菘早韭老不厌，夜鲤晨凫多见疏。","地僻难寻野僧饭，路长时枉故人车。","青山出没尘埃里，白发栽培疾病馀。","更有腐儒穷事业，夜窗残烛一编书。"]},{"t":"读易","f":"五言古诗","c":["春温疮疥繁，衣敝虮虱细。","颓然坐南轩，读易初有味。","初看象数殊，忽此爻彖异。","纷纷者众说，行各半途滞。","大言累千百，杂说记一二。","坐令天人分，复以小大计。","或强出枝叶，或自起旒赘。","孰能言语表，能使意独至。","空中本无华，眼病因有翳。","沈思忽有得，是则入精义。","吾生晚闻道，岁月今少憩。","遗经日在眼，似足了一世。","临流濯垢衣，尚勿惜馀弃。"]},{"t":"复往大名三首 其一","f":"五言律诗","c":["复往真无策，兹行亦漫游。","尘埃走剧暑，风雨占新秋。","便欲还家去，其谁为汝谋。","尚怜苏季子，虚敝黑貂裘。"]},{"t":"复往大名三首 其二","f":"五言律诗","c":["我老不自得，每为饥所驱。","漫抛青箬笠，空负白髭须。","见贼犹堪斗，逢人莫问途。","寰区足秀句，山泽有臞儒。"]},{"t":"复往大名三首 其三","f":"五言律诗","c":["地湿频经水，田荒亦未收。","断云催雨过，涨水没桥流。","半世想高卧，十年悲远游。","藜羹不用挟，尚足诳饥喉。"]},{"t":"闻德道中","f":"五言古诗","c":["五更发荒村，小憩草市北。","披衣度积水，月落天正黑。","豆苗半委地，野父厌匍匐。","我马则已饥，泥土污羁勒。","翻思在家时，一饭亦假贷。","小儿不解事，笑语颇自得。","一官走道路，此责久未塞。","速行勿迟留，有手须击贼。"]},{"t":"阳翟道中","f":"五言绝句","c":["不为伤离别，其如渐老何。","秖应从此去，转觉白须多。"]},{"t":"长葛道中遇周原仲","f":"七言古诗","c":["羸马冲寒骄不驶，积雪残冰杂泥滓。","长葛县中日落时，举头忽见周夫子。","下马相看两惊怪，各喜南归此身在。","僧房夜语久不眠，更摩枵腹偿诗债。","子行四方尚谋食，我亦年来倦行役。","枥下骅骝世得知，海底珊瑚人未识。","长安公卿富贵客，谁能日在子思侧。","洛阳年少未宜轻，看子重陈治安策。"]},{"t":"简叔易益谦兄弟","f":"七言绝句","c":["秋来归兴复何如，李范声名更羡渠。","它日买田吾有策，两家兄弟要邻居。"]},{"t":"赠益谦兄弟","f":"五言古诗","c":["范郎走微官，清固不绝俗。","家常四壁立，腹有万卷读。","迩来所为文，深若泉万斛。","纡馀风过水，宛转虫注木。","诸弟况可人，不但好眉目。","丹穴固出凤，蓝田自宜玉。","行扛九鼎重，顿使一世伏。","圣朝急用士，如子尚穷独。","乃知德在躬，不必富润屋。","我病拙文词，笔钝如发秃。","时逢子兄弟，未语心已足。","长空绝纤埃，何处著凫鹜。","朝来秋气清，伫看飞鸿鹄。"]},{"t":"题芦雁扇","f":"五言绝句","c":["雁下秋已晚，江天风雨微。","宁为聚沙立，不作傍云飞。"]},{"t":"游西宫有感","f":"五言古诗","c":["种种不如意，悠悠无复听。","漫寻村路好，似得片时醒。","水隐城坳白，山来树杪青。","晚田收袯襫，残日度笭箵。","兴入山阴道，诗如历下亭。","荒原子胥庙，千载想仪刑。"]},{"t":"送一书记果公作天宁化士","f":"七言律诗","c":["田家得米输官仓，一粒不得囊中藏。","天宁化士去如雨，此亦未易能低昂。","因官乞取民始病，况复妄邀檀越敬。","纵令不得半钱归，堂中圣僧应自知。"]},{"t":"京城围闭之初天气晴和军士乘城不以为难也因成四韵","f":"五言律诗","c":["贼马侵城急，官军报捷频。","民心皆欲斗，天意已如春。","魏阙方佳气，王畿且战尘。","不妨来往路，经月绝行人。"]},{"t":"守城士","f":"五言古诗","c":["北风且莫雪，一雪三日寒。","不念守城士，岁晚衣裳单。","衣单未为苦，隔壕闻战鼓。","杀贼须长枪，防城要强弩。","炮来大如席，城头且撑柱。","岂不知爱身，倾心报明主。","报主此其时，一死吾亦宜。","未敢望爵赏，且今无事归。","寄语守城士，此言君所知。"]},{"t":"闻军士求战甚力作诗勉之","f":"五言古诗","c":["今春贼来时，军士怖而走。","今冬贼来时，决拾揎两肘。","愤然思出斗，不但要死守。","仰怀吾君仁，愈觉戎虏丑。","欲以占天心，于焉卜长久。","暂劳何足道，富贵要力取。","行看斩贼头，金印大如斗。"]},{"t":"丁未二月上旬四首 其一","f":"五言律诗","c":["丞相忧宗及，编氓恐祸延。","乾坤正反覆，河洛扰戈鋋。","报主悲无术，伤时秪自怜。","遥知汉社稷，别有中兴年。"]},{"t":"丁未二月上旬四首 其二","f":"五言律诗","c":["厄运虽云极，群公莫自疑。","民心空有望，天道本无知。","野帐留黄屋，青城插皂旗。","燕云旧耆老，宁识汉官仪。"]},{"t":"丁未二月上旬四首 其三","f":"五言律诗","c":["羽檄从天下，于今久未回。","如何半年内，不见一人来。","周室仍遭变，宣王且遇灾。","犹存九庙在，咫尺得祈哀。"]},{"t":"丁未二月上旬四首 其四","f":"五言律诗","c":["主辱臣当死，时危命亦轻。","谋吞豫让炭，肯结仲由缨。","洒血瞻行殿，伤心望虏营。","尚留仪卫否，早晚复神京。"]},{"t":"兵乱寓小巷中作","f":"七言律诗","c":["城北杀人声彻天，城南放火夜烧船。","江河梦断不得往，问君此住何因缘。","窜身穷巷米如玉，翁寻湿薪媪爨粥。","明日开门雪到檐，隔墙更听邻家哭。"]},{"t":"围城中故人多避寇在邻巷者雪晴往访问之坐语既久意亦暂适也","f":"五言古诗","c":["雪泥春既融，晓日初破雾。","出门寻故人，来往不数步。","共谈江南胜，闭眼想去路。","松风被茅屋，稻垄立白鹭。","行看贼围解，春水即可渡。","先当上钟山，次第入庐阜。","生平泉石念，久受尘土污。","况今九死馀，转觉处事误。","豫怀岩壑里，所至陪杖屦。","可行君莫辞，行李我已具。"]},{"t":"城中纪事","f":"五言古诗","c":["生平足艰窘，可叹不可言。","两遭重城闭，再因群盗奔。","今兹所值遇，我岂不与闻。","脱身保儿女，恐辜明主恩。","傍徨不忍去，敢计生理存。","昨者城破日，贼烧东郭门。","中夜半天赤，所忧惊至尊。","是日雪正作，疾风飘大云。","十室九经盗，巨家多见焚。","至今驰道中，但行塞马群。","翠华久不返，魏阙横烟氛。","都人向天泣，欲语声复吞。","我病未即死，尔来春既分。","剥床供晨炊，两眼烟已昏。","岂无好少年，可与共殊勋。","志士或不耻，有身期报君。","塞水须塞源，伐木须伐根。","子莫笑短拙，荆蛮生伍员。"]},{"t":"读易","f":"七言绝句","c":["江北江南公不归，人言公懒笑公痴。","闭门端坐读周易，直过新春围闭时。"]},{"t":"无题","f":"七言绝句","c":["胡虏安知鼎重轻，祸胎元是汉公卿。","襄阳耆旧唯庞老，受禅碑中无姓名。"]},{"t":"怀京师","f":"七言古诗","c":["北风作霜秋已寒，长江浪生船去难。","客愁不断若江水，朝思莫思在长安。","长安城外高十丈，此地岂容胡马傍。","亲见去年城破时，至今铁马黄河上。","小臣位下才则拙，有谋未献空惆怅。","汉家宗庙有神灵，但语胡儿莫狂荡。"]},{"t":"读司马公集解大玄","f":"五言古诗","c":["京城半年围，道路三月病。","轻舟过江来，所向复未定。","客房夜凉冷，气体亦粗胜。","月穿窗罅白，风入桐叶劲。","挑灯读太玄，爱此顷刻静。","物数极三甲，此理本天命。","首赞则分行，故未及世应。","古历汉则亡，易实更三圣。","哀哉杨子云，上与数子竞。","虽云耗心力，固自有捷径。","后来司马公，独敛众说盛。","锱铢判讹谬，一宗蒙是正。","读玄则知易，此实公所證。","如何少年子，便欲献讥评。","我老未知学，读此知不称。","掩卷坐搔首，一洗肝肺净。","明朝寻故人，此语殊未竟。"]},{"t":"黄池西阻风","f":"七言古诗","c":["乌云衔日日不出，骤雨飘风吼三日。","扁舟寸步不得行，坐叹轻鸥如箭疾。","我行去家秋复冬，故园回思春梦中。","客愁茫茫若江水，生计渺渺随征鸿。","三年京城共憔悴，一杯此地难从容。","长溪卷浪雪花碎，远山横空眉黛浓。","故人别我上江去，亦有书来唤同住。","破屋数间君有馀，太仓五升吾已具。","严霜未放鹰隼击，盘涡恐致蛟龙怒。","片帆欲挂任篙师，君但徐行莫深惧。"]},{"t":"景德北窗","f":"五言古诗","c":["云横树阴浓，雨涨溪水白。","故人唤我出，已度蒸暑厄。","北窗非不佳，尚苦眼界窄。","小楼隐床后，自与尘雾隔。","更怜昭亭山，相向有佳色。","君能具鸡黍，略不厌须索。","我能知子穷，子亦能爱客。","人生要如是，一举乃讽百。","我病思远引，未塞交友责。","便当约诸公，归耕作长策。","囊无一钱赢，岁晚会有获。"]},{"t":"昭亭广教寺","f":"五言律诗","c":["故人唤我去，久雨值新晴。","草暗鼯鼠出，山深鶗鴂鸣。","斋厨半盂粥，草具一杯羹。","尚肯频来否，门前春笋生。"]},{"t":"昨日之热一首赠赵彦强","f":"七言古诗","c":["昨日之热未为热，凉风颇随团扇发。","今日之热不可言，西山火炎尘障天。","高楼坚坐若燔炙，常恐秋到无夤缘。","与君相从今几日，欲度一日如长年。","忆昔京城值秋雨，人家邂逅得细语。","不愁归舍少薪米，且喜尊前好宾主。","去年君自云中归，隔巷寻君相劳苦。","是时强虏在城下，耳犹厌听贼营鼓。","岂知丧乱到江南，同向宣城过残暑。","晚来一雨天遂凉，便思约君来对床。","床前适有新酒熟，君醉可舞吾能狂。","醉中谈天亦未妨，回船吴中君勿忙。"]},{"t":"又赠","f":"五言律诗","c":["日日住叠嶂，君能同此游。","黑云才映日，白雨忽穿楼。","盗贼何时定，溪山且自幽。","炎蒸不须厌，俄顷是新秋。"]},{"t":"题泾县水西","f":"五言律诗","c":["江东住已厌，又却过江西。","急雨投泾县，穷秋渡赏溪。","稻田犹少水，山路已多泥。","珍重高僧意，求诗索自题。"]},{"t":"宿秋霜阁后方丈","f":"七言绝句","c":["秋霜阁后山屈蟠，行人冲泥脚未乾。","正是水西佳绝处，不辞风雨夜深寒。"]},{"t":"水西与李彦恢相从余将取旌德趋徽州彦恢先归旌德相候彭元任亦自太平县来相送遇于三溪驿遂同过旌德道中呈二子三首 其一","f":"七言绝句","c":["水西投宿返秋霜，起听晨钟厌束装。","尚惜故人轻作别，乱山深处过重阳。"]},{"t":"水西与李彦恢相从余将取旌德趋徽州彦恢先归旌德相候彭元任亦自太平县来相送遇于三溪驿遂同过旌德道中呈二子三首 其二","f":"七言绝句","c":["村场路僻多无酒，野菊寒深亦未花。","底事中原归不得，又扶衰病过天涯。"]},{"t":"水西与李彦恢相从余将取旌德趋徽州彦恢先归旌德相候彭元任亦自太平县来相送遇于三溪驿遂同过旌德道中呈二子三首 其三","f":"七言绝句","c":["白头懒入少年场，二老追随却味长。","预喜尊前听清话，夜窗相对一炉香。"]},{"t":"休宁县与汪致道诸公别后晚宿黟县界鱼亭驿二首 其一","f":"七言绝句","c":["竹密如云不见天，好山无数簇溪田。","秪应黟县溪山胜，尽在鱼亭驿舍前。"]},{"t":"休宁县与汪致道诸公别后晚宿黟县界鱼亭驿二首 其二","f":"七言绝句","c":["故人相继别休宁，山路篮舆睡复醒。","所恨溪山正佳处，不能同我到鱼亭。"]},{"t":"寄宣城故旧","f":"七言律诗","c":["宣城经岁无它事，尚喜交游不弃遗。","叠嶂楼头纳凉处，宛陵堂下探梅时。","君今尚要一囊粟，我去亦无三径资。","归卧云山更深处，因书频报故人知。"]},{"t":"祁门道中四首 其一","f":"七言绝句","c":["去程归雁两悠悠，行到荒山尽上头。","试问中原何处是，只言东些是宣州。"]},{"t":"祁门道中四首 其二","f":"七言绝句","c":["风落千山雨夜鸣，时因归梦识宣城。","欲知溪路行多少，已过徽州第五程。"]},{"t":"祁门道中四首 其三","f":"七言绝句","c":["宣城人物未全衰，四士风流世不知。","别后略无佳语寄，道中才有数篇诗。"]},{"t":"祁门道中四首 其四","f":"七言绝句","c":["詹郎逸气今谁似，李令清言久不闻。","独立共传摩诘后，隐居还见伯仁孙。"]},{"t":"桂林别珂首座二首 其一","f":"七言绝句","c":["故人相望马牛风，世事波涛滉漾中。","漓水东边两年住，往还才有一珂公。"]},{"t":"桂林别珂首座二首 其二","f":"七言绝句","c":["北归我已办行缠，久约相从却未然。","何处云山堪著子，乱松回首岭南天。"]},{"t":"答赵祖文陈梦授","f":"五言律诗","c":["岭海畏深入，江湖成远游。","犹怀不活怖，少为故人留。","苦乏琼琚报，虚蒙札翰投。","因来问消息，不必计沈浮。"]},{"t":"寄赵十一弟","f":"七言绝句","c":["亲朋虽近懒追寻，湖岭归来病至今。","寄语洪州赵从事，忍令无酒过冬深。"]},{"t":"浮梁道中见小松数寸者极多然皆与蓬蒿杂出不能即长也余伤之作诗寄范四弟","f":"五言古诗","c":["青松数寸根，意出千丈外。","如何蓬蒿底，此志久未遂。","朝为牛羊践，莫受尘土翳。","虽云岁寒姿，当此亦憔悴。","今年虽小出，尚与凡草类。","会须扶其根，与作栋梁计。","大厦千万间，匠石所睥眤。","世或未尽知，慎勿伤汝志。"]},{"t":"自祁门至进贤路中怀旧二绝 其一","f":"五言绝句","c":["雨歇路逾滑，山空鸟不飞。","却思无事日，骑马踏泥归。"]},{"t":"自祁门至进贤路中怀旧二绝 其二","f":"五言绝句","c":["汴水夹榆柳，今留胡马踪。","如何进贤路，只是见青松。"]},{"t":"离洪州渡西江至翠微寺紫清宫","f":"五言古诗","c":["平明渡西江，西山正崔嵬。","中流欲浪作，细雨随风回。","促棹赴前浦，颇为风雨催。","寒沙引细路，人家山半隈。","密雨荫脩竹，久旱无莓苔。","晚入翠微寺，诸峰环抱来。","其西洪崖居，百代所仰怀。","何年蛟龙怒，更击深山开。","悬瀑泻洪井，喷噫藏风雷。","客行少休息，暂此得徘徊。","城中二三老，咫尺不得陪。","岂无陵风翰，邀致山中台。","涧水清且寒，可以当馀杯。","独来不敢久，恐为神物猜。"]},{"t":"宿翠微寺","f":"五言律诗","c":["西山今夜雨，不为故人留。","泥滑淹行李，风声欲送秋。","中原且多事，吾党敢无忧。","明日经由地，江南更几州。"]},{"t":"发翠微寺","f":"七言古诗","c":["古殿突兀风有声，粥鱼欲打鸡三鸣。","披衣起坐问行李，仆夫屡报天阴晴。","昨日路长频雨阻，今日东风得无苦。","杉松连山寒欲动，橘柚隔篱香半吐。","却忆京城无事时，人家打酒夜深归。","醉里不知妻子骂，醒后肯顾儿啼饥。","如今流落长江上，所至盗贼犹旌旗。","已怜吴县风俗僻，况复中原消息稀。"]},{"t":"送宋仲安往虔州","f":"词","c":["已流之水不可以复回，已往之日不可以复来。","唯有野外篱边之黄菊，年年岁岁见花开。","君如此菊不我厌，处处相逢同酒杯。","三年丧乱那可说，君头已白我齿缺。","高才抑塞久未用，坐守松桧凌霜雪。","君今又作章贡游，我犹少忍住筠州。","破屋不忧遭鬼瞰，端坐或恐贻神羞。","求田问舍古所叹，敢有远去惟身谋。","为约岭南三数子，明年乘兴欲东流。"]},{"t":"与仲安别后奉寄","f":"五言古诗","c":["出门送君时，一步再徘徊。","虽云非远别，念与始谋乖。","欲求连墙居，故作千里来。","君今不我待，欲跨洪沟回。","我独滞一方，后会良未谐。","冬初风浪息，蛟龙深蛰雷。","其如中原盗，所至尚扬埃。","子行莫夷犹，恐致狼虎猜。","胡人更远适，畏死投烟霾。","皇天久助顺，似不及吾侪。","独以智力免，宁有此理哉。","因书寄苦语，亦以谢不才。","新春好天色，指望妖氛开。","即当候归艎，取酒寻尊罍。","欣然得一笑，便足禳千灾。","豫章百里远，可以慰客怀。","须君起我病，同上徐孺台。"]},{"t":"题筠州僧房","f":"七言律诗","c":["客来无语坐禅房，共赏西窗一榻凉。","山路雨馀新笋出，江城春色杂花香。","烟厨已逐钟声远，树色初随塔影长。","敢道闲居便安稳，今年更欲下湖湘。"]},{"t":"离筠州","f":"五言律诗","c":["旧日闲居日，无悰已倦游。","如今避地走，不复为山留。","淮甸初经夏，江西复度秋。","今朝小亭望，东北是筠州。"]},{"t":"题圜悟与惇兄法语","f":"七言律诗","c":["杲公昔踏胡马尘，城中草木冻不春。","甲士却立不敢问，其谁从之惇上人。","袖手归来两无语，如今且向江南住。","云居老人费精神，送向高安滩头去。"]},{"t":"建城道中","f":"七言律诗","c":["建城南路入袁州，怪石纵横水乱流。","尽日衣冠在图画，百年心迹付林丘。","中原未作重归计，胡马能令此地忧。","浪迹江湖亦吾分，运筹帷幄有留侯。"]},{"t":"行至醴陵寄故人","f":"五言古诗","c":["浅溪沙碛寒，月白树影疏。","我行天一角，所至尚踌躇。","偶逢胜绝地，不异嵩颍居。","临流遂忘归，默坐数游鱼。","宁知胡马闹，江县已丘墟。","故人亦未来，一旬三寄书。","不必问浅深，但当膏子车。","新霜随北风，惨惨度重湖。","相寻近五岭，慎勿厌长途。"]},{"t":"将至南岳先寄演公禅师善公华严","f":"七言古诗","c":["胡马扬尘烽燧作，我行乃在天一角。","江西趼足过湖南，本赴郴阳故人约。","中途群盗又蜂起，所至往往为囊橐。","迟回改路心自笑，隐忍畏事人所薄。","不因此去渡湘水，更欲何时到南岳。","山中况有二老人，万里同来且安乐。","遥瞻见我应大笑，白须黑面都如昨。","平生故旧几人在，不早从公老丘壑。","自经丧乱可过从，每一思之怀抱恶。","请公更说因地初，一解人间因慧缚。"]},{"t":"避寇南行","f":"七言律诗","c":["何处田园不是家，尽扶衰病过天涯。","山村酒熟人人醉，客路春浓处处花。","敢道岭南无贼马，侧闻江左尚风沙。","囊空甑倒君休笑，亦有新诗伴齿牙。"]},{"t":"贞女峡","f":"五言古诗","c":["欲上贞女峡，江险未敢行。","岂是畏江险，愧此贞女名。","时经丧乱后，世不闻坚贞。","烈士久丧节，丈夫多败盟。","宁闻闺房秀，感义不偷生。","穷荒礼法在，尚此留佳声。","时事有通塞，江流无浊清。","欲行勿惮险，为君先濯缨。"]},{"t":"山水图","f":"七言古诗","c":["君家茅屋低蓬蒿，客来颇厌蛙蚓号。","何得有此山突兀，气压太华陵嵩高。","坐看远涧受悬瀑，似听跬步鸣秋涛。","槎牙老树半枯死，上倚绝壁缘飞猱。","我行日畏盗贼逼，敢厌瘴疠多腥臊。","偶逢坐稳懒归去，豁达眼界无纤毫。","岭南山水固多异，恨无中州清淑气。","对君图障心恍然，便如太华嵩高前。","君但对此能高眠，当有好句令君传。"]},{"t":"连州阳山归路三绝 其一","f":"七言绝句","c":["苍黄避地出连州，邃谷深岩懒转头。","归路始知山水好，少留村驿当闲游。"]},{"t":"连州阳山归路三绝 其三","f":"七言绝句","c":["岭外从来不识春，青梅年后已尝新。","深山忽有残花在，知与清明待北人。"]},{"t":"阳山道中遇大风雨暴寒有感","f":"七言古诗","c":["岭南二月春已尽，百花委弃随风吹。","山前山后绿阴满，已过中原初夏时。","不知何气忽乖沴，风雨夜作雷乘之。","鞭笞宇宙敝日月，万象倒错藏光辉。","岩倾涧绝水府现，捕搏虎豹擒蛟螭。","百围老树不须说，忍冻欲压摧其枝。","峥嵘屋瓦走飞雹，如战初合麾旌旗。","我行避地更值此，闭目但听儿啼饥。","仆夫噤死者数辈，牛马惧不存毛皮。","长途三日断还往，况有鸟雀凌云飞。","只今胡尘暗江路，盗贼往往乘馀威。","良民虽在困须索，四海万里皆疮痍。","天公忍不一顾此，反更震动穷荒为。","此方亦是神所主，我欲告诉心先疑。","明朝风定寒亦解，收召魂魄寻归期。","涧毛自可荐筐筥，试出苦语令神知。"]},{"t":"答朱成伯见赠四首 其一","f":"五言古诗","c":["三年转东南，足迹不得息。","新霜未压瘴，已畏贼马迫。","苍黄度岭去，山路枫叶赤。","慨然念平生，谬自有欣戚。","交游半鬼录，在者费相忆。","朱卿早闻道，一如见旧识。","新诗入要妙，如射已破的。","我行囊贮空，所至但四壁。","岂如投异县，忽枉和氏璧。","斯文得未丧，岂不系人力。","出门仰高山，此道如矢直。"]},{"t":"答朱成伯见赠四首 其二","f":"五言古诗","c":["我适苍梧野，君来洞庭岸。","相逢迫盗贼，一笑未得款。","欣然望眉宇，于我意自满。","天寒道路长，岁晚日晷短。","僧房肯再来，晴窗自妍暖。"]},{"t":"答朱成伯见赠四首 其三","f":"五言律诗","c":["入林恐不远，入山恐不深。","城市有深远，不必在山林。","隋珠不自宝，岂在须渊沈。","断弦得遗谱，千载有知音。"]},{"t":"答朱成伯见赠四首 其四","f":"五言古诗","c":["昔在中朝时，每从贤俊游。","酒酣握手欢，预怀今日忧。","两经岭峤春，三度江湖秋。","朱卿抱奇节，好语忽见收。","我无济世策，君有活国谋。","相寻不相笑，夜光犹暗投。","道丧师友绝，宁有民不偷。","风波极浩渺，欲济能无舟。"]},{"t":"连州行衙水阁望溪西诸山","f":"五言古诗","c":["峤南气常昏，终日如雾隔。","我来已经时，初不辨山色。","纷纷翳犯眼，默默悸动魄。","今晨忽晴快，如语见肝膈。","群峰插天青，野水恣意白。","深窥木杪静，细数鸟道窄。","天心岂无意，直欲慰北客。","才经盗贼扰，更脱瘴疠厄。","湖湘虽未定，势已初夏迫。","颇闻铁骑远，不复更追索。","我归当何时，俗事累千百。","便拟衡山前，今年饱新麦。","忧虑则未已，四海方逼仄。","群公献纳际，或肯任此责。","先当肃区夏，次用及蛮貊。","岂容肆蹂躏，岁必有大获。","天虽未悔祸，世岂无良策。","生人苟未尽，狐兔当有宅。"]},{"t":"赠欧阳处士","f":"七言古诗","c":["爱君年少便知足，今君虽老更无欲。","闭门不出动经时，保此无穷清净福。","黄衣弟子杂僧徒，共守荒郊数椽屋。","门前山水各有态，君但疏篱对脩竹。","直如季路耻有闻，清似之推不言禄。","坐看世事云变化，一任儿曹手反覆。","上皇龙飞三十春，临轩亦尝思异人。","诏书屡下广搜索，当时几人能识真。","君时声名动天子，高卧不起空逡巡。","谩收符箓养丹火，一旦四海生风尘。","我来见君斛岭下，识君无营真静者。","殷勤爱我莫遽行，尚肯相从结茅舍。","时当丧乱足淹留，豺狼恣横空山夜。","它年有意过匡庐，更许渊明入莲社。"]},{"t":"岭外怀宣城旧游","f":"七言律诗","c":["中原未敢说归期，却忆宣城近别离。","叠嶂雨来如画里，敬亭秋入胜花时。","每憎卑湿尤多病，苦爱风光屡有诗。","今日衰颓那可说，鬓须经瘴总成丝。"]},{"t":"余避地踰岭寄书宜章孙氏贼去则尽失之感叹有作","f":"七言律诗","c":["贼马纵横未说归，草间梁上借馀威。","布帆此去应无恙，银盌从来亦解飞。","世事只堪开口笑，主人空有食言肥。","自惭学道工夫少，坐觉文书到眼稀。"]},{"t":"过岭将至江华先寄朱成伯二首 其一","f":"七言绝句","c":["自怪匆匆来往忙，又携儿女过湖湘。","敢言此地能安稳，且道新年离瘴乡。"]},{"t":"过岭将至江华先寄朱成伯二首 其二","f":"七言绝句","c":["岭下微阴已自寒，早行山路觉衣单。","故人见我应惊笑，疾病衰颜怯据鞍。"]},{"t":"端午日北还至斛岭寄连州诸公","f":"五言律诗","c":["岭上逢端午，随家更北征。","隔村闻贼斗，通夕畏蛇行。","厌病初辞瘴，冲泥却胜晴。","犹怜昌歜酒，不与故人倾。"]},{"t":"山居素饭","f":"七言律诗","c":["豆苗可瀹瓠可羹，僧厨午饭蒸香粳。","道人得此清净供，下箸已胜肥羊烹。","平生为腹不为目，偶逢一饱心自足。","晚菘早韭旧所知，五鼎百牢未为福。"]},{"t":"寺居夜起","f":"五言古诗","c":["山深夜无人，竹密风露集。","长空新过雨，尚觉星斗湿。","避地走天涯，如何免拘絷。","朝忧粟囊尽，莫恐贼报急。","荒城兵火后，所至复未葺。","古寺半颓垣，枭啸鬼亦泣。","感事念平生，徘徊近阶立。"]},{"t":"寺居即事三首 其一","f":"五言律诗","c":["瘴疠过庚伏，庶几其少瘳。","甘心忍残暑，指日是清秋。","汴水他年别，郴江此日留。","如何理归梦，只见岭南州。"]},{"t":"寺居即事三首 其二","f":"五言律诗","c":["因循过岭表，忽复到湖南。","气力浑非旧，情怀老不堪。","无钱供痛饮，因病废清谈。","尚有寻书僻，穷搜未免贪。"]},{"t":"寺居即事三首 其三","f":"五言律诗","c":["中原是何处，敢道几时回。","一夏无书读，经时畏贼来。","老松犹偃蹇，病鹤久摧颓。","莫怪论兵少，吾今心已灰。"]},{"t":"赠夏庭别兄弟","f":"七言律诗","c":["披沙拣金勤乃见，读书何止须百遍。","如君心期已不凡，况有长兵可鏖战。","一寒湿薪薰病目，君但读书声彻屋。","僧房夜永灯火足，更肯襆被来同宿。"]},{"t":"贺州闻席大光陈去非诸公将至作诗迎之","f":"七言律诗","c":["五年避地走穷荒，岭海江湖半是乡。","欢喜闻君俱趣召，衰颓如我合深藏。","晓寒已静千山瘴，宿雾先吞万瓦霜。","日日江头望行李，几回驱马度浮梁。"]},{"t":"送周灵运入闽浙","f":"五言古诗","c":["青松著尘市，不辞尘土侵。","忍耻伴桃李，不言归故林。","交游在贫贱，始见平生心。","周侯客异县，屡蒙金玉音。","殷勤不我厌，自昔以至今。","使其少富贵，未必能相寻。","岂谓子诚然，此风今则深。","子欲转岭海，岁暮足愁阴。","路经盗贼窟，往往未就擒。","加鞭策驽马，欲行无滞淫。","故人散天涯，所在亦崎嵚。","相寻倘见及，道我病难任。"]},{"t":"次韵钱逊叔见寄","f":"七言律诗","c":["异时文物汉庭臣，公是中朝第一人。","忍使闲行犯山瘴，不令疾去扫胡尘。","情怀纵老元非病，时运方隆只暂屯。","顾我衰颓已无用，尚烦新语访沈沦。"]},{"t":"赠宗真上人","f":"七言绝句","c":["到处相逢是偶然，浙江湖岭屡经年。","赠君颂子君休笑，我已新来不问禅。"]},{"t":"全州与解子中向伯恭相会","f":"七言律诗","c":["五年流落判西东，尚喜交游一再逢。","但得低头拜东野，不妨下卧见元龙。","中原极目山千叠，往事伤心酒一钟。","如我支离久无用，敢因穷约废过从。"]},{"t":"初至桂州二首 其一","f":"五言古诗","c":["连年走遐方，所至若邮传。","未论道艰阻，先问米贵贱。","贼势来未已，行役我已倦。","解鞍憩空馆，敢叹此异县。","清泉上短绠，一洗尘垢面。","瘴疠非不深，美酝良可恋。"]},{"t":"初至桂州二首 其二","f":"五言古诗","c":["胡沙久冲突，贼马亦驰骛。","我行不得息，终岁在道路。","敢言更多事，尚恐与时忤。","低头访殊俗，何处可放步。","江流下沧海，日惨蛟鳄怒。","出门寻故人，风雨已断渡。"]},{"t":"桂林解后拜见仲古龙图吉父学士别后得两诗书怀奉寄 其一","f":"五言律诗","c":["所至艰危里，如何更别离。","只看山似戟，自合鬓如丝。","汤熨徒增疾，文章不疗饥。","端居温馀论，苦语自成诗。"]},{"t":"桂林解后拜见仲古龙图吉父学士别后得两诗书怀奉寄 其二","f":"五言律诗","c":["折老久高卧，曾乡仍倦游。","同为万里走，肯避数年留。","贼帜江湖晚，岚烟岭峤秋。","相逢得安稳，乘兴莫东流。"]},{"t":"次韵吉父见寄新句","f":"七言律诗","c":["词源久矣多岐路，句法相传共一家。","良贾深藏宜有待，大圭可宝在无瑕。","长江渺渺看秋注，孤骛悠悠伴落霞。","盛欲寄书商榷此，岭南不见雁行斜。"]},{"t":"桂州水西","f":"七言古诗","c":["隆隆而雷风乘之，断霓落日江东西。","江头古寺颇岑寂，僧檐正与南山齐。","我来端坐已寒暑，终日看山默无语。","盗贼连村那敢问，藜苋充肠未为苦。","早禾已旱心所知，正待前山一犁雨。"]},{"t":"断桥","f":"五言律诗","c":["桥断客途少，春深花已休。","闭门尤省事，于世转无求。","来往只诸老，相期非壮游。","欲知身所住，同寓訾家洲。"]},{"t":"赠岭东陈秀才","f":"七言古诗","c":["风吹贺江浪如雪，浮梁左右行人绝。","病夫坐稳懒出行，破屋只愁吹瓦裂。","东县陈卿忽叩门，笑语欢然相暖热。","怪我长贫走道路，所至不安宁有说。","邻州贼报又警急，欲泛扁舟穷百粤。","如君长才亦未用，独守区区负奇节。","未能俯首效儿辈，肯便出门探虎穴。","马群时致千里足，烈士宁无一时杰。","我复何人敢言事，一世摧颓甘短拙。","幸君无事时一过，喜听高谈健其决。","瘴疠参差畏久留，岁月峥嵘惜轻别。"]},{"t":"衡州逢解子中别后奉寄","f":"五言古诗","c":["我来筠水阳，君亦发章贡。","相逢潇湘门，及此兵未动。","卧闻羽书驰，起已行者众。","匆匆不及款，尚辱苦语送。","慨然念平生，相从已如梦。","交游半生死，所至多罅缝。","我衰学不入，君亦老未用。","熟知一世中，有此九鼎重。","子贱则君子，闵子言必中。","师门未遽绝，斯文实天奉。","别离又几日，坐想发孤讽。","衡州逼南岳，湘水寒不冻。","颇传江西扰，盗贼已放纵。","往从田苏游，此乐不得共。"]},{"t":"范县丞惠双鸡","f":"七言绝句","c":["羸病不能除肉味，每逢斋钵愧馀生。","双鸡未可为公膳，留与山僧报五更。"]},{"t":"王抚干失去毛裘","f":"七言律诗","c":["王郎随身一驼裘，偷儿遽作壑失舟。","春初未免霜露迫，岁晚可无迁徙忧。","客房夜坐薪当烛，不怕近江风裂屋。","马平编户更艰难，君行莫忘民号寒。"]},{"t":"四十二弟将还宾州相过夜话","f":"五言律诗","c":["兵戈久未歇，所至转抢攘。","万里逢吾弟，三年走瘴乡。","春风入古寺，夜雨暗浮梁。","尚肯留连否，僧庐可对床。"]},{"t":"呈折仲古四首 其一","f":"七言绝句","c":["市酒酸甜久绝沽，湿薪薰眼坐僧庐。","尚怜诸老无机事，不待愁人折简呼。"]},{"t":"呈折仲古四首 其二","f":"七言绝句","c":["龙阁老翁流落久，如今辛苦去朝天。","向来岭海经行地，分付蛮溪著钓船。"]},{"t":"呈折仲古四首 其三","f":"七言绝句","c":["已无厚禄故人书，尚有相寻长者车。","所至纷然兵火里，不知从此更何如。"]},{"t":"呈折仲古四首 其四","f":"七言绝句","c":["疾病侵凌百不能，只今全是住庵僧。","谢安肯为苍生起，早与吾君了中兴。"]},{"t":"次韵王抚干见惠","f":"七言律诗","c":["新春忽忽到庭除，短褐经寒病却苏。","漫以诗书教儿子，懒将薪水倩童奴。","天涯每觉人情薄，眼界何知风景殊。","万里相逢君莫叹，好山无数簇城隅。"]},{"t":"次韵王漕见赠并寄曾吉父二首 其一","f":"五言律诗","c":["前贤去则远，今代不无人。","小出已无敌，深藏恐未仁。","两章知思苦，一语见情亲。","径欲忘衰病，知公笔有神。"]},{"t":"次韵王漕见赠并寄曾吉父二首 其二","f":"五言律诗","c":["曾子住南国，端居无所思。","逃禅不用酒，投笔谩成诗。","敏捷忘千虑，纵横又一奇。","子中有住处，莫待折肱医。"]},{"t":"次韵折仲古见赠","f":"七言律诗","c":["未有丝毫补县官，几年流转但求安。","江湖自称嵇康懒，故旧空嗟范叔寒。","顾我初无食肉相，喜公复著侍臣冠。","新诗不忘东山志，敢作寻常禁近看。"]},{"t":"再用前韵奉和","f":"七言律诗","c":["自昔支离畏作官，只今犹望一枝安。","饱知时态病良已，心喜故人盟未寒。","所至军书销日月，几回戎马污衣冠。","公归定有安边策，不学愚夫静处看。"]},{"t":"夜坐有感","f":"七言古诗","c":["五更月落鸡未鸣，小炉残火犹晶荧。","道人强起理衰疾，不闻松声闻雨声。","跏趺坐稳百念去，岂有宿梦令神惊。","平生于世万事懒，况复今兹饱忧患。","中原北望四千里，三年不见南飞雁。","著身天涯未为远，所至风沙莫深叹。","时寒但趁僧房火，日暖可赴邻家饭。","岭南无瘴便可老，江头有酒犹堪唤。","嗟哉宁子不自休，辛苦饭牛过夜半。"]},{"t":"送密上人归江西","f":"五言古诗","c":["轻舟君先行，羸马我已往。","湖山已在望，南岳行可仰。","不忧盗贼繁，渐喜草木长。","密也负奇气，少已离尘网。","饱参诸方禅，所至被称赏。","独留末后句，未肯休吾党。","经寻卓锥地，更足以自养。","囊空脚颇健，体俭心甚广。","喜谈江西胜，妙处犹指掌。","未见频寄书，悠然发遐想。"]},{"t":"送常子正赴召二首 其一","f":"五言律诗","c":["属者闻居久，今来促召频。","但能消党论，便足扫胡尘。","众水同归海，殊涂必问津。","如何彼黠虏，敢谓汉无人。"]},{"t":"送常子正赴召二首 其二","f":"五言律诗","c":["疾病老逾剧，交亲穷转疏。","惟公不改旧，怪我未安居。","日月干戈里，江山瘴疠馀。","南行见李白，亦莫问何如。"]},{"t":"颂送山上人游南华","f":"七言绝句","c":["三浙三衢未说归，且从岭路访曹溪。","卢公若问南来事，但道江湖尽鼓鼙。"]},{"t":"山颂送谭师直归湖南","f":"五言律诗","c":["人事日翻覆，昔同今不然。","于心苟有用，与世自无缘。","剩结官田社，饱参云盖禅。","已胜高鸟尽，徒泛五湖船。"]},{"t":"送能化主还法轮","f":"七言绝句","c":["岭外三年避贼忙，法轮元不下禅床。","君归却说岭南事，瘴暑作时君自凉。"]},{"t":"送夏少曾兄弟","f":"七言律诗","c":["处处人家避贼忙，数因行李问舟航。","江横晚照凫鸥乱，春到空山草木香。","我未有缘离岭峤，君今决策下湖湘。","定知此去添贫病，不及相从气味长。"]},{"t":"本中将为江浙之行念当与梦贶远别感叹伤怀因成长句奉呈","f":"五言古诗","c":["客行已无聊，况此忧虑集。","颓然念远役，未见勇可习。","虚庭觉气润，远视萤火湿。","故人不我厌，踏雨相劳揖。","朝餐共饥饱，夜语同坐立。","问我去此邦，何用如此急。","干戈与瘴疠，未见可出入。","何殊知二五，而不知有十。","俛首谢勤意，此非愚所及。","天涯重离别，所至方嶪岌。","感怀平生旧，忍效儿女泣。","风沙蔽中原，道路满荆棘。","世事古则然，临分莫于邑。"]},{"t":"赠日者张直夫","f":"七言律诗","c":["因循避世不求名，潦倒江湖过一生。","贾谊定能寻季主，子云先已识君平。","独行市肆口无语，懒踏权门身自轻。","看甑生尘只坚坐，世间宁有不平鸣。"]},{"t":"永州西亭","f":"五言古诗","c":["旧闻西亭胜，独盛湘湖间。","山秀水亦好，千里在凭栏。","今来乃不然，眼境故未宽。","环城但浊水，满目唯荒山。","如何柳司马，肯为此解颜。","始知忧虑久，方觉所遇安。","我从避地来，山水亦饫观。","初不厌岭峤，况敢嫌荆蛮。","徘徊念昔人，亦作故意看。","所惭二三子，来不倦跻攀。","开轩纳微凉，共享一日闲。","说诗到雅颂，论文参诰盘。","快若箭破的，圆如坂下丸。","此乐固可乐，此盟安得寒。","天暑畏道路，时危安阻难。","相逢得少款，莫问何时还。","何须待杯酒，始尽平生欢。"]},{"t":"浯溪","f":"七言古诗","c":["五月行人汗如雨，意绪昏昏杂尘土。","浯溪一见中兴碑，便有清风濯烦暑。","中兴之业诚艰难，敢作汉武周宣看。","纷然大历上元间，文恬武嬉主则孱。","但知追咎一禄山，袖手不作如旁观。","天亦未使庸夫干，故生李郭在人间。","一时节士张许颜，其谁不知唐已安。","道州落笔风雨寒，鲁公大书镇百蛮。","诃叱水怪摧神奸，有臣若此亡所叹。","而不能使君心还，我来转岭逾千盘。","对此凛然清肺肝，想见群小遭讥弹。","尔曹何心犹诞谩，至今怒发常冲冠。"]},{"t":"送元上人归禾山","f":"词","c":["长嚣而寂，方作而息。","如射破的，初不以力。","子居深山，又处绝顶。","避嚣不作，二事俱屏。","往来临川，道里且千。","一见我喜，如旧交然。","我欲属子，重于发言。","子请则坚，之子之贤。","遍寻诸方，不主先入。","唯是之从，何拘何执。","惟昔善财，我曹之师。","其心广大，谁能间之。","山高海深，德则不孤。","不深不高，培塿潢污。","奚必深山，惟静之守。","求寂念息，以阅永久。"]},{"t":"赠一上人","f":"七言律诗","c":["偶从岭峤转江东，得向疏山见一公。","所至共游常草草，尔来相遇更匆匆。","晁郎埋骨虚无里，璧老收声苍莽中。","二十馀年往还事，半随秋雁落寒空。"]},{"t":"赠圭公杲公四首 其一","f":"五言律诗","c":["北归住江西，尘事日窘束。","两公时踵门，高谊已绝俗。","空房拥残火，更许相就宿。","不嫌寒无毡，肯厌饭脱粟。"]},{"t":"赠圭公杲公四首 其二","f":"五言律诗","c":["杲公玉壶冰，所至自清净。","圭公出林鹤，肯与鸡骛竞。","吾穷得两公，颇觉意气盛。","未能出艰危，犹足起衰病。"]},{"t":"赠圭公杲公四首 其三","f":"五言律诗","c":["杲固昔所熟，圭亦旧闻名。","江西一聚首，遂宽南去程。","扫除文字习，追寻香火盟。","期君向此道，隐若一长城。"]},{"t":"赠圭公杲公四首 其四","f":"五言律诗","c":["堂头老居士，我识盖自早。","声名从少年，闭户今却扫。","公能为少留，尚可慰枯槁。","欲知主人贤，但看此二老。"]},{"t":"次韵钱逊叔清江图后二首 其一","f":"词","c":["公但一室坚坐，我方万里生还。","共作十年清梦，同寻五岭名山。"]},{"t":"次韵钱逊叔清江图后二首 其二","f":"词","c":["作清江三两曲，胜大厦千万间。","若保此中安坐，不必中原遽还。"]},{"t":"次韵钱逊叔独鹤图三首 其一","f":"七言绝句","c":["长颈竦身懒不前，此宁有望更腾鶱。","懿公爱尔非无意，要压曹人三百轩。"]},{"t":"次韵钱逊叔独鹤图三首 其二","f":"七言绝句","c":["粉墨半销翎翅短，正如衰发不胜簪。","可怜少保功名误，写此凌云意不堪。"]},{"t":"次韵钱逊叔独鹤图三首 其三","f":"七言绝句","c":["眼明见此出笼鹤，似我北归辞瘴岚。","慎勿低头待收养，人间欣戚尽朝三。"]},{"t":"次韵钱逊叔画图","f":"七言古诗","c":["西风著人尘满襟，江山纵近难追寻。","当年写此数幅妙，坐使几案频登临。","断云黤惨出古寺，远岸杳霭连荒岑。","渔舟荡漾江路晚，烟雨濛笼山店阴。","已知落笔气象古，一任世间消息沈。","最怜霜干倚长石，不待岁久成枯林。","知公此中兴不浅，此画故能留意深。","只今燕坐一室里，尚费从来长短吟。","诗成掩卷坐秋晚，一唱三叹求遗音。"]},{"t":"送一上人","f":"五言古诗","c":["我齿久已摇，君发日向白。","相逢不相笑，共被老境迫。","周旋三十年，近岁多间隔。","伊昔无事时，日夕望颜色。","此道要琢磨，苦语费思索。","不能如宿心，每负朋友责。","别我宁陵县，随我昭德宅。","所期无二三，可恨已千百。","交游大半死，况值兵火厄。","举首望八荒，无乃天地窄。","凉风吹秋深，江湖动行客。","谁能于此时，出语见肝膈。","胡尘蔽中原，盗贼暗阡陌。","公其无遽行，待我有良策。"]},{"t":"钱逊叔诸公赋石鼓文请同作","f":"七言古诗","c":["江头羽书相续来，城中草木冻不开。","腐儒坐视了无策，但守寒炉吹死灰。","我公送我石鼓文，令我琢句要春回。","簸荡风云走蛟蜃，百虫久蛰闻惊雷。","钱公自是力扛鼎，持此浮游转湖岭。","汉碑秦篆已么么，况复钟王敢驰骋。","后来颇供儿女弄，神物有知当远屏。","石鼓之文公所知，正是周室中兴时。","庶几我皇亦如此，一扫狂虏随风飞。","石鼓之文尚可读，小臣愿继车攻诗。"]},{"t":"和邢子坚韵","f":"七言律诗","c":["万里重归旧秃翁，笑谈聊复与君同。","鹪鹩所愿一枝足，鼯鼠从来五技穷。","短发自梳浑欲白，残炉因客尚能红。","正须混迹师元亮，未忍低头学敬通。"]},{"t":"戏呈东林云间二老","f":"七言律诗","c":["几年湖岭费追寻，尚喜归来听足音。","御虎已知吾有命，问禅方见子无心。","风尘黤惨病如昨，岁月峥嵘穷至今。","犹觉相逢有馀恨，老盆盛酒不同斟。"]},{"t":"佛日纵步相寻索归甚苦戏成绝句","f":"七言绝句","c":["相逢不用苦相催，只到更深月上回。","莫怪室空无侍者，夜窗相对有寒梅。"]},{"t":"东林圭云门杲将如雪峰因成长韵奉送","f":"五言古诗","c":["东风被泽国，君有千里行。","送君不能远，宿昔春水生。","胡马污中原，旁淮多贼城。","即今江南岸，盗贼犹纵横。","颇闻闽粤静，农民方及耕。","雪峰佳主人，况欲屣履迎。","两公与谈道，正欲平其衡。","但见演若头，自然心地明。","云何未览镜，便欲其流清。","君行可语此，勿忧儿女惊。","鄙夫牙齿缺，苦遭尘事撄。","七年忧奔走，一饱费经营。","野鹤出笼飞，尚须完翅翎。","今者与君别，故乡他日情。","新诗见万一，庶用托同盟。"]},{"t":"赠童尧询蔡楠谢敏行","f":"五言古诗","c":["七年避胡尘，无复少年事。","适从岭外归，眼病不识字。","尚幸戎马间，得见此数士。","蔡童南城杰，所养盖有自。","两谢名家子，学已前作似。","相逢眼暂明，已足慰迟暮。","如何舍我去，使我起千虑。","江深羽檄繁，况此日月骛。","犹馀大谢留，与我相近住。","风霜渺墟落，泥土暗道路。","得无经此别，各复走他处。","期君则甚远，苦语不厌屡。","微言恐遂绝，其谁与调护。","要当发愤求，不欲侥倖遇。","圣门极坦平，渠自有回互。","河清倘有期，未死或可俟。"]},{"t":"和范仲熊舜元游橘园见梅","f":"七言律诗","c":["橘林经雨未全衰，归路人家已见梅。","风物粗知江左胜，瘴烟新离岭南来。","笔头有眼方知妙，句里忘言始绝埃。","但得一寒无事过，与公还往胜衔杯。"]},{"t":"答钱逊叔","f":"七言古诗","c":["北风吹霜夜如雪，江城草木冻欲折。","病夫袖手无所为，一坐临川已三月。","忽蒙妙句起衰惫，顿觉和气生毛发。","公能忘机我亦倦，不待曼殊见摩诘。","画图是非久未解，况保长年不磨灭。","请公置画莫多求，要与时人除爱渴。"]},{"t":"与钱逊叔饮酒分韵得鸟字","f":"五言古诗","c":["客游等浮萍，岁事如过鸟。","逢公得一笑，不厌古寺悄。","雨声喧客耳，烛影吹半袅。","宿酲未及解，更觉恶韵扰。","时方足艰虞，身未识要妙。","如何一杯酒，便出万物表。","别公愿一言，使我意易了。"]}]};